macro_rules! tri {
    ($zh:literal, $en:literal $(, $arg:expr)* $(,)?) => {
        if i18n::is_en() {
            format!($en $(, $arg)*)
        } else {
            format!($zh $(, $arg)*)
        }
    };
}
