/// 右侧栏宽度（会话详情栏、经典壳右栏、设置详情栏都以此为准）。
///
/// 曾经企微壳用 `PANEL_WIDTH.max(260.)` = 260，而撑窗口用的是 320，
/// 导致「窗口涨 320、面板只占 260」，多出的 60 被会话列吃掉。
pub const PANEL_WIDTH: f32 = 320.0;

/// 主窗口最小尺寸（窗口系统层）。侧栏展开时以此为基础加宽，
/// 保证左侧名单 / 中间会话的宽度不变。
const WINDOW_MIN_W: f32 = 900.0;
const WINDOW_MIN_H: f32 = 600.0;

/// 打开 / 收起右侧栏时调整窗口宽度。
///
/// 规则（用户要的语义）：**面板展开永远不挤压其它模块**。
/// 所以「展开」= 窗口无条件加宽「面板自身宽度」，「收起」= 还原到展开前。
///
/// 这里刻意不做「已经很宽就不撑」的优化：那会让「1400 宽时开面板」
/// 反而把会话列从 1093 挤到 758——和需求直接冲突。
fn panel_target_width(
    current: f32,
    opening: bool,
    restore: Option<f32>,
    panel: f32,
) -> Option<f32> {
    const SLACK: f32 = 2.;
    if opening {
        Some(current + panel)
    } else {
        // 收起：还原到展开前的宽度。
        let restore = restore?;
        if (restore - current).abs() < SLACK {
            return None;
        }
        Some(restore)
    }
}

/// 应用 `panel_target_width` 的结果（最大化/全屏时不改窗口）。
fn apply_panel_width(window: &mut Window, target: Option<f32>) {
    let Some(target) = target else {
        return;
    };
    if window.is_maximized() || window.is_fullscreen() {
        return;
    }
    let bounds = window.bounds();
    let current = f32::from(bounds.size.width);
    if (target - current).abs() < 1. {
        return;
    }
    let height = f32::from(bounds.size.height);
    window.resize(size(px(target), px(height)));
}

const TITLEBAR_HEIGHT: f32 = 28.0;
/// transcript 每次渲染的消息窗口（「显示更早」按同样步长增大）。
const TRANSCRIPT_WINDOW: usize = 120;

/// 本地 UI 偏好文件（与主题共用 prefs.json，保留既有键）。
fn ui_prefs_path() -> std::path::PathBuf {
    crate::instance::state_dir().join("prefs.json")
}

/// 侧栏最多固定几个设置页（再多会挤压底部齿轮和导航）。
const MAX_PINNED_SETTINGS: usize = 5;

fn load_ui_prefs() -> (HashSet<String>, bool, Vec<usize>, bool) {
    let Ok(bytes) = std::fs::read(ui_prefs_path()) else {
        return (HashSet::new(), false, Vec::new(), false);
    };
    let value: serde_json::Value = serde_json::from_slice(&bytes).unwrap_or_else(|_| serde_json::json!({}));
    let muted = value
        .get("muted")
        .and_then(|value| value.as_array())
        .map(|items| {
            items
                .iter()
                .filter_map(|item| item.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();
    let topmost = value
        .get("topmost")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    let pinned: Vec<usize> = value
        .get("pinned_settings")
        .and_then(|value| value.as_array())
        .map(|items| {
            items
                .iter()
                .filter_map(|item| item.as_u64().map(|n| n as usize))
                .collect()
        })
        .unwrap_or_default();
    // 设置页扩容时旧下标整体后移：
    // v1→v2：团队记忆插在「群聊」之后（>=6 +1）；
    // v2→v3：浏览器/电脑操控插在「更多」之前（>=15 +2）。
    let layout = value
        .get("settings_layout")
        .and_then(|value| value.as_u64())
        .unwrap_or(1);
    let pinned = migrate_pinned_settings(&pinned, layout);
    // 守卫必须跟着迁移表的**目标版本**走：加了 v3->v4 之后这里还是 `< 3`，
    // 导致 layout=3 的用户迁移结果永远不落盘（只活在内存里）。
    if layout < 4 {
        let mut migrated = value.clone();
        migrated["pinned_settings"] = serde_json::json!(pinned);
        migrated["settings_layout"] = serde_json::json!(4);
        let _ = atomic_file::write_json_atomic(
            &ui_prefs_path(),
            &migrated,
            &atomic_file::WriteOptions::default(),
        );
    }
    // 右栏默认收起：中栏能拿到 894px，长文可读性最好；需要时点标题栏展开。
    let right_panel_open = value
        .get("right_panel_open")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    (
        muted,
        topmost,
        normalize_pinned_settings(&pinned),
        right_panel_open,
    )
}

/// 设置页布局版本迁移。
///
/// - v1→v2：团队记忆插入到 6，其后 +1
/// - v2→v3：浏览器/电脑操控插入到 15/16，其后 +2
/// - v3→v4：Bot 与群聊合并为「Bot团队」，群里归到 4，其后 -1
fn migrate_pinned_settings(items: &[usize], layout: u64) -> Vec<usize> {
    let mut out = items.to_vec();
    if layout < 2 {
        out = out
            .iter()
            .map(|&item| if item >= 6 { item + 1 } else { item })
            .collect();
    }
    if layout < 3 {
        out = out
            .iter()
            .map(|&item| if item >= 15 { item + 2 } else { item })
            .collect();
    }
    if layout < 4 {
        out = out
            .iter()
            .map(|&item| match item {
                // 群聊(5) 并入 Bot团队(4)
                5 => 4,
                // 6.. 整体前移一位
                n if n >= 6 => n - 1,
                n => n,
            })
            .collect();
    }
    out
}

/// 去重、去掉越界页与内嵌页（浏览器/电脑操控，见下方 `settings_page_in_nav`）、截断到上限；保持用户添加顺序。
fn normalize_pinned_settings(items: &[usize]) -> Vec<usize> {
    let mut out = Vec::new();
    for &item in items {
        if item < SETTINGS_PAGES.len() && settings_page_in_nav(item) && !out.contains(&item) {
            out.push(item);
            if out.len() == MAX_PINNED_SETTINGS {
                break;
            }
        }
    }
    out
}

fn load_ui_bool(key: &str, default: bool) -> bool {
    std::fs::read(ui_prefs_path())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
        .and_then(|value| value.get(key).and_then(serde_json::Value::as_bool))
        .unwrap_or(default)
}

/// 只改一个布尔偏好，保留 prefs.json 其它键。
fn save_ui_bool(key: &str, enabled: bool) {
    let path = ui_prefs_path();
    let mut value = std::fs::read(&path)
        .ok()
        .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
        .unwrap_or_else(|| serde_json::json!({}));
    if !value.is_object() {
        value = serde_json::json!({});
    }
    value[key] = serde_json::json!(enabled);
    let _ = atomic_file::write_json_atomic(&path, &value, &atomic_file::WriteOptions::default());
}

fn save_ui_value(key: &str, value: serde_json::Value) {
    let path = ui_prefs_path();
    let mut root = std::fs::read(&path)
        .ok()
        .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())
        .unwrap_or_else(|| serde_json::json!({}));
    if !root.is_object() {
        root = serde_json::json!({});
    }
    root[key] = value;
    let _ = atomic_file::write_json_atomic(&path, &root, &atomic_file::WriteOptions::default());
}

fn parse_hex_color(value: &str) -> Option<gpui::Rgba> {
    let hex = value.trim().trim_start_matches('#');
    if hex.len() != 6 {
        return None;
    }
    let channel = |start: usize| u8::from_str_radix(&hex[start..start + 2], 16).ok();
    Some(gpui::Rgba {
        r: channel(0)? as f32 / 255.0,
        g: channel(2)? as f32 / 255.0,
        b: channel(4)? as f32 / 255.0,
        a: 1.0,
    })
}

fn color_hex(color: gpui::Rgba) -> String {
    format!(
        "#{:02x}{:02x}{:02x}",
        (color.r * 255.0).round() as u8,
        (color.g * 255.0).round() as u8,
        (color.b * 255.0).round() as u8
    )
}

fn load_accent_pref() -> Option<gpui::Rgba> {
    let value = std::fs::read(ui_prefs_path())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok())?;
    parse_hex_color(value.get("accent")?.as_str()?)
}

fn load_motion_pref() -> &'static str {
    let value = std::fs::read(ui_prefs_path())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok());
    match value
        .as_ref()
        .and_then(|value| value.get("motion"))
        .and_then(serde_json::Value::as_str)
    {
        Some("quiet") => "quiet",
        Some("lively") => "lively",
        _ => "normal",
    }
}

fn load_lang_pref() -> &'static str {
    let value = std::fs::read(ui_prefs_path())
        .ok()
        .and_then(|bytes| serde_json::from_slice::<serde_json::Value>(&bytes).ok());
    if value
        .as_ref()
        .and_then(|value| value.get("lang"))
        .and_then(serde_json::Value::as_str)
        == Some("en")
    {
        "en"
    } else {
        "zh"
    }
}

