    /// 问题卡的自由输入：默认只显示一行链接，点开才出现输入框（不占常驻高度）。
    fn question_free_row(&self, request_id: String, cx: &mut Context<Self>) -> gpui::AnyElement {
        if self.question_free_active.as_deref() == Some(request_id.as_str()) {
            let submit_id = request_id.clone();
            return div()
                .w_full()
                .flex()
                .items_center()
                .gap(px(6.))
                .child(
                    div()
                        .flex_1()
                        .min_w(px(0.))
                        .h(px(32.))
                        .rounded(px(theme::RADIUS_FIELD))
                        .border_1()
                        .border_color(theme::edge())
                        .bg(theme::card())
                        .px(px(8.))
                        .child(self.question_free_input.clone()),
                )
                .child(
                    div()
                        .id(SharedString::from(format!(
                            "question-free-submit-{request_id}"
                        )))
                        .h(px(32.))
                        .px(px(12.))
                        .rounded(px(theme::RADIUS_FIELD))
                        .bg(wechat_theme::send_enabled())
                        .flex()
                        .items_center()
                        .pointer()
                        .hover(|style| style.opacity(0.9))
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            let text = this
                                .question_free_input
                                .read(cx)
                                .content()
                                .trim()
                                .to_string();
                            if text.is_empty() {
                                this.toast(i18n::t("请输入回答"), cx);
                                return;
                            }
                            this.answer_question(submit_id.clone(), Some(text), cx);
                        }))
                        .child(
                            div()
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(12.))
                                .line_height(px(16.))
                                .text_color(wechat_theme::nav_text_active())
                                .child(i18n::t("提交")),
                        ),
                )
                .into_any_element();
        }
        let active_id = request_id;
        div()
            .id(SharedString::from(format!("question-free-{active_id}")))
            .h(px(24.))
            .px(px(2.))
            .flex()
            .items_center()
            .pointer()
            .hover(|style| style.opacity(0.85))
            .on_click(cx.listener(move |this, _event, _window, cx| {
                this.question_free_active = Some(active_id.clone());
                cx.notify();
            }))
            .child(
                div()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(12.))
                    .line_height(px(16.))
                    .text_color(wechat_theme::time_label())
                    .child(i18n::t("其他（自行输入）")),
            )
            .into_any_element()
    }

    /// ACP elicitation 表单：多题并排，提交后回填 content；取消 = decline。
    fn elicitation_cards(&self, cx: &mut Context<Self>) -> Vec<gpui::AnyElement> {
        let Some(key) = self.active_key() else {
            return Vec::new();
        };
        let Some(chat) = self.chats.get(&key) else {
            return Vec::new();
        };
        chat.elicitations
            .iter()
            .map(|pending| self.elicitation_card_el(pending, cx))
            .collect()
    }

    fn elicitation_card_el(
        &self,
        pending: &PendingElicitation,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let card = &pending.card;
        let request_id = card.request_id.clone();
        let sent = pending.sent;
        let mut fields = div().flex().flex_col().gap(px(10.));
        if sent {
            fields = fields.child(
                div()
                    .font_family(theme::FONT_FAMILY)
                    .text_size(px(11.))
                    .text_color(theme::ink_tertiary())
                    .child(i18n::t("已提交，等待 Agent 继续…")),
            );
        } else {
            for field in &card.fields {
                let mut block = div()
                    .flex()
                    .flex_col()
                    .gap(px(4.))
                    .child(
                        div()
                            .font_family(theme::FONT_FAMILY)
                            .text_size(px(12.))
                            .text_color(theme::ink())
                            .child(SharedString::from(format!(
                                "{}{}",
                                field.title,
                                if field.required { " *" } else { "" }
                            ))),
                    );
                match &field.kind {
                    ElicitationFieldKind::Text
                    | ElicitationFieldKind::Number { .. }
                    | ElicitationFieldKind::TextList => {
                        if matches!(field.kind, ElicitationFieldKind::TextList) {
                            block = block.child(settings_note(i18n::t("多个值用逗号或换行分隔")));
                        }
                        if let Some(input) = pending.texts.get(&field.key) {
                            block = block.child(input.clone());
                        }
                    }
                    ElicitationFieldKind::Single(options) => {
                        let mut chips = div().flex().flex_wrap().gap(px(6.));
                        for (index, (value, label)) in options.iter().enumerate() {
                            let selected = pending.single.get(&field.key) == Some(value);
                            let value = value.clone();
                            let field_key = field.key.clone();
                            let request = request_id.clone();
                            chips = chips.child(
                                div()
                                    .id(SharedString::from(format!(
                                        "elicit-{request_id}-{}-{index}",
                                        field.key
                                    )))
                                    .h(px(26.))
                                    .rounded(px(theme::RADIUS_FIELD))
                                    .border_1()
                                    .border_color(if selected {
                                        theme::accent()
                                    } else {
                                        theme::edge()
                                    })
                                    .bg(if selected {
                                        theme::selected()
                                    } else {
                                        theme::card()
                                    })
                                    .px(px(9.))
                                    .flex()
                                    .items_center()
                                    .pointer()
                                    .hover(|style| style.bg(theme::hover()))
                                    .on_click(cx.listener(move |this, _event, _window, cx| {
                                        this.elicit_select(
                                            &request,
                                            &field_key,
                                            value.clone(),
                                            false,
                                            cx,
                                        );
                                    }))
                                    .child(
                                        div()
                                            .font_family(theme::FONT_FAMILY)
                                            .text_size(px(11.))
                                            .text_color(theme::ink_secondary())
                                            .child(SharedString::from(label.clone())),
                                    ),
                            );
                        }
                        block = block.child(chips);
                    }
                    ElicitationFieldKind::Multi(options) => {
                        let mut chips = div().flex().flex_wrap().gap(px(6.));
                        let picked = pending.multi.get(&field.key).cloned().unwrap_or_default();
                        for (index, (value, label)) in options.iter().enumerate() {
                            let selected = picked.contains(value);
                            let value = value.clone();
                            let field_key = field.key.clone();
                            let request = request_id.clone();
                            chips = chips.child(
                                div()
                                    .id(SharedString::from(format!(
                                        "elicit-{request_id}-{}-{index}",
                                        field.key
                                    )))
                                    .h(px(26.))
                                    .rounded(px(theme::RADIUS_FIELD))
                                    .border_1()
                                    .border_color(if selected {
                                        theme::accent()
                                    } else {
                                        theme::edge()
                                    })
                                    .bg(if selected {
                                        theme::selected()
                                    } else {
                                        theme::card()
                                    })
                                    .px(px(9.))
                                    .flex()
                                    .items_center()
                                    .pointer()
                                    .hover(|style| style.bg(theme::hover()))
                                    .on_click(cx.listener(move |this, _event, _window, cx| {
                                        this.elicit_select(
                                            &request,
                                            &field_key,
                                            value.clone(),
                                            true,
                                            cx,
                                        );
                                    }))
                                    .child(
                                        div()
                                            .font_family(theme::FONT_FAMILY)
                                            .text_size(px(11.))
                                            .text_color(theme::ink_secondary())
                                            .child(SharedString::from(label.clone())),
                                    ),
                            );
                        }
                        block = block.child(chips);
                    }
                    ElicitationFieldKind::Boolean => {
                        let mut chips = div().flex().gap(px(6.));
                        for (value, label) in [("true", i18n::t("是")), ("false", i18n::t("否"))] {
                            let selected = pending.single.get(&field.key).map(String::as_str)
                                == Some(value);
                            let value = value.to_string();
                            let field_key = field.key.clone();
                            let request = request_id.clone();
                            chips = chips.child(
                                div()
                                    .id(SharedString::from(format!(
                                        "elicit-{request_id}-{}-{value}",
                                        field.key
                                    )))
                                    .h(px(26.))
                                    .rounded(px(theme::RADIUS_FIELD))
                                    .border_1()
                                    .border_color(if selected {
                                        theme::accent()
                                    } else {
                                        theme::edge()
                                    })
                                    .bg(if selected {
                                        theme::selected()
                                    } else {
                                        theme::card()
                                    })
                                    .px(px(12.))
                                    .flex()
                                    .items_center()
                                    .pointer()
                                    .hover(|style| style.bg(theme::hover()))
                                    .on_click(cx.listener(move |this, _event, _window, cx| {
                                        this.elicit_select(
                                            &request,
                                            &field_key,
                                            value.clone(),
                                            false,
                                            cx,
                                        );
                                    }))
                                    .child(
                                        div()
                                            .font_family(theme::FONT_FAMILY)
                                            .text_size(px(11.))
                                            .text_color(theme::ink_secondary())
                                            .child(i18n::t(label)),
                                    ),
                            );
                        }
                        block = block.child(chips);
                    }
                }
                fields = fields.child(block);
            }
            let request = request_id.clone();
            fields = fields.child(
                div()
                    .flex()
                    .justify_end()
                    .gap(px(8.))
                    .child(
                        div()
                            .id(SharedString::from(format!("elicit-decline-{request_id}")))
                            .h(px(28.))
                            .rounded_full()
                            .border_1()
                            .border_color(theme::edge())
                            .bg(theme::card())
                            .px(px(12.))
                            .flex()
                            .items_center()
                            .pointer()
                            .hover(|style| style.bg(theme::hover()))
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                this.answer_elicitation(request.clone(), None, cx);
                            }))
                            .child(
                                div()
                                    .font_family(theme::FONT_FAMILY)
                                    .text_size(px(12.))
                                    .text_color(theme::ink_secondary())
                                    .child(i18n::t("取消")),
                            ),
                    )
                    .child(
                        div()
                            .id(SharedString::from(format!("elicit-submit-{request_id}")))
                            .h(px(28.))
                            .rounded_full()
                            .bg(ui_accent())
                            .px(px(12.))
                            .flex()
                            .items_center()
                            .pointer()
                            .hover(|style| style.opacity(0.85))
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                this.submit_elicitation(request_id.clone(), cx);
                            }))
                            .child(
                                div()
                                    .font_family(theme::FONT_FAMILY)
                                    .text_size(px(12.))
                                    .line_height(px(16.))
                                    .font_weight(gpui::FontWeight::MEDIUM)
                                    .text_color(theme::accent_ink())
                                    .child(i18n::t("提交")),
                            ),
                    ),
            );
        }

        div()
            .w_full()
            .max_w(px(960.))
            .mx_auto()
            .mb(px(14.))
            .flex_shrink_0()
            .rounded(px(theme::RADIUS_CARD))
            .border_1()
            .border_color(ui_accent())
            .bg(theme::card())
            .p(px(12.))
            .flex()
            .flex_col()
            .gap(px(8.))
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(8.))
                    .child(
                        div()
                            .font_family(theme::FONT_FAMILY)
                            .text_size(px(13.))
                            .line_height(px(18.))
                            .font_weight(gpui::FontWeight::SEMIBOLD)
                            .text_color(theme::ink())
                            .child(i18n::t("Bot 提问 · 填写表单")),
                    )
                    .child(div().flex_1())
                    .children(member_label(&card.member)),
            )
            .children((!card.message.is_empty()).then(|| {
                div()
                    .font_family(theme::FONT_FAMILY)
                    .text_size(px(12.))
                    .line_height(px(16.))
                    .text_color(theme::ink_secondary())
                    .child(SharedString::from(card.message.clone()))
            }))
            .child(fields)
            .into_any_element()
    }

    fn elicit_select(
        &mut self,
        request_id: &str,
        field_key: &str,
        value: String,
        multi: bool,
        cx: &mut Context<Self>,
    ) {
        let Some(key) = self.active_key() else {
            return;
        };
        let Some(chat) = self.chats.get_mut(&key) else {
            return;
        };
        let Some(pending) = chat
            .elicitations
            .iter_mut()
            .find(|pending| pending.card.request_id == request_id)
        else {
            return;
        };
        if pending.sent {
            return;
        }
        if multi {
            let picked = pending.multi.entry(field_key.to_string()).or_default();
            if let Some(index) = picked.iter().position(|item| item == &value) {
                picked.remove(index);
            } else {
                picked.push(value);
            }
        } else {
            pending.single.insert(field_key.to_string(), value);
        }
        cx.notify();
    }

    fn submit_elicitation(&mut self, request_id: String, cx: &mut Context<Self>) {
        let Some(key) = self.active_key() else {
            return;
        };
        let built = {
            let Some(chat) = self.chats.get(&key) else {
                return;
            };
            let Some(pending) = chat
                .elicitations
                .iter()
                .find(|pending| pending.card.request_id == request_id)
            else {
                return;
            };
            if pending.sent {
                return;
            }
            let card = pending.card.clone();
            let mut problem = None;
            for field in &card.fields {
                let text = pending
                    .texts
                    .get(&field.key)
                    .map(|input| input.read(cx).content().trim().to_string())
                    .unwrap_or_default();
                let answered = match &field.kind {
                    ElicitationFieldKind::Text
                    | ElicitationFieldKind::Number { .. }
                    | ElicitationFieldKind::TextList => !text.is_empty(),
                    ElicitationFieldKind::Single(_) | ElicitationFieldKind::Boolean => {
                        pending.single.contains_key(&field.key)
                    }
                    ElicitationFieldKind::Multi(_) => pending
                        .multi
                        .get(&field.key)
                        .is_some_and(|values| !values.is_empty()),
                };
                if field.required && !answered {
                    problem = Some(tri!("请先回答：{}", "Please answer: {}", field.title));
                    break;
                }
                if let ElicitationFieldKind::Number { integer } = &field.kind
                    && !text.is_empty()
                {
                    let valid = if *integer {
                        text.parse::<i64>().is_ok()
                    } else {
                        text.parse::<f64>().is_ok()
                    };
                    if !valid {
                        let kind = if *integer { i18n::t("整数") } else { i18n::t("数字") };
                        problem = Some(tri!("{} 需要{}", "{} must be {}", field.title, kind));
                        break;
                    }
                }
            }
            if problem.is_some() {
                (problem, None)
            } else {
                let mut content = ElicitationContent::new();
                for field in &card.fields {
                    let text = pending
                        .texts
                        .get(&field.key)
                        .map(|input| input.read(cx).content().trim().to_string())
                        .unwrap_or_default();
                    let value = match &field.kind {
                        ElicitationFieldKind::Text => {
                            (!text.is_empty()).then_some(ElicitationValue::Text(text.clone()))
                        }
                        ElicitationFieldKind::Number { integer } => {
                            if text.is_empty() {
                                None
                            } else if *integer {
                                text.parse::<i64>()
                                    .ok()
                                    .map(ElicitationValue::Integer)
                            } else {
                                text.parse::<f64>()
                                    .ok()
                                    .map(ElicitationValue::Number)
                            }
                        }
                        ElicitationFieldKind::TextList => {
                            let items: Vec<String> = text
                                .split([',', '，', '\n'])
                                .map(str::trim)
                                .filter(|item| !item.is_empty())
                                .map(str::to_string)
                                .collect();
                            (!items.is_empty()).then_some(ElicitationValue::List(items))
                        }
                        ElicitationFieldKind::Single(_) => pending
                            .single
                            .get(&field.key)
                            .cloned()
                            .map(ElicitationValue::Text),
                        ElicitationFieldKind::Multi(_) => pending
                            .multi
                            .get(&field.key)
                            .filter(|values| !values.is_empty())
                            .cloned()
                            .map(ElicitationValue::List),
                        ElicitationFieldKind::Boolean => pending
                            .single
                            .get(&field.key)
                            .map(|value| ElicitationValue::Bool(value == "true")),
                    };
                    if let Some(value) = value {
                        content.insert(field.key.clone(), value);
                    }
                }
                (None, Some(content))
            }
        };
        match built {
            (Some(message), _) => self.toast(message, cx),
            (None, Some(content)) => {
                self.answer_elicitation(request_id, Some(content), cx);
            }
            _ => {}
        }
    }

    fn answer_elicitation(
        &mut self,
        request_id: String,
        content: Option<ElicitationContent>,
        cx: &mut Context<Self>,
    ) {
        let Some(key) = self.active_key() else {
            return;
        };
        let Some(chat) = self.chats.get_mut(&key) else {
            return;
        };
        let Some(pending) = chat
            .elicitations
            .iter_mut()
            .find(|pending| pending.card.request_id == request_id)
        else {
            return;
        };
        if pending.sent {
            return;
        }
        pending.sent = true;
        chat.status = i18n::t("提交回答…").to_string();
        self.backend.answer_elicitation(key, request_id, content);
        cx.notify();
    }

    /// 审批卡同问题卡：支持多张并存，卡头标注归属成员。
    fn approval_cards(&self, cx: &mut Context<Self>) -> Vec<gpui::AnyElement> {
        let Some(key) = self.active_key() else {
            return Vec::new();
        };
        let Some(chat) = self.chats.get(&key) else {
            return Vec::new();
        };
        chat.permissions
            .iter()
            .map(|pending| self.approval_card_el(pending, cx))
            .collect()
    }

    fn approval_card_el(
        &self,
        pending: &PendingApproval,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let prompt = &pending.prompt;
        let request_id = prompt.request_id.clone();
        let sent = pending.sent;
        let risk = if prompt.risk.is_empty() {
            String::new()
        } else {
            let label = match prompt.risk.as_str() {
                "exec" => tri!("执行", "Execute"),
                "write" => tri!("写入", "Write"),
                "read" => tri!("读取", "Read"),
                other => other.to_string(),
            };
            tri!("风险 {}", "Risk {}", label)
        };

        let mut options = div().flex().flex_col().gap(px(6.));
        if sent {
            options = options.child(
                div()
                    .font_family(theme::FONT_FAMILY)
                    .text_size(px(11.))
                    .text_color(theme::ink_tertiary())
                    .child(i18n::t("已提交，等待 Agent 确认…")),
            );
        } else {
            for (index, option) in prompt.options.iter().enumerate() {
                let kind = option.kind.clone();
                let option_id = option.option_id.clone();
                let request_id_click = request_id.clone();
                let (bg, border, fg) = match kind.as_str() {
                    "deny" => (theme::card(), theme::edge(), theme::danger()),
                    _ => (theme::raised(), theme::edge(), theme::ink()),
                };
                options = options.child(
                    div()
                        .id(SharedString::from(format!(
                            "approval-opt-{}-{}",
                            request_id, index
                        )))
                        .h(px(36.))
                        .w_full()
                        .rounded(px(theme::RADIUS_FIELD))
                        .border_1()
                        .border_color(border)
                        .bg(bg)
                        .px(px(10.))
                        .flex()
                        .items_center()
                        .gap(px(8.))
                        .pointer()
                        .hover(|style| style.opacity(0.88))
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            this.resolve_permission(request_id_click.clone(), option_id.clone(), cx);
                        }))
                        .child(
                            div()
                                .w(px(16.))
                                .flex_shrink_0()
                                .font_family(theme::FONT_FAMILY)
                                .text_size(px(12.))
                                .text_color(theme::ink_tertiary())
                                .child(SharedString::from(format!("{}.", index + 1))),
                        )
                        .child(
                            div()
                                .font_family(theme::FONT_FAMILY)
                                .text_size(px(13.))
                                .line_height(px(18.))
                                .font_weight(gpui::FontWeight::MEDIUM)
                                .text_color(fg)
                                .child(SharedString::from(i18n::owned(approval_option_label(
                                    &kind,
                                    &option.label,
                                )))),
                        ),
                );
            }
        }

        div()
            .w_full()
            .max_w(px(560.))
            .mx_auto()
            .mb(px(14.))
            .flex_shrink_0()
            .rounded(px(theme::RADIUS_MENU))
            .border_1()
            .border_color(theme::edge())
            .bg(theme::card())
            .shadow(theme::shadow_3())
            .p(px(12.))
            .flex()
            .flex_col()
            .gap(px(8.))
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(8.))
                    .child(
                        div()
                            .font_family(theme::FONT_FAMILY)
                            .text_size(px(13.))
                            .line_height(px(18.))
                            .font_weight(gpui::FontWeight::MEDIUM)
                            .text_color(theme::ink_secondary())
                            .child(i18n::t("需要你的确认")),
                    )
                    .child(div().flex_1())
                    .children(member_label(&prompt.member))
                    .children((!risk.is_empty()).then(|| {
                        div()
                            .rounded(px(theme::RADIUS_TAG))
                            .bg(theme::hover())
                            .px(px(6.))
                            .py(px(2.))
                            .font_family(theme::FONT_FAMILY)
                            .text_size(px(ui_kit::T_LABEL))
                            .text_color(theme::ink_tertiary())
                            .child(risk)
                    })),
            )
            .child(
                div()
                    .font_family(theme::FONT_FAMILY)
                    .text_size(px(12.))
                    .line_height(px(16.))
                    .text_color(theme::ink_secondary())
                    .child(SharedString::from(format!(
                        "{} · {}",
                        i18n::t("工具"),
                        prompt.tool_name
                    ))),
            )
            .children((!prompt.reason.is_empty()).then(|| {
                // 写入类审批直接给 diff 预览；其余工具仍走通用参数解析。
                if tool_render::family(&prompt.tool_name) == tool_render::ToolFamily::Edit
                    && let Some(info) = tool_render::edit_info(
                        &prompt.tool_name,
                        &prompt.reason,
                        "",
                    )
                {
                    return div()
                        .flex()
                        .flex_col()
                        .gap(px(4.))
                        .children((!info.path.is_empty()).then(|| {
                            div()
                                .font_family(theme::FONT_MONO)
                                .text_size(px(12.))
                                .line_height(px(16.))
                                .text_color(theme::ink_secondary())
                                .child(SharedString::from(info.path.clone()))
                        }))
                        .child(edit_diff_panel(&info, ""))
                        .into_any_element();
                }
                approval_reason_view(&prompt.reason)
            }))
            .child(options)
            .into_any_element()
    }

    /// Esc：只关一层，顺序与视觉层级一致（后开的先关）。
    fn on_close_overlay(&mut self, _: &CloseOverlay, window: &mut Window, cx: &mut Context<Self>) {
        debug_action("CloseOverlay");
        // IME 组合中 Esc 是「取消候选」，不能顺手关掉当前浮层。
        if self.ime_composing(cx) {
            return;
        }
        if self.chat_find.is_some() {
            self.chat_find = None;
            self.pending_find_scroll = false;
            cx.notify();
            return;
        }
        if self.new_menu_open {
            self.new_menu_open = false;
            cx.notify();
            return;
        }
        if self.settings_dropdown.is_some() {
            self.settings_dropdown = None;
            cx.notify();
            return;
        }
        if self.permission_menu.is_some() {
            self.permission_menu = None;
            cx.notify();
            return;
        }
        if self.mention_context(cx).is_some() {
            self.mention_dismissed = true;
            cx.notify();
            return;
        }
        if self.image_preview.is_some() {
            self.image_preview = None;
        } else if self.palette.is_some() {
            self.palette = None;
        } else if self.find_dialog.is_some() {
            self.find_dialog = None;
        } else if self.me_card_open {
            self.me_card_open = false;
            return;
        } else if self.detail_menu_open {
            self.close_detail_menu(window, cx);
            return;
        } else if self.footer_menu_open {
            self.footer_menu_open = false;
            return;
        } else if self.settings_open && self.settings_detail.is_some() {
            // 详情面板：Esc 只收起面板，不关设置。
            self.settings_detail = None;
            self.settings_detail_input = None;
            self.settings_detail_error = None;
            self.settings_focus.focus(window, cx);
        } else if self.settings_open && (self.im_create.is_some() || self.im_qr_page.is_some()) {
            // IM 子页面：Esc 只返回上级页，不直接关设置。
            if self.im_qr_page.take().is_none() {
                self.im_create = None;
            }
            self.settings_focus.focus(window, cx);
        } else if self.settings_open {
            self.settings_open = false;
        } else if self.search_open {
            self.search_open = false;
            let search = self.search_input.clone();
            search.update(cx, |input, cx| input.set_content("", cx));
        } else {
            // 没有浮层可关：不动草稿，也不抢输入框焦点。
            return;
        }
        // 关掉最后一层后把焦点还给输入框：浮层（菜单/搜索/对话框）可能持有过焦点，
        // 元素一消失焦点就悬空，之后打字会全部静默丢失。
        self.refocus_composer_if_clear(window, cx);
        cx.notify();
    }

    /// 没有浮层时把焦点交给输入框（多用于 Esc 逐层关闭之后）。
    fn refocus_composer_if_clear(&self, window: &mut Window, cx: &mut Context<Self>) {
        let clear = self.palette.is_none()
            && self.find_dialog.is_none()
            && !self.detail_menu_open
            && !self.settings_open
            && !self.search_open;
        if clear {
            let handle = self.input.read(cx).focus_handle(cx);
            handle.focus(window, cx);
        } else if self.settings_open {
            // 设置窗口还开着：把焦点收回设置卡，别让它悬在刚关闭的子对话框上。
            self.settings_focus.clone().focus(window, cx);
        }
    }

    /// kit AlertDialog 关闭后不会自动恢复焦点；on_close 里统一还给输入框/设置卡。
    /// 关闭当帧对话框还在退场动画里，焦点会被浮层盖住，所以延后一帧再还。
    fn dialog_focus_restore(&self, cx: &mut Context<Self>) -> DialogFocusRestore {
        let weak = cx.weak_entity();
        std::rc::Rc::new(move |_, window, cx| {
            Self::defer_focus_restore(weak.clone(), window, cx);
        })
    }

    /// 延后一帧恢复焦点（程序化 close_dialog 不触发 on_close 时也要调用）。
    fn defer_focus_restore(weak: gpui::WeakEntity<Self>, window: &mut Window, cx: &mut App) {
        window.defer(cx, move |window, cx| {
            let _ = weak.update(cx, |this, cx| this.refocus_composer_if_clear(window, cx));
        });
    }

    /// Ctrl+N：与右栏「新会话」同一条路径（仅私聊；群聊没有新会话语义）。
    fn on_new_session_shortcut(
        &mut self,
        _: &NewSessionShortcut,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        debug_action("NewSessionShortcut");
        self.new_session_for_selected(cx);
    }

    /// Q-05：默认壳标题栏的「新会话」按钮与 Ctrl+N 共用这一份逻辑。
    ///
    /// 只在这里保留「生成中不换会话」的守卫（原 `on_new_session_shortcut` 有，
    /// `detail-new-session` 的闭包版没有），并把旧会话入历史后立刻落盘。
    fn new_session_for_selected(&mut self, cx: &mut Context<Self>) {
        let Some(bot) = self.selected_bot().cloned() else {
            return;
        };
        let key = bot_key(&bot.id);
        if self
            .chats
            .get(&key)
            .is_some_and(|chat| chat.streaming)
        {
            // 生成中不换会话：先 Stop 或等回合结束。
            return;
        }
        if let Some(chat) = self.chats.get(&key)
            && let Some(old_id) = chat.session_id.clone()
        {
            self.sessions.push_history(&bot.id, &old_id);
            self.sessions.save();
        }
        self.chats.remove(&key);
        let workspace = if bot.directory.trim().is_empty() {
            backend::fallback_workspace().to_string_lossy().into_owned()
        } else {
            bot.directory.clone()
        };
        self.backend
            .new_session(
                key,
                workspace,
                bot.identity(),
                bot.model.clone(),
                self.sessions.engine_of(&bot.id).map(str::to_string),
            );
        cx.notify();
    }

