    /// Ctrl+F：打开会话全文搜索（输入即查，命中按会话去重）。
    fn on_find_shortcut(&mut self, _: &FindShortcut, window: &mut Window, cx: &mut Context<Self>) {
        debug_action("FindShortcut");
        if self.find_dialog.is_some() {
            return;
        }
        let input = cx.new(|cx| SimpleInput::new(i18n::t("搜索历史消息…"), theme::ink_tertiary, cx));
        // 每次输入变化就重查（本地库、limit 8；不足 2 字由 search_messages 自己挡掉）。
        cx.observe(&input, |this: &mut Self, input, cx| {
            let query = input.read(cx).content().to_string();
            // 结果集变了，高亮回到第一条。
            this.find_selected = 0;
            this.find_seq = this.find_seq.wrapping_add(1);
            let seq = this.find_seq;
            // 真机会话库能到 GB 级：LIKE 扫描放在后台线程，再做 120ms 防抖，
            // 过期结果用序号丢弃（不能阻塞 UI 线程，否则输入一个字卡一次）。
            cx.spawn(async move |this, cx| {
                cx.background_executor()
                    .timer(Duration::from_millis(120))
                    .await;
                let fresh = this
                    .update(cx, |this, _| this.find_seq == seq)
                    .unwrap_or(false);
                if !fresh {
                    return;
                }
                let results = cx
                    .background_executor()
                    .spawn(async move {
                        // 旧会话库 + 当前 pi-rust JSONL 两路合并；JSONL 覆盖全部新会话。
                        let mut results = session_db::search_messages(&query, 8);
                        let remaining = 8usize.saturating_sub(results.len());
                        if remaining > 0 {
                            results.extend(crate::rpi_engine::search_sessions(&query, remaining));
                        }
                        results.sort_by_key(|hit| std::cmp::Reverse(hit.at));
                        results.truncate(8);
                        results
                    })
                    .await;
                let _ = this.update(cx, |this, cx| {
                    let results: Vec<_> = results
                        .into_iter()
                        .filter(|hit| !this.is_private_session(&hit.session_id))
                        .collect();
                    if this.find_seq == seq
                        && let Some(dialog) = this.find_dialog.as_mut()
                    {
                        dialog.results = results;
                        cx.notify();
                    }
                });
            })
            .detach();
            cx.notify();
        })
        .detach();
        let handle = input.read(cx).focus_handle(cx);
        handle.focus(window, cx);
        self.find_dialog = Some(FindState {
            input,
            results: Vec::new(),
        });
        self.find_selected = 0;
        self.find_seq = self.find_seq.wrapping_add(1);
        cx.notify();
    }

    /// 会话内查找：只搜当前 transcript 的正文消息。
    fn open_chat_find(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(key) = self.active_key() else {
            return;
        };
        let input = cx.new(|cx| {
            SimpleInput::new(i18n::t("在当前会话中查找…"), theme::ink_tertiary, cx)
        });
        cx.observe(&input, |this: &mut Self, input, cx| {
            if let Some(find) = this.chat_find.as_mut() {
                find.query = input.read(cx).content().to_string();
            }
            this.recompute_chat_find();
            this.pending_find_scroll = true;
            cx.notify();
        })
        .detach();
        let handle = input.read(cx).focus_handle(cx);
        handle.focus(window, cx);
        self.chat_find = Some(ChatFindState {
            key,
            input,
            query: String::new(),
            matches: Vec::new(),
            current: 0,
        });
        self.pending_find_scroll = false;
        cx.notify();
    }

    fn recompute_chat_find(&mut self) {
        let Some(find) = self.chat_find.as_mut() else {
            return;
        };
        let needle = find.query.trim().to_lowercase();
        if needle.is_empty() {
            find.matches.clear();
            find.current = 0;
            return;
        }
        if let Some(chat) = self.chats.get(&find.key) {
            find.matches = chat
                .messages
                .iter()
                .enumerate()
                .filter(|(_, message)| {
                    message.kind == MsgKind::Text
                        && message.text.to_lowercase().contains(&needle)
                })
                .map(|(index, _)| index)
                .collect();
        } else {
            find.matches.clear();
        }
        find.current = 0;
    }

    fn chat_find_step(&mut self, delta: isize, cx: &mut Context<Self>) {
        let Some(find) = self.chat_find.as_mut() else {
            return;
        };
        if find.matches.is_empty() {
            return;
        }
        let len = find.matches.len() as isize;
        find.current = ((find.current as isize + delta).rem_euclid(len)) as usize;
        self.pending_find_scroll = true;
        cx.notify();
    }

    /// 隐私 Bot 的当前/历史会话：全局搜索不展示。
    fn is_private_session(&self, session_id: &str) -> bool {
        self.roster.bots.iter().filter(|bot| bot.is_private).any(|bot| {
            self.sessions.get(&bot.id).as_deref() == Some(session_id)
                || self
                    .sessions
                    .history_of(&bot.id)
                    .iter()
                    .any(|id| id == session_id)
        })
    }

    /// 搜索命中属于谁（私聊 Bot / 群聊成员）。
    /// 找出某个 session 属于谁。
    ///
    /// 返回 `(Selection, 命中的群成员 id)`：群成员会话要带上成员 id，
    /// 否则 UI 只能切到群、定位不到具体成员。
    fn find_owner_of_session(&self, session_id: &str) -> Option<(Selection, Option<String>)> {
        for (index, bot) in self.roster.bots.iter().enumerate() {
            if self.sessions.get(&bot.id).as_deref() == Some(session_id)
                || self
                    .sessions
                    .history_of(&bot.id)
                    .iter()
                    .any(|id| id == session_id)
            {
                return Some((Selection::Bot(index), None));
            }
        }
        for (index, group) in self.roster.groups.iter().enumerate() {
            for member_id in &group.member_ids {
                let slot = backend::member_session_key(&group_key(&group.id), member_id);
                if self.sessions.get(&slot).as_deref() == Some(session_id) {
                    return Some((Selection::Group(index), Some(member_id.clone())));
                }
            }
        }
        None
    }

    fn on_find_next(&mut self, _: &FindNext, _window: &mut Window, cx: &mut Context<Self>) {
        let count = self
            .find_dialog
            .as_ref()
            .map(|dialog| dialog.results.len())
            .unwrap_or(0);
        if count == 0 {
            return;
        }
        self.find_selected = (self.find_selected + 1) % count;
        cx.notify();
    }

    fn on_find_prev(&mut self, _: &FindPrev, _window: &mut Window, cx: &mut Context<Self>) {
        let count = self
            .find_dialog
            .as_ref()
            .map(|dialog| dialog.results.len())
            .unwrap_or(0);
        if count == 0 {
            return;
        }
        self.find_selected = (self.find_selected + count - 1) % count;
        cx.notify();
    }

    fn on_mention_next(&mut self, _: &MentionNext, _window: &mut Window, cx: &mut Context<Self>) {
        if let Some((_, names)) = self.mention_context(cx) {
            let count = names.len();
            self.mention_selected = (self.mention_selected + 1) % count;
            cx.notify();
        }
    }

    fn on_mention_prev(&mut self, _: &MentionPrev, _window: &mut Window, cx: &mut Context<Self>) {
        if let Some((_, names)) = self.mention_context(cx) {
            let count = names.len();
            self.mention_selected = (self.mention_selected + count - 1) % count;
            cx.notify();
        }
    }

    fn on_focus_next(&mut self, _: &FocusNext, window: &mut Window, cx: &mut Context<Self>) {
        window.focus_next(cx);
    }

    fn on_focus_prev(&mut self, _: &FocusPrev, window: &mut Window, cx: &mut Context<Self>) {
        window.focus_prev(cx);
    }

    fn on_find_open(&mut self, _: &FindOpen, _window: &mut Window, cx: &mut Context<Self>) {
        if self.ime_composing(cx) {
            return;
        }
        let Some(hit) = self
            .find_dialog
            .as_ref()
            .and_then(|dialog| dialog.results.get(self.find_selected))
            .cloned()
        else {
            return;
        };
        self.jump_to_hit(&hit, cx);
    }

    /// 跳到搜索结果：私聊直接切到那个会话；群聊成员会话切群后再把
    /// 命中成员那一行滚到可见位置。
    fn jump_to_hit(&mut self, hit: &session_db::SearchHit, cx: &mut Context<Self>) {
        let session_id = hit.session_id.clone();
        // JSONL 历史会话可能不在当前 Bot 的会话映射里（不同 Bot/旧槽位）：退回当前
        // 选中的 Bot 打开它，否则用户只能看到搜索结果却点不动。
        let found = self.find_owner_of_session(&session_id);
        // 群成员会话：切到群之后要把该成员的输出行滚到可见位置。
        let jump_member = found.as_ref().and_then(|(_, member)| member.clone());
        let owner = found.map(|(selection, _)| selection).or(match self.selection {
            selection @ Some(Selection::Bot(_)) => selection,
            _ => None,
        });
        match owner {
            Some(Selection::Bot(index)) => {
                let Some(bot) = self.roster.bots.get(index).cloned() else {
                    return;
                };
                let key = bot_key(&bot.id);
                let is_current = self
                    .chats
                    .get(&key)
                    .and_then(|chat| chat.session_id.as_deref())
                    == Some(session_id.as_str());
                self.selection = Some(Selection::Bot(index));
                if is_current {
                    self.find_dialog = None;
                    cx.notify();
                    return;
                }
                if let Some(chat) = self.chats.get(&key)
                    && let Some(current) = chat.session_id.clone()
                    && current != session_id
                {
                    self.sessions.push_history(&bot.id, &current);
                    self.sessions.save();
                }
                if let Some(chat) = self.chats.get_mut(&key) {
                    chat.messages.clear();
                    chat.streaming_index = None;
                    chat.tool_index.clear();
                    chat.member_stream.clear();
                    chat.streaming = false;
                    chat.permissions.clear();
                    chat.questions.clear();
                    chat.elicitations.clear();
                    chat.session_id = None;
                    chat.ready = false;
                    chat.status = i18n::t("切换会话…").to_string();
                }
                let workspace = if bot.directory.trim().is_empty() {
                    backend::fallback_workspace().to_string_lossy().into_owned()
                } else {
                    bot.directory.clone()
                };
                self.backend.switch_session(
                    key,
                    workspace,
                    bot.identity(),
                    bot.model.clone(),
                    bot.id.clone(),
                    session_id,
                    self.sessions.engine_of(&bot.id).map(str::to_string),
                );
                self.find_dialog = None;
                self.scroll.scroll_to_bottom();
                cx.notify();
            }
            Some(Selection::Group(index)) => {
                self.find_dialog = None;
                self.select_group(index, cx);
                // 命中群成员会话时，把该成员的输出行滚到可见位置。
                if let Some(member_id) = jump_member
                    && let Some(group) = self.roster.groups.get(index)
                {
                    let gkey = group_key(&group.id);
                    let member_name = self
                        .roster
                        .bot_by_id(&member_id)
                        .map(|bot| bot.name.clone());
                    if let Some(name) = member_name
                        && let Some(chat) = self.chats.get(&gkey)
                        && let Some(pos) = chat.member_stream.get(&name).copied()
                    {
                        self.scroll.scroll_to_item(pos);
                    }
                }
            }
            None => {
                // 名册里找不到归属（旧会话/已删 Bot）：只关闭对话框。
                self.find_dialog = None;
                cx.notify();
            }
        }
    }

    /// 命令面板的候选（静态动作 + 当前名册里的 Bot/群聊）。
    fn palette_entries(&self) -> Vec<(String, String, PaletteCmd)> {
        let mut entries = vec![
            (i18n::t("新建 Bot").to_string(), "Ctrl+B".to_string(), PaletteCmd::NewBot),
            (i18n::t("编辑当前 Bot").to_string(), "Ctrl+E".to_string(), PaletteCmd::EditBot),
            (i18n::t("新建群聊").to_string(), "Ctrl+G".to_string(), PaletteCmd::NewChannel),
            (i18n::t("新会话").to_string(), "Ctrl+N".to_string(), PaletteCmd::NewSession),
            (
                i18n::t("旁路会话").to_string(),
                i18n::t("不写入主会话").to_string(),
                PaletteCmd::SideChat,
            ),
            (i18n::t("搜索历史消息").to_string(), "Ctrl+F".to_string(), PaletteCmd::FindMessages),
            (i18n::t("选择运行时").to_string(), String::new(), PaletteCmd::PickModel),
            (i18n::t("审批白名单").to_string(), String::new(), PaletteCmd::EditAllowlist),
            (i18n::t("立即压缩").to_string(), String::new(), PaletteCmd::Compact),
            (i18n::t("打开设置").to_string(), "Ctrl+,".to_string(), PaletteCmd::OpenSettings),
        ];
        for (index, bot) in self.roster.bots.iter().enumerate() {
            entries.push((
                tri!("切换到 {}", "Switch to {}", bot.name),
                bot.role.clone(),
                PaletteCmd::SelectBot(index),
            ));
        }
        for (index, group) in self.roster.groups.iter().enumerate() {
            entries.push((
                tri!("切换到 {}", "Switch to {}", group.name),
                i18n::t("群聊").to_string(),
                PaletteCmd::SelectGroup(index),
            ));
        }
        entries
    }

    /// 按输入过滤（不区分大小写，全部关键词都要命中）。
    fn filtered_palette(&self, cx: &App) -> Vec<(String, String, PaletteCmd)> {
        let query = self
            .palette
            .as_ref()
            .map(|palette| palette.input.read(cx).content().trim().to_lowercase())
            .unwrap_or_default();
        let mut entries = self.palette_entries();
        if !query.is_empty() {
            entries.retain(|(label, hint, _)| {
                let haystack = format!("{} {}", label, hint).to_lowercase();
                query.split_whitespace().all(|part| haystack.contains(part))
            });
        }
        entries.truncate(10);
        entries
    }

    fn on_palette_shortcut(
        &mut self,
        _: &PaletteShortcut,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        debug_action("PaletteShortcut");
        if self.palette.is_some() {
            self.palette = None;
            cx.notify();
            return;
        }
        let input = cx.new(|cx| SimpleInput::new(i18n::t("输入命令…"), theme::ink_tertiary, cx));
        cx.observe(&input, |_, _, cx| cx.notify()).detach();
        let handle = input.read(cx).focus_handle(cx);
        handle.focus(window, cx);
        self.palette = Some(PaletteState {
            input,
            selected: 0,
        });
        cx.notify();
    }

    fn on_palette_prev(&mut self, _: &PalettePrev, _window: &mut Window, cx: &mut Context<Self>) {
        debug_action("PalettePrev");
        let count = self.filtered_palette(cx).len();
        if count == 0 {
            return;
        }
        if let Some(palette) = self.palette.as_mut() {
            palette.selected = if palette.selected == 0 {
                count - 1
            } else {
                palette.selected - 1
            };
        }
        cx.notify();
    }

    fn on_palette_next(&mut self, _: &PaletteNext, _window: &mut Window, cx: &mut Context<Self>) {
        debug_action("PaletteNext");
        let count = self.filtered_palette(cx).len();
        if count == 0 {
            return;
        }
        if let Some(palette) = self.palette.as_mut() {
            palette.selected = (palette.selected + 1) % count;
        }
        cx.notify();
    }

    fn on_palette_submit(&mut self, _: &PaletteSubmit, window: &mut Window, cx: &mut Context<Self>) {
        debug_action("PaletteSubmit");
        if self.ime_composing(cx) {
            return;
        }
        let Some(palette) = self.palette.as_ref() else {
            return;
        };
        let index = palette.selected;
        let entries = self.filtered_palette(cx);
        let Some((_, _, command)) = entries.get(index).cloned() else {
            return;
        };
        self.palette = None;
        self.run_palette_command(command, window, cx);
        cx.notify();
    }

    /// 执行命令面板的一项（关面板由调用方保证）。
    fn run_palette_command(
        &mut self,
        command: PaletteCmd,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        match command {
            PaletteCmd::NewBot => self.open_new_dialog(cx),
            PaletteCmd::EditBot => {
                if let Some(bot) = self.selected_bot() {
                    let bot_id = bot.id.clone();
                    self.open_edit_dialog(bot_id, cx);
                }
            }
            PaletteCmd::NewChannel => self.open_new_group_dialog(cx),
            PaletteCmd::NewSession => {
                // 行为与 Ctrl+N 等价，但是独立实现（守卫 + history + save）：去重记 v0.6。
                if let Some(bot) = self.selected_bot().cloned() {
                    let key = bot_key(&bot.id);
                    if !self.chats.get(&key).is_some_and(|chat| chat.streaming) {
                        if let Some(chat) = self.chats.get(&key)
                            && let Some(old_id) = chat.session_id.clone()
                        {
                            self.sessions.push_history(&bot.id, &old_id);
                            self.sessions.save();
                        }
                        self.chats.remove(&key);
                        let workspace = if bot.directory.trim().is_empty() {
                            backend::fallback_workspace().to_string_lossy().into_owned()
                        } else {
                            bot.directory.clone()
                        };
                        self.backend.new_session(
                            key,
                            workspace,
                            bot.identity(),
                            bot.model.clone(),
                            self.sessions.engine_of(&bot.id).map(str::to_string),
                        );
                        cx.notify();
                    }
                }
            }
            PaletteCmd::SideChat => {
                // 旁路会话跟着当前选中的 Bot 走（私聊面板同样只开侧栏小窗）。
                if self.selected_bot().is_some() {
                    self.open_side("", window, cx);
                }
            }
            PaletteCmd::FindMessages => {
                // 打开搜索要有 window 才能聚焦输入框：交给下一帧渲染处理。
                self.pending_find = true;
                cx.notify();
            }
            PaletteCmd::OpenSettings => {
                self.open_settings_at(self.settings_tab, window, cx);
                cx.notify();
            }
            PaletteCmd::PickModel => {
                if let Some(bot) = self.selected_bot() {
                    self.settings_detail = Some(SettingsDetail::Model {
                        bot_id: bot.id.clone(),
                    });
                    self.settings_detail_input = None;
                    self.settings_open = true;
                }
                cx.notify();
            }
            PaletteCmd::Compact => {
                if let Some(key) = self.active_key() {
                    self.backend.compact(key);
                    self.toast(i18n::t("正在压缩上下文…"), cx);
                } else {
                    self.toast(i18n::t("先选一个会话"), cx);
                }
                cx.notify();
            }
            PaletteCmd::EditAllowlist => {
                if let Some(bot) = self.selected_bot() {
                    self.settings_detail = Some(SettingsDetail::Allowlist {
                        bot_id: bot.id.clone(),
                    });
                    self.settings_detail_entries.clear();
                    self.settings_detail_input = None;
                    self.settings_open = true;
                }
                cx.notify();
            }
            PaletteCmd::SelectBot(index) => self.select_bot(index, cx),
            PaletteCmd::SelectGroup(index) => self.select_group(index, cx),
        }
    }

    /// 左栏条目线性顺序：Bot（名册顺序）在前、群聊在后。
    fn step_selection(&mut self, delta: isize, cx: &mut Context<Self>) {
        let bots = self.roster.bots.len();
        let groups = self.roster.groups.len();
        let total = bots + groups;
        if total == 0 {
            return;
        }
        let current = match self.selection {
            Some(Selection::Bot(index)) => index as isize,
            Some(Selection::Group(index)) => (bots + index) as isize,
            None => -1,
        };
        // 从「无选中」出发：↓ 落到第一个，↑ 落到最后一个。
        let next = if current < 0 {
            if delta >= 0 { 0 } else { total as isize - 1 }
        } else {
            (current + delta).rem_euclid(total as isize)
        };
        if (next as usize) < bots {
            self.select_bot(next as usize, cx);
        } else if let Some(index) = (next as usize).checked_sub(bots) {
            self.select_group(index, cx);
        }
    }

    fn on_select_next(&mut self, _: &SelectNextItem, _window: &mut Window, cx: &mut Context<Self>) {
        debug_action("SelectNextItem");
        self.step_selection(1, cx);
    }

    fn on_select_prev(&mut self, _: &SelectPrevItem, _window: &mut Window, cx: &mut Context<Self>) {
        debug_action("SelectPrevItem");
        self.step_selection(-1, cx);
    }

    /// 批准：优先 allowAlways/allowOnce，其次任意非 deny 选项。
    fn on_approve_allow(&mut self, _: &ApproveAllow, _window: &mut Window, cx: &mut Context<Self>) {
        debug_action("ApproveAllow");
        let Some(key) = self.active_key() else {
            return;
        };
        let Some(chat) = self.chats.get(&key) else {
            return;
        };
        let Some(pending) = chat.permissions.iter().find(|pending| !pending.sent) else {
            return;
        };
        let options = &pending.prompt.options;
        let chosen = options
            .iter()
            .find(|option| option.kind == "allowAlways")
            .or_else(|| options.iter().find(|option| option.kind == "allowOnce"))
            .or_else(|| options.iter().find(|option| option.kind != "deny"));
        let Some(option) = chosen else {
            return;
        };
        let (request_id, option_id) = (pending.prompt.request_id.clone(), option.option_id.clone());
        self.resolve_permission(request_id, option_id, cx);
    }

    fn on_approve_deny(&mut self, _: &ApproveDeny, _window: &mut Window, cx: &mut Context<Self>) {
        debug_action("ApproveDeny");
        let Some(key) = self.active_key() else {
            return;
        };
        let Some(chat) = self.chats.get(&key) else {
            return;
        };
        let Some(pending) = chat.permissions.iter().find(|pending| !pending.sent) else {
            return;
        };
        let Some(option) = pending
            .prompt
            .options
            .iter()
            .find(|option| option.kind == "deny")
        else {
            return;
        };
        let (request_id, option_id) = (pending.prompt.request_id.clone(), option.option_id.clone());
        self.resolve_permission(request_id, option_id, cx);
    }

    /// 是否有输入框正处于 IME 组合态（候选未上屏）：组合中的 Enter/Esc 归输入法，
    /// 应用侧不能把它当成「发送/提交/关浮层」。
    fn ime_composing(&self, cx: &App) -> bool {
        // 仅 composer 还是自绘 TextInput；其余输入框由 gpui-kit 内部处理组合态。
        self.input.read(cx).is_composing()
    }

    fn on_send(&mut self, _: &Send, window: &mut Window, cx: &mut Context<Self>) {
        // IME 组合中 Enter 是「上屏候选」，不能当成发送（否则把拼音发出去）。
        if self.ime_composing(cx) {
            return;
        }
        // @ 候选面板打开时，Enter 先把选中成员插进草稿，不发送。
        if let Some((_, names)) = self.mention_context(cx) {
            let index = self.mention_selected.min(names.len().saturating_sub(1));
            let name = names[index].clone();
            self.insert_mention_at(&name, cx);
            return;
        }
        self.send_current(window, cx);
    }

    /// Ctrl+Enter：回合进行中立即插话；空闲时与普通发送一致。
    fn on_send_secondary(
        &mut self,
        _: &SendSecondary,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        if self.ime_composing(cx) {
            return;
        }
        if let Some((_, names)) = self.mention_context(cx) {
            let index = self.mention_selected.min(names.len().saturating_sub(1));
            let name = names[index].clone();
            self.insert_mention_at(&name, cx);
            return;
        }
        let streaming = self
            .active_key()
            .and_then(|key| self.chats.get(&key))
            .is_some_and(|chat| chat.streaming);
        if streaming {
            self.interject_current(window, cx);
        } else {
            self.send_current(window, cx);
        }
    }

    /// 回合进行中把当前输入直接 steer 给正在跑的引擎，而不是等回合结束。
    fn interject_current(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(key) = self.active_key() else {
            return;
        };
        let text = self.input.read(cx).content().trim().to_string();
        if text.is_empty() {
            return;
        }
        let is_group = key.starts_with("group:");
        // 外部 ACP 引擎没有 steering 通道：退回排队，而不是先落气泡再报错。
        if !self.current_engine_is_mode() {
            self.queue_current(&key, text, window, cx);
            return;
        }
        let Some(chat) = self.chats.get_mut(&key) else {
            return;
        };
        if !chat.ready || !chat.streaming {
            return;
        }
        // 插话现在支持附件：取走待发附件。它们已经是 AttachmentUpload
        // （暂存时就读好字节了），这里直接传下去。
        let interject_files = std::mem::take(&mut chat.pending_attachments);
        if chat.elicitations.iter().any(|pending| !pending.sent) {
            return;
        }
        let payload = compose_with_quote(&text, chat.quote.take());
        let members: Vec<String> = if is_group {
            chat.member_stream.keys().cloned().collect()
        } else {
            Vec::new()
        };
        if is_group {
            chat.push_user_group(payload.clone(), Vec::new());
        } else {
            chat.push_user(payload.clone());
        }
        chat.last_sent = Some(text.clone());
        chat.retry = None;
        self.drafts.remove(&key);
        self.backend
            .interject(key, payload, members, interject_files);
        self.input.update(cx, |input, cx| input.clear(window, cx));
        self.toast(i18n::t("已插话，当前回合会立即收到"), cx);
        self.scroll.scroll_to_bottom();
        cx.notify();
    }

    // ---- /side 旁路会话 ----

    /// 打开/复用旁路会话；`text` 非空时立刻发出去。
    fn open_side(&mut self, text: &str, window: &mut Window, cx: &mut Context<Self>) {
        let Some(Selection::Bot(index)) = self.selection else {
            return;
        };
        let Some(bot) = self.roster.bots.get(index).cloned() else {
            return;
        };
        let key = format!("side:{}", bot.id);
        if self
            .side_chat
            .as_ref()
            .is_some_and(|side| side.key == key)
        {
            let input = self.side_chat.as_ref().map(|side| side.input.clone());
            if let Some(input) = input {
                if text.trim().is_empty() {
                    let handle = input.read(cx).focus_handle(cx);
                    handle.focus(window, cx);
                } else {
                    input.update(cx, |input, cx| input.set_content(text, cx));
                    self.send_side(window, cx);
                }
            }
            return;
        }
        if let Some(old) = self.side_chat.take() {
            self.backend.reset_session(old.key);
        }
        let workspace = if bot.directory.trim().is_empty() {
            backend::fallback_workspace().to_string_lossy().into_owned()
        } else {
            bot.directory.clone()
        };
        let identity = bot.identity();
        let model = bot.model.clone();
        let engine = self.sessions.engine_of(&bot.id).map(str::to_string);
        let input = cx.new(|cx| {
            SimpleInput::new(
                i18n::t("旁路提问（不写入主会话）…"),
                theme::ink_tertiary,
                cx,
            )
        });
        self.side_chat = Some(SideChat {
            key: key.clone(),
            bot_name: bot.name.clone(),
            ready: false,
            streaming: false,
            messages: Vec::new(),
            error: None,
            input: input.clone(),
            scroll: ScrollHandle::new(),
            permissions: Vec::new(),
            questions: Vec::new(),
            elicitations: Vec::new(),
        });
        self.backend
            .ensure(key, workspace, identity, model, None, engine);
        if text.trim().is_empty() {
            let handle = input.read(cx).focus_handle(cx);
            window.defer(cx, move |window, cx| handle.focus(window, cx));
        } else {
            input.update(cx, |input, cx| input.set_content(text, cx));
            self.send_side(window, cx);
        }
        cx.notify();
    }

    fn send_side(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(side) = self.side_chat.as_mut() else {
            return;
        };
        let text = side.input.read(cx).content().trim().to_string();
        if text.is_empty() || side.streaming {
            return;
        }
        side.messages.push(SideMessage {
            user: true,
            text: text.clone(),
            tool: false,
        });
        side.streaming = true;
        side.error = None;
        side.input.update(cx, |input, cx| input.clear(window, cx));
        let key = side.key.clone();
        side.scroll.scroll_to_bottom();
        self.backend.send(key, text);
        cx.notify();
    }

    fn close_side(&mut self, cx: &mut Context<Self>) {
        if let Some(side) = self.side_chat.take() {
            self.backend.reset_session(side.key);
        }
        cx.notify();
    }

    /// 旁路事件：不进主 chat，也不触发群任务/记忆回顾/IM 镜像。
    fn apply_side_event(
        &mut self,
        _key: &str,
        event: SessionEvent,
        cx: &mut Context<Self>,
    ) {
        let Some(side) = self.side_chat.as_mut() else {
            return;
        };
        match event {
            SessionEvent::Ready { .. } => {
                side.ready = true;
                side.error = None;
            }
            SessionEvent::Delta { text, .. } => {
                if !text.is_empty() {
                    match side.messages.last_mut() {
                        Some(message) if !message.user && !message.tool => {
                            message.text.push_str(&text);
                        }
                        _ => side.messages.push(SideMessage {
                            user: false,
                            text,
                            tool: false,
                        }),
                    }
                    side.streaming = true;
                    side.scroll.scroll_to_bottom();
                }
            }
            SessionEvent::Tool(card) => {
                if card.state == "running" || card.state == "done" {
                    let line = if card.state == "running" {
                        tri!("调用工具 · {}", "Calling tool · {}", card.name)
                    } else {
                        format!("完成工具 · {}", card.name)
                    };
                    if !side
                        .messages
                        .last()
                        .is_some_and(|message| message.tool && message.text == line)
                    {
                        side.messages.push(SideMessage {
                            user: false,
                            text: line,
                            tool: true,
                        });
                        side.scroll.scroll_to_bottom();
                    }
                }
            }
            SessionEvent::Permission(prompt) => {
                if !side
                    .permissions
                    .iter()
                    .any(|pending| pending.request_id == prompt.request_id)
                {
                    side.permissions.push(prompt);
                }
            }
            SessionEvent::PermissionResolved { request_id } => {
                side.permissions
                    .retain(|pending| pending.request_id != request_id);
            }
            SessionEvent::Question(card) => {
                // 入队显示，由用户点选项回答；不再自动取消。
                if !side
                    .questions
                    .iter()
                    .any(|pending| pending.card.request_id == card.request_id)
                {
                    side.questions.push(PendingQuestion { card, sent: false });
                }
            }
            SessionEvent::QuestionResolved { request_id } => {
                side.questions
                    .retain(|pending| pending.card.request_id != request_id);
            }
            SessionEvent::Elicitation(card) => {
                // 表单需要为每个文本字段建输入框，和主会话同一套初始化。
                if !side
                    .elicitations
                    .iter()
                    .any(|pending| pending.card.request_id == card.request_id)
                {
                    let mut texts = std::collections::HashMap::new();
                    for field in &card.fields {
                        if matches!(
                            field.kind,
                            backend::ElicitationFieldKind::Text
                                | backend::ElicitationFieldKind::Number { .. }
                                | backend::ElicitationFieldKind::TextList
                        ) {
                            texts.insert(
                                field.key.clone(),
                                cx.new(|cx| {
                                    SimpleInput::new(
                                        i18n::t("填写"),
                                        theme::ink_tertiary,
                                        cx,
                                    )
                                }),
                            );
                        }
                    }
                    side.elicitations.push(PendingElicitation {
                        card,
                        sent: false,
                        single: std::collections::HashMap::new(),
                        multi: std::collections::HashMap::new(),
                        texts,
                    });
                }
            }
            SessionEvent::Done { .. } => {
                side.streaming = false;
                side.scroll.scroll_to_bottom();
            }
            SessionEvent::Error { message, .. } => {
                side.streaming = false;
                side.error = Some(message.clone());
                side.messages.push(SideMessage {
                    user: false,
                    text: tri!("错误：{message}", "Error: {message}"),
                    tool: false,
                });
            }
            SessionEvent::Retry {
                attempt,
                max_retries,
                reason,
                ..
            } => {
                side.messages.push(SideMessage {
                    user: false,
                    text: tri!(
                        "重试 {attempt}/{max_retries}：{reason}",
                        "Retry {attempt}/{max_retries}: {reason}"
                    ),
                    tool: true,
                });
            }
            _ => {}
        }
        cx.notify();
    }

