    /// 设置下拉浮层（按点击位置锚定，点外面或 Esc 关闭）。
    fn settings_dropdown_overlay(&mut self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let dropdown = self.settings_dropdown?;
        let position = dropdown.position;
        let kind = dropdown.kind;
        let wechat = wechat_theme::active();
        let (options, current) = self.settings_select_options(kind);
        let mut menu = div()
            .w(px(160.))
            .rounded(px(theme::RADIUS_FIELD))
            .border_1()
            .border_color(if wechat {
                wechat_theme::panel_divider()
            } else {
                theme::edge()
            })
            .bg(if wechat {
                wechat_theme::panel_card_bg()
            } else {
                theme::menu()
            })
            .shadow(theme::shadow_4())
            .p(px(4.))
            .flex()
            .flex_col()
            .gap(px(2.))
            .on_mouse_down(
                gpui::MouseButton::Left,
                cx.listener(|_this, _event, _window, cx| {
                    cx.stop_propagation();
                }),
            );
        for (index, (value, label)) in options.into_iter().enumerate() {
            let active = current == value;
            let option_value = value.clone();
            menu = menu.child(
                div()
                    .id(SharedString::from(format!("settings-option-{index}")))
                    .h(px(28.))
                    .px(px(8.))
                    .rounded(px(theme::RADIUS_CHIP))
                    .flex()
                    .items_center()
                    .gap(px(8.))
                    .pointer()
                    .hover(|style| style.bg(theme::hover()))
                    .on_click(cx.listener(move |this, _event, window, cx| {
                        this.apply_setting_select(kind, &option_value, window, cx);
                    }))
                    .child(icons::icon(
                        icons::Icon::Check,
                        13.,
                        if active {
                            if wechat {
                                wechat_theme::send_enabled()
                            } else {
                                theme::accent()
                            }
                        } else {
                            gpui::rgba(0x00000000)
                        },
                    ))
                    .child(
                        div()
                            .font_family(if wechat {
                                wechat_theme::FONT_FAMILY
                            } else {
                                theme::FONT_FAMILY
                            })
                            .text_size(px(12.))
                            .line_height(px(18.))
                            .text_color(if wechat {
                                wechat_theme::chat_title()
                            } else {
                                theme::ink()
                            })
                            .child(SharedString::from(label)),
                    ),
            );
        }
        Some(
            gpui::deferred(
                div()
                    .absolute()
                    .inset_0()
                    .on_mouse_down(
                        gpui::MouseButton::Left,
                        cx.listener(|this, _event, _window, cx| {
                            this.settings_dropdown = None;
                            cx.notify();
                        }),
                    )
                    .child(
                        gpui::anchored()
                            .position(position)
                            .offset(gpui::point(px(0.), px(6.)))
                            .child(menu),
                    ),
            )
            .into_any_element(),
        )
    }

    /// 输入框权限菜单：三档审批策略，点选即写回当前 Bot。
    fn permission_menu_overlay(&mut self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let position = self.permission_menu?;
        let bot = self.selected_bot()?;
        let bot_id = bot.id.clone();
        let current = bot.approval_level.clone();
        let wechat = wechat_theme::active();
        let accent = if wechat {
            wechat_theme::send_enabled()
        } else {
            theme::accent()
        };
        let title_color = if wechat {
            wechat_theme::chat_title()
        } else {
            theme::ink()
        };
        let note_color = if wechat {
            wechat_theme::list_preview()
        } else {
            theme::ink_secondary()
        };
        let mut menu = div()
            .w(px(304.))
            .rounded(px(theme::RADIUS_FIELD))
            .border_1()
            .border_color(if wechat {
                wechat_theme::composer_border()
            } else {
                theme::edge()
            })
            .bg(if wechat {
                wechat_theme::panel_card_bg()
            } else {
                theme::card()
            })
            .shadow(theme::shadow_3())
            .p(px(6.))
            .on_mouse_down(
                gpui::MouseButton::Left,
                cx.listener(|_this, _event, _window, cx| cx.stop_propagation()),
            )
            .flex()
            .flex_col()
            .child(
                div()
                    .px(px(8.))
                    .py(px(4.))
                    .font_family(if wechat {
                        wechat_theme::FONT_FAMILY
                    } else {
                        theme::FONT_FAMILY
                    })
                    .text_size(px(11.))
                    .text_color(note_color)
                    .child(i18n::t("权限策略")),
            );
        for (level, label) in [
            ("ask", i18n::t("每次询问")),
            ("auto", i18n::t("自动只读")),
            ("full", i18n::t("工作区自动")),
        ] {
            let selected = current == level;
            let bot_id = bot_id.clone();
            menu = menu.child(
                div()
                    .id(SharedString::from(format!("permission-{level}")))
                    .rounded(px(theme::RADIUS_CHIP))
                    .px(px(8.))
                    .py(px(7.))
                    .flex()
                    .items_start()
                    .gap(px(8.))
                    .pointer()
                    .hover(|style| {
                        style.bg(if wechat {
                            wechat_theme::nav_item_hover_bg()
                        } else {
                            theme::hover()
                        })
                    })
                    .on_click(cx.listener(move |this, _event, _window, cx| {
                        this.permission_menu = None;
                        match data::set_bot_approval_level(&bot_id, level) {
                            Ok(()) => {
                                // 权限在会话创建时读取；重置会话后续用同一 resume id。
                                let key = bot_key(&bot_id);
                                this.backend.reset_session(&key);
                                this.chats.remove(&key);
                                this.roster = Roster::load();
                                if let Some(index) =
                                    this.roster.bots.iter().position(|bot| bot.id == bot_id)
                                {
                                    this.selection = Some(Selection::Bot(index));
                                    this.ensure_bot(index);
                                }
                                let label = i18n::t(label);
                                this.toast(
                                    if i18n::is_en() {
                                        format!("Permissions: {label}")
                                    } else {
                                        format!("权限已切换：{label}")
                                    },
                                    cx,
                                );
                            }
                            Err(message) => this.toast(message, cx),
                        }
                        cx.notify();
                    }))
                    .child(
                        div()
                            .w(px(14.))
                            .flex_shrink_0()
                            .flex()
                            .justify_center()
                            .child(if selected {
                                icons::icon(icons::Icon::Check, 14., accent)
                                    .into_any_element()
                            } else {
                                div().size(px(14.)).into_any_element()
                            }),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_w(px(0.))
                            .flex()
                            .flex_col()
                            .gap(px(2.))
                            .child(
                                div()
                                    .font_family(if wechat {
                                        wechat_theme::FONT_FAMILY
                                    } else {
                                        theme::FONT_FAMILY
                                    })
                                    .text_size(px(13.))
                                    .line_height(px(18.))
                                    .text_color(title_color)
                                    .child(label),
                            )
                            .child(
                                div()
                                    .font_family(if wechat {
                                        wechat_theme::FONT_FAMILY
                                    } else {
                                        theme::FONT_FAMILY
                                    })
                                    .text_size(px(11.))
                                    .line_height(px(15.))
                                    .text_color(note_color)
                                    .child(approval_note(level)),
                            ),
                    ),
            );
        }
        Some(
            gpui::deferred(
                div()
                    .absolute()
                    .inset_0()
                    .on_mouse_down(
                        gpui::MouseButton::Left,
                        cx.listener(|this, _event, _window, cx| {
                            this.permission_menu = None;
                            cx.notify();
                        }),
                    )
                    .child(
                        gpui::anchored().position(position).child(menu),
                    ),
            )
            .into_any_element(),
        )
    }

