    /// 历史消息里的附件图片按需回源；取不到时后端回错误占位，UI 显示占位块。
    fn load_history_image(&mut self, meta: &backend::HistoryAttachment, cx: &mut Context<Self>) {
        if self.history_images.contains_key(&meta.attachment_ref)
            || !self
                .history_images_pending
                .insert(meta.attachment_ref.clone())
        {
            return;
        }
        let bot = self.selected_bot().cloned();
        let workspace = bot
            .as_ref()
            .map(|bot| bot.directory.clone())
            .filter(|directory| !directory.trim().is_empty())
            .unwrap_or_else(|| {
                backend::fallback_workspace().to_string_lossy().into_owned()
            });
        let identity = bot.as_ref().map(|bot| bot.identity()).unwrap_or_default();
        self.backend.load_attachment_image(
            workspace,
            identity,
            meta.session_id.clone().unwrap_or_default(),
            meta.attachment_ref.clone(),
            meta.row_id,
            meta.entity_id.clone(),
            meta.index,
        );
        cx.notify();
    }

    /// 智能体：卡片式。每个引擎一张卡（官方标 + 名称 + 检测状态 + 选用）。
    fn settings_page_local_agents(&self, cx: &mut Context<Self>) -> gpui::AnyElement {
        use crate::ui_kit as ui;

        let agents = data::local_agents();
        let bot = self.selected_bot().cloned();
        let bot_index = self.bot_index();
        let bot_id_opt = bot.as_ref().map(|bot| bot.id.clone());
        let current = bot
            .as_ref()
            .and_then(|bot| self.sessions.engine_of(&bot.id))
            .unwrap_or("mode")
            .to_string();
        let current_label = if current == "mode" {
            tri!("内置引擎（Pi-Rust）", "Built-in engine (Pi-Rust)").to_string()
        } else {
            agents
                .iter()
                .find(|agent| agent.command == current || agent.id == current)
                .map(|agent| agent.name.to_string())
                .unwrap_or_else(|| current.clone())
        };

        let mut body = ui::page();
        if let Some(bot) = &bot {
            body = body.child(ui::section(i18n::t("当前 Bot"))).child(ui::card(vec![
                ui::stat_row(bot.name.clone(), "Bot").into_any_element(),
                ui::stat_row(current_label.clone(), i18n::t("当前引擎")).into_any_element(),
            ]));
        } else {
            body = body.child(ui::empty(i18n::t("先在左栏选中一个 Bot 再选择引擎")));
        }

        body = body.child(ui::section_action(
            tri!("已检测到的 Agent · {}", "Detected agents · {}", agents.len()),
            ui::button("agents-refresh", i18n::t("刷新")).on_click(cx.listener(
                |this, _event, _window, cx| {
                    cx.notify();
                    let _ = this;
                },
            )),
        ));

        let mut cards: Vec<gpui::AnyElement> = Vec::new();
        for agent in agents {
            let is_current = current == agent.command || (current == "mode" && agent.wired);
            let installed = agent.path.is_some();
            let adapter = agent.wired
                || matches!(
                    agent.command,
                    "pi-acp" | "deepseek-acp" | "zcode-acp-server" | "hermes"
                );
            let selectable = bot_id_opt.is_some() && adapter && installed && !is_current;

            let detail = if agent.wired {
                tri!("进程内 · 随应用分发（无 Node）", "in-process · bundled (no Node)").to_string()
            } else {
                format!(
                    "{} · {}",
                    agent.id,
                    agent.path.clone().unwrap_or_else(|| tri!(
                        "PATH 上没找到 {}", "{} was not found on PATH", agent.command
                    ))
                )
            };

            let tone = if is_current {
                ui::Tone::Accent
            } else if agent.wired {
                ui::Tone::Success
            } else if installed {
                ui::Tone::Neutral
            } else {
                ui::Tone::Danger
            };
            let status_text = if is_current {
                i18n::t("当前")
            } else if agent.wired {
                i18n::t("内置")
            } else if installed {
                i18n::t("可选用")
            } else {
                i18n::t("未安装")
            };

            let mut card = ui::icon_card(
                agent_icon(agent.id),
                agent.name.to_string(),
                Some(detail.into()),
                Some(ui::badge(status_text, tone).into_any_element()),
            );

            if selectable {
                let bot_id = bot_id_opt.clone().unwrap_or_default();
                let engine_id = if agent.wired {
                    "mode".to_string()
                } else {
                    agent.command.to_string()
                };
                card = card.child(
                    div().flex().child(
                        ui::button(
                            SharedString::from(format!("engine-pick-{}", agent.command)),
                            i18n::t("选用"),
                        )
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            if this.sessions.set_engine(&bot_id, &engine_id) {
                                this.sessions.save();
                            }
                            let key = bot_key(&bot_id);
                            this.backend.reset_session(&key);
                            this.chats.remove(&key);
                            this.ensure_bot(bot_index);
                            this.toast(
                                tri!("已切换到 {engine_id}", "Switched to {engine_id}"),
                                cx,
                            );
                            cx.notify();
                        })),
                    ),
                );
            }
            cards.push(card.into_any_element());
        }
        body.child(
            div()
                .w_full()
                .flex()
                .flex_col()
                .gap(px(ui::S2))
                .children(cards),
        )
        .into_any_element()
    }

    /// 「侧栏分组」管理块（通用页与 Bot团队页共用）。
    ///
    /// 抽出来是因为它现在有两个入口：原「通用」页里的快捷入口，
    /// 和合并后的「Bot团队 → 分组」tab。两边必须完全一致，否则用户会看到两套行为。
    fn sidebar_sections_section(&self, cx: &mut Context<Self>) -> impl IntoElement {
        let mut body = div().w_full().flex().flex_col().gap(px(ui_kit::S4));
        body = body.child(settings_section(i18n::t("侧栏分组")));
        if self.sidebar_sections.sections.is_empty() {
            body = body.child(settings_empty(i18n::t(
                "还没有分组；新建后可在会话 ⋯ 菜单里把 Bot/群聊移入",
            )));
        } else {
            let mut section_rows: Vec<gpui::AnyElement> = Vec::new();
            for section in self.sidebar_sections.sections.clone() {
                let count = self
                    .sidebar_sections
                    .membership
                    .values()
                    .filter(|id| **id == section.id)
                    .count();
                let color_label = section
                    .color
                    .as_deref()
                    .and_then(|id| {
                        SIDEBAR_SECTION_COLORS
                            .iter()
                            .find(|(value, _)| *value == id)
                            .map(|(_, label)| i18n::t(label))
                    })
                    .unwrap_or(i18n::t("无"));
                let mut row = settings_row(
                    section.name.clone(),
                    Some(if i18n::is_en() {
                        format!("{} · color {color_label}", i18n::n(count, "item", "items"))
                    } else {
                        format!("{count} 项 · 颜色 {color_label}")
                    }),
                );
                let id_up = section.id.clone();
                let id_down = section.id.clone();
                let id_rename = section.id.clone();
                let id_color = section.id.clone();
                let id_delete = section.id.clone();
                row = row
                    .child(
                        settings_button(
                            SharedString::from(format!("section-up-{}", id_up)),
                            "↑",
                        )
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            this.move_sidebar_section(&id_up, -1);
                            cx.notify();
                        })),
                    )
                    .child(
                        settings_button(
                            SharedString::from(format!("section-down-{}", id_down)),
                            "↓",
                        )
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            this.move_sidebar_section(&id_down, 1);
                            cx.notify();
                        })),
                    )
                    .child(
                        settings_button(
                            SharedString::from(format!("section-rename-{}", id_rename)),
                            i18n::t("改名"),
                        )
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            let current_name = this
                                .sidebar_sections
                                .sections
                                .iter()
                                .find(|section| section.id == id_rename)
                                .map(|section| section.name.clone())
                                .unwrap_or_default();
                            this.settings_detail = Some(SettingsDetail::Section {
                                editing_id: Some(id_rename.clone()),
                                current_name,
                            });
                            this.settings_detail_input = None;
                            this.settings_open = true;
                            cx.notify();
                        })),
                    )
                    .child(
                        settings_button(
                            SharedString::from(format!("section-color-{}", id_color)),
                            i18n::t("颜色"),
                        )
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            this.cycle_sidebar_section_color(&id_color);
                            cx.notify();
                        })),
                    )
                    .child(
                        settings_button(
                            SharedString::from(format!("section-delete-{}", id_delete)),
                            i18n::t("删除"),
                        )
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            this.delete_sidebar_section(&id_delete);
                            this.toast(i18n::t("已删除分组，成员回到未分组"), cx);
                            cx.notify();
                        })),
                    );
                section_rows.push(row.into_any_element());
            }
            body = body.child(settings_group(section_rows));
        }
        body.child(div().flex().justify_end().child(
            settings_button(SharedString::from("section-new"), i18n::t("新建分组")).on_click(
                cx.listener(|this, _event, _window, cx| {
                    this.settings_detail = Some(SettingsDetail::Section {
                        editing_id: None,
                        current_name: String::new(),
                    });
                    this.settings_detail_input = None;
                    this.settings_open = true;
                    cx.notify();
                }),
            ),
        ))
    }

    /// 「Bot团队」页：Bot / 群聊 / 分组 三个子视图，顶部横向 tab 切换。
    ///
    /// 合并前这是三个独立设置页。三者操作的是同一批对象——Bot 和群聊互为成员，
    /// 分组是对它们的归类——分开反而要来回跳导航。
    fn settings_page_bot_team(
        &mut self,
        content_width: f32,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        const TABS: [&str; 3] = ["Bot", "群聊", "分组"];
        let active = self.bot_team_tab.min(TABS.len() - 1);

        let mut tab_row = div()
            .w_full()
            .flex()
            .flex_shrink_0()
            .items_center()
            .border_b_1()
            .border_color(wechat_theme::divider());
        for (index, label) in TABS.iter().enumerate() {
            let is_active = index == active;
            tab_row = tab_row.child(
                div()
                    .id(SharedString::from(format!("bot-team-tab-{index}")))
                    .h(px(38.))
                    .px(px(ui_kit::S3))
                    .flex()
                    .items_center()
                    .justify_center()
                    // 选中项画 2px 下划线，和容器的 1px 分隔线重叠对齐。
                    .border_b_2()
                    .border_color(if is_active {
                        wechat_theme::send_enabled()
                    } else {
                        gpui::rgba(0x00000000)
                    })
                    .mb(px(-1.))
                    .pointer()
                    .when(!is_active, |el| {
                        el.hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                    })
                    .on_click(cx.listener(move |this, _event, _window, cx| {
                        this.bot_team_tab = index;
                        cx.notify();
                    }))
                    .child(
                        div()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(13.))
                            .line_height(px(20.))
                            .font_weight(if is_active {
                                gpui::FontWeight::SEMIBOLD
                            } else {
                                gpui::FontWeight::NORMAL
                            })
                            .text_color(if is_active {
                                wechat_theme::chat_title()
                            } else {
                                wechat_theme::list_preview()
                            })
                            .child(i18n::t(label)),
                    ),
            );
        }

        let inner = match active {
            0 => self.settings_page_bots(cx),
            1 => self.settings_page_channels(cx),
            _ => self
                .sidebar_sections_section(cx)
                .into_any_element(),
        };
        let _ = content_width;

        div()
            .w_full()
            .flex()
            .flex_col()
            .child(tab_row)
            .child(div().w_full().pt(px(ui_kit::S4)).child(inner))
            .into_any_element()
    }

    fn settings_page_bots(&mut self, cx: &mut Context<Self>) -> gpui::AnyElement {
        let bots = self.roster.bots.clone();
        let hidden = self.roster.hidden_bots.clone();
        let mut body = settings_page_body("Bot");
        body = body.child(settings_section_action(
            tri!("全部 Bot · {}", "All bots · {}", bots.len()),
            settings_action_button("settings-new-bot", i18n::t("新建 Bot")).on_click(
                cx.listener(|this, _event, _window, cx| {
                    this.open_new_dialog(cx);
                }),
            ),
        ));
        if bots.is_empty() {
            body = body.child(settings_empty(i18n::t("名册里还没有 Bot")));
        }
        let mut bot_rows: Vec<gpui::AnyElement> = Vec::new();
        for bot in &bots {
            let bot_id = bot.id.clone();
            let delete_id = bot.id.clone();
            let detail = if bot.role.trim().is_empty() {
                i18n::t("未设角色").to_string()
            } else {
                bot.role.clone()
            };
            bot_rows.push(
                settings_row(bot.name.clone(), Some(detail))
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(6.))
                            .child(
                                settings_button(
                                    SharedString::from(format!("settings-edit-bot-{}", bot.id)),
                                    i18n::t("编辑"),
                                )
                                .on_click(cx.listener(move |this, _event, _window, cx| {
                                    this.open_edit_dialog(bot_id.clone(), cx);
                                })),
                            )
                            .child(
                                settings_button(
                                    SharedString::from(format!("settings-delete-bot-{}", bot.id)),
                                    i18n::t("删除"),
                                )
                                .on_click(cx.listener(move |this, _event, window, cx| {
                                    this.open_delete_bot_dialog(delete_id.clone(), window, cx);
                                })),
                            ),
                    )
                    .into_any_element(),
            );
        }
        if !bot_rows.is_empty() {
            body = body.child(settings_group(bot_rows));
        }
        if !hidden.is_empty() {
            body = body.child(settings_section(i18n::t("已隐藏")));
            let mut hidden_rows: Vec<gpui::AnyElement> = Vec::new();
            for bot in &hidden {
                let bot_id = bot.id.clone();
                let label = if bot.role.trim().is_empty() {
                    bot.name.clone()
                } else {
                    format!("{}（{}）", bot.name, bot.role.trim())
                };
                hidden_rows.push(
                    settings_row(label, None)
                        .child(
                            settings_button(
                                SharedString::from(format!("restore-bot-{}", bot.id)),
                                i18n::t("恢复显示"),
                            )
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                let keep = selected_ids(this);
                                if let Err(message) = data::set_bot_flags(&bot_id, None, Some(false)) {
                                    eprintln!("[settings] 恢复 Bot 失败：{message}");
                                }
                                this.roster = Roster::load();
                                this.reselect_after_roster_change(keep.0.as_deref(), keep.1.as_deref());
                                cx.notify();
                            })),
                        )
                        .into_any_element(),
                );
            }
            body = body.child(settings_group(hidden_rows));
        }
        body.into_any_element()
    }

    fn settings_page_channels(&mut self, cx: &mut Context<Self>) -> gpui::AnyElement {
        let groups = self.roster.groups.clone();
        let hidden = self.roster.hidden_groups.clone();
        let archived = self.roster.archived_groups.clone();
        let mut body = settings_page_body("群聊");
        body = body.child(settings_section_action(
            tri!("全部群聊 · {}", "All group chats · {}", groups.len()),
            settings_action_button("settings-new-group", i18n::t("新建群聊")).on_click(
                cx.listener(|this, _event, _window, cx| {
                    this.open_new_group_dialog(cx);
                }),
            ),
        ));
        if groups.is_empty() {
            body = body.child(settings_empty(i18n::t("还没有群聊")));
        }
        let mut group_rows: Vec<gpui::AnyElement> = Vec::new();
        for group in &groups {
            let group_id = group.id.clone();
            let delete_id = group.id.clone();
            group_rows.push(
                settings_row(
                    group.name.clone(),
                    Some(count_members(visible_group_members(group, &self.roster).len())),
                )
                .child(
                    div()
                        .flex()
                        .items_center()
                        .gap(px(6.))
                        .child(
                            settings_button(
                                SharedString::from(format!("settings-edit-group-{}", group.id)),
                                i18n::t("编辑"),
                            )
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                this.open_edit_group_dialog(group_id.clone(), cx);
                            })),
                        )
                        .child(
                            settings_button(
                                SharedString::from(format!("settings-delete-group-{}", group.id)),
                                i18n::t("删除"),
                            )
                            .on_click(cx.listener(move |this, _event, window, cx| {
                                this.open_delete_group_dialog(delete_id.clone(), window, cx);
                            })),
                        ),
                )
                .into_any_element(),
            );
        }
        if !group_rows.is_empty() {
            body = body.child(settings_group(group_rows));
        }
        if !hidden.is_empty() {
            body = body.child(settings_section(i18n::t("已隐藏")));
            let mut hidden_rows: Vec<gpui::AnyElement> = Vec::new();
            for group in &hidden {
                let group_id = group.id.clone();
                hidden_rows.push(
                    settings_row(tri!("{}（群聊）", "{} (group chat)", group.name), None)
                        .child(
                            settings_button(
                                SharedString::from(format!("restore-group-{}", group.id)),
                                i18n::t("恢复显示"),
                            )
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                let keep = selected_ids(this);
                                if let Err(message) =
                                    data::set_group_flags(&group_id, None, Some(false))
                                {
                                    eprintln!("[settings] 恢复群聊失败：{message}");
                                }
                                this.roster = Roster::load();
                                this.reselect_after_roster_change(keep.0.as_deref(), keep.1.as_deref());
                                cx.notify();
                            })),
                        )
                        .into_any_element(),
                );
            }
            body = body.child(settings_group(hidden_rows));
        }
        if !archived.is_empty() {
            body = body.child(settings_section(i18n::t("已归档群聊")));
            let mut archived_rows: Vec<gpui::AnyElement> = Vec::new();
            for group in &archived {
                let group_id = group.id.clone();
                archived_rows.push(
                    settings_row(group.name.clone(), None)
                        .child(
                            settings_button(
                                SharedString::from(format!("restore-archived-{}", group.id)),
                                i18n::t("取消归档"),
                            )
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                let keep = selected_ids(this);
                                if let Err(message) = data::set_group_archived(&group_id, false) {
                                    eprintln!("[settings] 取消归档失败：{message}");
                                }
                                this.roster = Roster::load();
                                this.reselect_after_roster_change(keep.0.as_deref(), keep.1.as_deref());
                                cx.notify();
                            })),
                        )
                        .into_any_element(),
                );
            }
            body = body.child(settings_group(archived_rows));
        }
        body.into_any_element()
    }

    /// 重读定时任务快照（打开设置页/切换页/动作后调用，不进每帧渲染路径）。
    fn reload_automations(&mut self) {
        let db_path = automations::db_path(&self.roster.data_root);
        let bots: Vec<automations::BotRef<'_>> = self
            .roster
            .bots
            .iter()
            .map(|bot| automations::BotRef {
                id: &bot.id,
                name: &bot.name,
                directory: &bot.directory,
            })
            .collect();
        self.automations_view = Some(match automations::load(&db_path, &bots) {
            Ok(entries) => AutomationsView {
                entries,
                error: None,
            },
            Err(error) => AutomationsView {
                entries: Vec::new(),
                error: Some(error),
            },
        });
    }

    /// IM：微信/企业微信机器人的扫码、运行态、绑定与群聊审批（配置与主程序同源）。
    /// 打开「新建机器人」子页面（设置内容区整页替换，不再弹窗）。
    fn open_im_create_page(
        &mut self,
        provider: bots_service::BotProvider,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let name = cx.new(|cx| {
            SimpleInput::new(i18n::t("机器人名称（可选）"), theme::ink_tertiary, cx)
        });
        let heartbeat = cx.new(|cx| SimpleInput::new("0", theme::ink_tertiary, cx));
        heartbeat.update(cx, |input, cx| input.set_content("0", cx));
        let handle = name.read(cx).focus_handle(cx);
        self.im_create = Some(ImCreateView {
            provider,
            name,
            heartbeat,
            free_access: true,
            group_activation: bots_service::BotGroupActivation::Disabled,
            enabled: true,
        });
        self.im_qr_page = None;
        self.im_delete = None;
        cx.notify();
        window.defer(cx, move |window, cx| handle.focus(window, cx));
    }

    /// 返回上一级：扫码页 → IM 详情；创建页 → IM 列表。
    fn close_im_subpage(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        if self.im_qr_page.take().is_none() {
            self.im_create = None;
        }
        self.settings_focus.focus(window, cx);
        cx.notify();
    }

    /// 提交创建：应用访问/群聊/心跳/启用设置，随后进入扫码绑定页。
    fn submit_im_create(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(view) = self.im_create.as_ref() else {
            return;
        };
        let provider = view.provider;
        let name = view.name.read(cx).content().trim().to_string();
        let free_access = view.free_access;
        let activation = view.group_activation;
        let enabled = view.enabled;
        let minutes = view
            .heartbeat
            .read(cx)
            .content()
            .trim()
            .parse::<i64>()
            .unwrap_or(0)
            .max(0);
        let root = self.roster.data_root.clone();
        let created = if provider == bots_service::BotProvider::Weixin {
            im::create_weixin_bot_named(&root, &name)
        } else {
            im::create_wecom_bot_named(&root, &name)
        };
        match created {
            Ok(bot) => {
                let bot_id = bot.id.clone();
                let mut error = None;
                if !enabled && let Err(message) = im::set_enabled(&root, &bot_id, false) {
                    error = Some(message);
                }
                if error.is_none() && let Err(message) = im::set_access_mode(&root, &bot_id, free_access) {
                    error = Some(message);
                }
                if error.is_none()
                    && let Err(message) = im::set_group_activation(&root, &bot_id, activation)
                {
                    error = Some(message);
                }
                if error.is_none()
                    && minutes > 0
                    && let Err(message) = im::set_heartbeat(&root, &bot_id, minutes)
                {
                    error = Some(message);
                }
                self.im_create = None;
                self.im_selected = Some(bot_id.clone());
                self.im_qr_page = Some(bot_id.clone());
                self.im_heartbeat_input
                    .update(cx, |input, cx| input.set_content(minutes.to_string(), cx));
                if let Some(service) = im_service::handle() {
                    if provider == bots_service::BotProvider::Weixin {
                        service.start_weixin_qr(&bot_id);
                    } else {
                        service.start_wecom_qr(&bot_id);
                    }
                    service.refresh_runtime();
                }
                self.toast(
                    error.unwrap_or_else(|| {
                        i18n::t("已创建机器人，请扫码绑定").to_string()
                    }),
                    cx,
                );
                self.settings_focus.focus(window, cx);
                cx.notify();
            }
            Err(message) => self.toast(message, cx),
        }
    }

    /// 创建页：包含名称、访问模式、群聊方式、心跳与启用开关。
    fn im_create_page(&mut self, cx: &mut Context<Self>) -> gpui::AnyElement {
        let Some(view) = self.im_create.as_ref() else {
            return settings_page_body("").into_any_element();
        };
        let provider = view.provider;
        let name = view.name.clone();
        let heartbeat = view.heartbeat.clone();
        let free_access = view.free_access;
        let activation = view.group_activation;
        let enabled = view.enabled;
        let weixin = provider == bots_service::BotProvider::Weixin;
        let hint = if weixin {
            i18n::t("创建后立即显示登录二维码，用微信扫码即可接通。")
        } else {
            i18n::t("创建后进入企业微信扫码流程，确认后自动写入 Bot ID 与 Secret。")
        };
        let wechat = wechat_theme::active();
        let submit_text = if wechat {
            wechat_theme::bubble_out_text()
        } else {
            theme::accent_ink()
        };
        let mut access = div().flex().flex_wrap().gap(px(6.));
        for (value, label) in [(true, i18n::t("自由访问")), (false, i18n::t("白名单"))] {
            let id = if value {
                "im-create-access-free"
            } else {
                "im-create-access-whitelist"
            };
            access = access.child(
                im_choice_button(id, label, free_access == value).on_click(cx.listener(
                    move |this, _event, _window, cx| {
                        if let Some(view) = this.im_create.as_mut() {
                            view.free_access = value;
                        }
                        cx.notify();
                    },
                )),
            );
        }
        let mut groups = div().flex().flex_wrap().gap(px(6.));
        for (value, label) in [
            (
                bots_service::BotGroupActivation::Disabled,
                i18n::t("不响应群聊"),
            ),
            (
                bots_service::BotGroupActivation::Mention,
                i18n::t("仅 @ 时回复"),
            ),
            (
                bots_service::BotGroupActivation::Always,
                i18n::t("始终回复"),
            ),
        ] {
            let id = SharedString::from(format!("im-create-group-{label}"));
            groups = groups.child(
                im_choice_button(id, label, activation == value).on_click(cx.listener(
                    move |this, _event, _window, cx| {
                        if let Some(view) = this.im_create.as_mut() {
                            view.group_activation = value;
                        }
                        cx.notify();
                    },
                )),
            );
        }
        settings_page_body("")
            .child(settings_section(i18n::t("基本信息")))
            .child(settings_group(vec![im_field(i18n::t("名称（可选）"), name)]))
            .child(settings_section(i18n::t("访问与群聊")))
            .child(settings_group(vec![
                settings_row(i18n::t("访问模式").to_string(), None)
                    .child(access)
                    .into_any_element(),
                settings_row(i18n::t("群聊方式").to_string(), None)
                    .child(groups)
                    .into_any_element(),
            ]))
            .child(settings_section(i18n::t("运行")))
            .child(settings_group(vec![
                im_field(i18n::t("心跳间隔（分钟，0 关闭）"), heartbeat),
                settings_row(i18n::t("创建后启用").to_string(), None)
                    .child(
                        switch("im-create-enabled", enabled).on_click(cx.listener(
                            |this, _event, _window, cx| {
                                if let Some(view) = this.im_create.as_mut() {
                                    view.enabled = !view.enabled;
                                }
                                cx.notify();
                            },
                        )),
                    )
                    .into_any_element(),
            ]))
            .child(settings_note(hint))
            .child(settings_note(i18n::t(
                "创建后请在对应聊天里给 Bot 发一条消息激活。",
            )))
            .child(
                div()
                    .flex()
                    .justify_end()
                    .gap(px(8.))
                    .child(
                        settings_button("im-create-cancel", i18n::t("取消")).on_click(
                            cx.listener(|this, _event, window, cx| {
                                this.close_im_subpage(window, cx);
                            }),
                        ),
                    )
                    .child(
                        div()
                            .id("im-create-submit")
                            .h(px(30.))
                            .rounded(px(theme::RADIUS_PILL))
                            .px(px(14.))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .bg(ui_accent())
                            .hover(|style| style.opacity(0.9))
                            .on_click(cx.listener(|this, _event, window, cx| {
                                this.submit_im_create(window, cx);
                            }))
                            .child(
                                div()
                                    .font_family(if wechat {
                                        wechat_theme::FONT_FAMILY
                                    } else {
                                        theme::FONT_FAMILY
                                    })
                                    .text_size(px(12.))
                                    .line_height(px(18.))
                                    .font_weight(gpui::FontWeight::MEDIUM)
                                    .text_color(submit_text)
                                    .child(i18n::t("创建")),
                            ),
                    ),
            )
            .into_any_element()
    }

    /// 创建后的扫码绑定页（二维码由后台服务刷新，完成即回详情）。
    fn im_qr_page_view(&mut self, bot_id: &str, cx: &mut Context<Self>) -> gpui::AnyElement {
        let wecom = im::bot(&self.roster.data_root, bot_id)
            .ok()
            .flatten()
            .map(|bot| bot.provider == bots_service::BotProvider::Wecom)
            .unwrap_or(false);
        let service = im_service::handle();
        let card = self.im_qr_card(bot_id, wecom, service.as_ref(), cx);
        let done = bot_id.to_string();
        settings_page_body("")
            .child(settings_note(if wecom {
                i18n::t("用企业微信扫码并确认创建机器人；完成后自动写入 Bot ID 与 Secret。")
            } else {
                i18n::t("用微信扫码登录；扫码成功后即可在微信里给 Bot 发消息。")
            }))
            .child(card)
            .child(
                div().flex().justify_end().child(
                    settings_button("im-qr-done", i18n::t("完成")).on_click(cx.listener(
                        move |this, _event, _window, cx| {
                            this.im_qr_page = None;
                            this.im_selected = Some(done.clone());
                            cx.notify();
                        },
                    )),
                ),
            )
            .into_any_element()
    }

