/// @所有人 的固定写法。
const ALL_MENTION: &str = "所有人";

/// 用户消息里的 `@名字` 高亮（chip 效果：强调色淡底 + 正文色），返回 StyledText。
/// `names` 是当前名册里的成员名（群）或 Bot 名（私聊）。
fn user_text_with_mentions(text: &str, names: &[String]) -> gpui::AnyElement {
    let mut highlights: Vec<(std::ops::Range<usize>, HighlightStyle)> = Vec::new();
    let mut candidates: Vec<&str> = names.iter().map(|name| name.as_str()).collect();
    candidates.push(ALL_MENTION);
    for name in candidates {
        if name.is_empty() {
            continue;
        }
        let needle = format!("@{name}");
        let mut cursor = 0usize;
        while let Some(found) = text[cursor..].find(&needle) {
            let start = cursor + found;
            let end = start + needle.len();
            // 词边界：后面紧跟字母/数字/下划线视为更长的名字，不算命中。
            let boundary_ok = text[end..]
                .chars()
                .next()
                .map(|ch| !ch.is_alphanumeric() && ch != '_')
                .unwrap_or(true);
            if boundary_ok {
                highlights.push((
                    start..end,
                    HighlightStyle {
                        background_color: Some(Hsla::from(ui_accent_soft())),
                        color: Some(Hsla::from(if wechat_theme::active() {
                            wechat_theme::bubble_out_text()
                        } else {
                            theme::bubble_user_ink()
                        })),
                        font_weight: Some(gpui::FontWeight::MEDIUM),
                        ..Default::default()
                    },
                ));
            }
            cursor = end;
        }
    }
    if highlights.is_empty() {
        return div().child(SharedString::from(text.to_string())).into_any_element();
    }
    highlights.sort_by_key(|(range, _)| range.start);
    div()
        .child(StyledText::new(text.to_string()).with_highlights(highlights))
        .into_any_element()
}

/// Q-04：默认壳（微信风）的消息悬停动作条。
///
/// classic 的 `message_actions` 要构建期 `&mut Context<PilotApp>`，而 `wechat_row_el`
/// 是虚拟列表的纯函数，只拿到 `&mut App`；这里照 `history_attachment_view` 的
/// 已验证写法，用 `weak.update` 在点击回调里取 Context。
///
/// 只做「复制 / 复制代码」：默认壳的 composer 还没有引用条 UI，挂上「引用」
/// 会让用户点了看不到任何反馈，属于新增 UI，归 v0.6。
fn wechat_message_actions(
    index: usize,
    text: &str,
    weak: &gpui::WeakEntity<PilotApp>,
    align_right: bool,
    hover_group: &gpui::SharedString,
) -> gpui::AnyElement {
    let mut bar = div()
        .absolute()
        // 与 classic 的 `message_row` 一致：挂在气泡上方 18px，
        // 避开正文（助手长段落会铺满列宽，top(0) 会压字）。
        .top(px(-18.))
        .when(align_right, |el| el.right(px(0.)))
        .when(!align_right, |el| el.left(px(0.)))
        .opacity(0.)
        .group_hover(hover_group.clone(), |style| style.opacity(1.))
        .flex()
        .items_center()
        .gap(px(8.))
        .px(px(6.))
        .py(px(2.))
        .rounded(px(theme::RADIUS_TAG))
        .bg(wechat_theme::chip_bg());

    let copy_text = text.to_string();
    let weak_copy = weak.clone();
    bar = bar.child(
        div()
            .id(SharedString::from(format!("wecom-copy-{index}")))
            .font_family(wechat_theme::FONT_FAMILY)
            .text_size(px(ui_kit::T_LABEL))
            .line_height(px(ui_kit::T_LABEL_LH))
            .text_color(wechat_theme::chip_text())
            .pointer()
            .hover(|style| style.text_color(wechat_theme::chat_title()))
            .on_click(move |_event, _window, cx| {
                let text = copy_text.clone();
                let _ = weak_copy.update(cx, |this, cx| {
                    cx.write_to_clipboard(ClipboardItem::new_string(text));
                    this.toast(i18n::t("已复制消息"), cx);
                    cx.notify();
                });
            })
            .child(i18n::t("复制")),
    );

    if let Some(code) = fenced_code(text) {
        let weak_code = weak.clone();
        bar = bar.child(
            div()
                .id(SharedString::from(format!("wecom-copy-code-{index}")))
                .font_family(wechat_theme::FONT_FAMILY)
                .text_size(px(ui_kit::T_LABEL))
                .line_height(px(ui_kit::T_LABEL_LH))
                .text_color(wechat_theme::chip_text())
                .pointer()
                .hover(|style| style.text_color(wechat_theme::chat_title()))
                .on_click(move |_event, _window, cx| {
                    let code = code.clone();
                    let _ = weak_code.update(cx, |this, cx| {
                        cx.write_to_clipboard(ClipboardItem::new_string(code));
                        this.toast(i18n::t("已复制代码"), cx);
                        cx.notify();
                    });
                })
                .child(i18n::t("复制代码")),
        );
    }

    bar.into_any_element()
}

/// 抽取消息里的 ``` 围栏代码块（多个块用空行连接）；没有就返回 None。
fn fenced_code(text: &str) -> Option<String> {
    let mut blocks = Vec::new();
    let mut current = String::new();
    let mut inside = false;
    for line in text.lines() {
        if line.trim_start().starts_with("```") {
            if inside {
                if !current.trim().is_empty() {
                    blocks.push(current.trim_end().to_string());
                }
                current.clear();
                inside = false;
            } else {
                inside = true;
            }
        } else if inside {
            current.push_str(line);
            current.push('\n');
        }
    }
    if blocks.is_empty() {
        None
    } else {
        Some(blocks.join("\n\n"))
    }
}

/// 历史/当前用户消息的附件行：历史图片可点开加载，加载后显示缩略图。
fn history_attachment_view(
    names: &[String],
    metas: &[backend::HistoryAttachment],
    weak: &gpui::WeakEntity<PilotApp>,
    cx: &mut App,
) -> Option<gpui::AnyElement> {
    if names.is_empty() {
        return None;
    }
    let (cache, pending) = weak
        .upgrade()
        .map(|app| {
            let app = app.read(cx);
            (app.history_images.clone(), app.history_images_pending.clone())
        })
        .unwrap_or_default();
    let image_metas: Vec<&backend::HistoryAttachment> = metas
        .iter()
        .filter(|meta| meta.mime.starts_with("image/"))
        .collect();
    let image_names: std::collections::HashSet<&str> =
        image_metas.iter().map(|meta| meta.file_name.as_str()).collect();
    let mut column = div().mt(px(4.)).flex().flex_col().gap(px(4.));
    for meta in image_metas {
        let ref_key = meta.attachment_ref.clone();
        if let Some(path) = cache.get(&meta.attachment_ref) {
            let path = path.clone();
            let thumb_path = path.clone();
            let weak = weak.clone();
            column = column.child(
                div()
                    .id(SharedString::from(format!("history-img-{}", ref_key)))
                    .w(px(132.))
                    .h(px(96.))
                    .rounded(px(theme::RADIUS_CHIP))
                    .overflow_hidden()
                    .border_1()
                    .border_color(wechat_theme::composer_border())
                    .pointer()
                    .hover(|style| style.bg(theme::hover()))
                    .on_click(move |_event, _window, cx| {
                        let path = thumb_path.clone();
                        let _ = weak.update(cx, |this, cx| {
                            this.image_preview = Some(path.clone());
                            cx.notify();
                        });
                    })
                    .child(
                        img(path)
                            .size_full()
                            .object_fit(gpui::ObjectFit::Cover),
                    ),
            );
            continue;
        }
        let loading = pending.contains(&meta.attachment_ref);
        let meta = meta.clone();
        let click_meta = meta.clone();
        let weak = weak.clone();
        column = column.child(
            div()
                .id(SharedString::from(format!("history-img-load-{}", ref_key)))
                .h(px(24.))
                .rounded(px(theme::RADIUS_TAG))
                .bg(wechat_theme::chip_bg())
                .px(px(6.))
                .flex()
                .items_center()
                .gap(px(4.))
                .pointer()
                .hover(|style| style.bg(theme::hover()))
                .when(!loading, |el| {
                    el.on_click(move |_event, _window, cx| {
                        let meta = click_meta.clone();
                        let _ = weak.update(cx, |this, cx| this.load_history_image(&meta, cx));
                    })
                })
                .child(icons::icon(icons::Icon::Paperclip, 11., wechat_theme::icon()))
                .child(
                    div()
                        .max_w(px(160.))
                        .truncate()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(ui_kit::T_LABEL))
                        .text_color(wechat_theme::chip_text())
                        .child(SharedString::from(meta.file_name.clone())),
                )
                .child(
                    div()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(ui_kit::T_LABEL))
                        .text_color(wechat_theme::list_preview())
                        .child(if loading { i18n::t("加载中…") } else { i18n::t("加载") }),
                ),
        );
    }
    for name in names {
        if image_names.contains(name.as_str()) {
            continue;
        }
        column = column.child(
            div()
                .flex()
                .items_center()
                .gap(px(4.))
                .child(icons::icon(icons::Icon::Paperclip, 11., wechat_theme::icon()))
                .child(
                    div()
                        .max_w(px(220.))
                        .truncate()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(ui_kit::T_LABEL))
                        .text_color(wechat_theme::chip_text())
                        .child(SharedString::from(name.clone())),
                ),
        );
    }
    Some(column.into_any_element())
}

/// 按字符截断（id 可能不是纯 ASCII；不能按字节切）。
/// 只压前 `limit` 个字符里的连续空白，返回单行片段。
///
/// 列表预览只需要开头几十个字符；对整条消息做 `split_whitespace().join(" ")`
/// 的代价与消息长度成正比，而这个函数只看前缀，长消息下省掉大部分分配。
fn collapse_whitespace_prefix(text: &str, limit: usize) -> String {
    let mut out = String::with_capacity(limit.min(text.len()));
    let mut prev_space = true; // 首部空白也压掉
    for ch in text.chars().take(limit) {
        if ch.is_whitespace() {
            if !prev_space {
                out.push(' ');
                prev_space = true;
            }
        } else {
            out.push(ch);
            prev_space = false;
        }
    }
    out.trim_end().to_string()
}

fn truncate_chars(text: &str, limit: usize) -> String {
    if text.chars().count() <= limit {
        return text.to_string();
    }
    let mut result: String = text.chars().take(limit).collect();
    result.push('…');
    result
}

/// 焦点指示：贴在元素左侧的 3px 内阴影。
///
/// 用 inset 阴影而不是 `border_l_3()`：边框会占布局空间，把固定宽度的
/// 侧栏/设置导航撑破；阴影只在绘制层，不影响布局。
fn focus_ring_left(color: Rgba) -> gpui::BoxShadow {
    gpui::BoxShadow::new(px(3.), px(0.), Hsla::from(color))
        .inset()
        .spread_radius(px(0.))
}

