/// 已并入「插件」页、不再单独占导航的设置页下标（浏览器 / 电脑操控）。
///
/// 这两页的内容由 `settings_page_plugins` 以内嵌卡片渲染，导航里故意不列。
/// 用常量 + `settings_page_in_nav` 而不是两处 `index == 14 || index == 15` 硬编码：
/// 导航在桌面侧栏（`settings_nav`）和微信风侧栏各写一遍，硬编码写歪一处就会出现
/// 「`SETTINGS_PAGES` 17 项、侧栏只有 15 个入口」的不一致（验收 D-03）。
const EMBEDDED_SETTINGS_PAGES: [usize; 2] = [14, 15];

/// 该设置页是否在导航里单列（内嵌页返回 false）。
fn settings_page_in_nav(index: usize) -> bool {
    !EMBEDDED_SETTINGS_PAGES.contains(&index)
}

/// 设置页骨架：页标题 + 纵向间距（调用方继续 `.child` 内容）。
fn settings_page_body(_title: &'static str) -> gpui::Div {
    // 统一到 ui_kit：页标题由设置壳渲染，页面只排内容（间距 S4）。
    crate::ui_kit::page()
}

/// 设置页分区标题（13/18 · 600）。
fn settings_section(title: impl Into<SharedString>) -> impl IntoElement {
    crate::ui_kit::section(title)
}

/// `"HH:mm"` → `(hour, minute)`。向导里手输时间用，格式错返回 None。
fn parse_hhmm(text: &str) -> Option<(u32, u32)> {
    let (hour, minute) = text.trim().split_once(':')?;
    let hour: u32 = hour.trim().parse().ok()?;
    let minute: u32 = minute.trim().parse().ok()?;
    (hour < 24 && minute < 60).then_some((hour, minute))
}

/// W9 用量分组表列宽：回合窄、token 三列等宽（右对齐，等宽字体才对齐）。
const COL_TURNS: f32 = 44.;
const COL_TOKENS: f32 = 64.;

/// W9 用量分组表（按 Bot）：名称 / 回合 / 输入 / 输出 / 合计。
///
/// 名称列 `flex_1` 吃掉剩余宽度并 truncate；四个数字列用**定宽**右对齐 +
/// 等宽字体（`FONT_MONO`）。定宽是必须的：之前数字列表头和数据行都用 `flex_1`
/// 平分软宽，内容一短就挤到最右侧，表头和数字对不上。
fn usage_table_bot(rows: &[(String, i64, i64, i64)]) -> impl IntoElement {
    use crate::ui_kit as ui;
    if rows.is_empty() {
        return div()
            .w_full()
            .child(ui::empty(i18n::t("这个范围内还没有用量。")))
            .into_any_element();
    }
    let mut card_rows: Vec<gpui::AnyElement> = Vec::new();
    // 表头：名称列跟随 flex_1，四个数字列与数据行同宽同对齐，否则表头会漂。
    let header = |text: &'static str, width: Option<f32>| {
        div()
            .flex()
            .items_center()
            .min_w(px(0.))
            .when_some(width, |el, width| el.w(px(width)).justify_end())
            .when(width.is_none(), |el| el.flex_1())
            .child(
                div()
                    .font_family(theme::FONT_FAMILY)
                    .text_size(px(ui::T_LABEL))
                    .text_color(theme::ink_tertiary())
                    .child(i18n::t(text)),
            )
    };
    card_rows.push(
        div()
            .w_full()
            .flex()
            .items_center()
            .gap(px(ui::S2))
            .px(px(ui::S3))
            .py(px(ui::S2))
            .child(header("名称", None))
            .child(header("回合", Some(COL_TURNS)))
            .child(header("输入", Some(COL_TOKENS)))
            .child(header("输出", Some(COL_TOKENS)))
            .child(header("合计", Some(COL_TOKENS)))
            .into_any_element(),
    );
    let last = rows.len();
    for (index, (name, turns, input, output)) in rows.iter().enumerate() {
        let number = |value: String| {
            div()
                .w(px(COL_TOKENS))
                .flex_shrink_0()
                .flex()
                .justify_end()
                .child(
                    div()
                        .font_family(theme::FONT_MONO)
                        .text_size(px(ui::T_BODY))
                        .text_color(theme::ink())
                        .child(SharedString::from(value)),
                )
        };
        card_rows.push(
            ui::card_row(
                div()
                    .w_full()
                    .flex()
                    .items_center()
                    .gap(px(ui::S2))
                    .px(px(ui::S3))
                    .py(px(ui::S2))
                    .child(
                        div()
                            .flex_1()
                            .min_w(px(0.))
                            .truncate()
                            .font_family(theme::FONT_FAMILY)
                            .text_size(px(ui::T_BODY))
                            .text_color(theme::ink())
                            .child(SharedString::from(name.clone())),
                    )
                    .child(
                        div()
                            .w(px(COL_TURNS))
                            .flex_shrink_0()
                            .flex()
                            .justify_end()
                            .child(
                                div()
                                    .font_family(theme::FONT_MONO)
                                    .text_size(px(ui::T_BODY))
                                    .text_color(theme::ink())
                                    .child(SharedString::from(turns.to_string())),
                            ),
                    )
                    .child(number(session_db::format_tokens(*input)))
                    .child(number(session_db::format_tokens(*output)))
                    .child(number(session_db::format_tokens(input + output))),
                index + 1 == last,
            )
            .into_any_element(),
        );
    }
    div()
        .w_full()
        .id("usage-table-bot")
        .child(ui::card(card_rows))
        .into_any_element()
}

/// W9 用量分组表（按模型）：provider / model / 回合 / 输入 / 输出 / 合计。
///
/// 列宽与 [`usage_table_bot`] 完全一致（同 `COL_TURNS` / `COL_TOKENS`），
/// 两张表切换时数字不会左右跳。
fn usage_table_model(rows: &[(String, String, i64, i64, i64)]) -> impl IntoElement {
    use crate::ui_kit as ui;
    if rows.is_empty() {
        return div()
            .w_full()
            .child(ui::empty(i18n::t("这个范围内还没有用量。")))
            .into_any_element();
    }
    let mut card_rows: Vec<gpui::AnyElement> = Vec::new();
    let number = |width: f32, value: String| {
        div()
            .w(px(width))
            .flex_shrink_0()
            .flex()
            .justify_end()
            .child(
                div()
                    .font_family(theme::FONT_MONO)
                    .text_size(px(ui::T_BODY))
                    .text_color(theme::ink())
                    .child(SharedString::from(value)),
            )
    };
    let mut header = div()
        .w_full()
        .flex()
        .items_center()
        .gap(px(ui::S2))
        .px(px(ui::S3))
        .py(px(ui::S2))
        .child(
            div()
                .flex_1()
                .min_w(px(0.))
                .font_family(theme::FONT_FAMILY)
                .text_size(px(ui::T_LABEL))
                .text_color(theme::ink_tertiary())
                .child(i18n::t("模型 / 提供方")),
        );
    for (label, width) in [
        ("回合", COL_TURNS),
        ("输入", COL_TOKENS),
        ("输出", COL_TOKENS),
        ("合计", COL_TOKENS),
    ] {
        header = header.child(
            div()
                .w(px(width))
                .flex_shrink_0()
                .flex()
                .justify_end()
                .child(
                    div()
                        .font_family(theme::FONT_FAMILY)
                        .text_size(px(ui::T_LABEL))
                        .text_color(theme::ink_tertiary())
                        .child(i18n::t(label)),
                ),
        );
    }
    card_rows.push(header.into_any_element());
    let last = rows.len();
    for (index, (provider, model, turns, input, output)) in rows.iter().enumerate() {
        card_rows.push(
            ui::card_row(
                div()
                    .w_full()
                    .flex()
                    .items_center()
                    .gap(px(ui::S2))
                    .px(px(ui::S3))
                    .py(px(ui::S2))
                    .child(
                        div()
                            .flex_1()
                            .min_w(px(0.))
                            .flex()
                            .flex_col()
                            .gap(px(ui::S1))
                            .child(
                                div()
                                    .font_family(theme::FONT_FAMILY)
                                    .text_size(px(ui::T_BODY))
                                    .text_color(theme::ink())
                                    .truncate()
                                    .child(SharedString::from(model.clone())),
                            )
                            .child(
                                div()
                                    .font_family(theme::FONT_FAMILY)
                                    .text_size(px(ui::T_LABEL))
                                    .text_color(theme::ink_tertiary())
                                    .truncate()
                                    .child(SharedString::from(provider.clone())),
                            ),
                    )
                    .child(number(COL_TURNS, turns.to_string()))
                    .child(number(COL_TOKENS, session_db::format_tokens(*input)))
                    .child(number(COL_TOKENS, session_db::format_tokens(*output)))
                    .child(number(COL_TOKENS, session_db::format_tokens(input + output))),
                index + 1 == last,
            )
            .into_any_element(),
        );
    }
    div()
        .w_full()
        .id("usage-table-model")
        .child(ui::card(card_rows))
        .into_any_element()
}

/// 分区标题 + 右侧动作（对齐 DS `.bt-set-section` + 头部 soft 按钮）。
fn settings_section_action(
    title: impl Into<SharedString>,
    action: impl IntoElement,
) -> impl IntoElement {
    let wechat = wechat_theme::active();
    div()
        .w_full()
        .pt(px(10.))
        .flex()
        .items_center()
        .justify_between()
        .gap(px(8.))
        .child(
            div()
                .font_family(if wechat {
                    wechat_theme::FONT_FAMILY
                } else {
                    theme::FONT_FAMILY
                })
                .text_size(px(13.))
                .line_height(px(18.))
                .font_weight(gpui::FontWeight::SEMIBOLD)
                .text_color(if wechat {
                    wechat_theme::chat_title()
                } else {
                    theme::ink()
                })
                .child(title.into()),
        )
        .child(action)
}

/// 设置页分区头部的小动作按钮（32 高，比正文 soft 按钮轻一档）。
fn settings_action_button(
    id: impl Into<gpui::ElementId>,
    label: impl Into<gpui::SharedString>,
) -> gpui::Stateful<gpui::Div> {
    let wechat = wechat_theme::active();
    div()
        .id(id)
        .h(px(28.))
        .rounded(px(theme::RADIUS_PILL))
        .bg(if wechat {
            wechat_theme::chip_bg()
        } else {
            theme::hover()
        })
        .px(px(10.))
        .flex()
        .items_center()
        .justify_center()
        .pointer()
        .hover(|style| style.bg(theme::raised_hover()))
        .child(
            div()
                .font_family(if wechat {
                    wechat_theme::FONT_FAMILY
                } else {
                    theme::FONT_FAMILY
                })
                .text_size(px(12.))
                .line_height(px(18.))
                .font_weight(gpui::FontWeight::MEDIUM)
                .text_color(if wechat {
                    wechat_theme::chat_title()
                } else {
                    theme::ink()
                })
                .child(label.into()),
        )
}

/// 设置页空态：DS 的空态是卡片里一行 hint，不是裸文字。
fn settings_empty(text: impl Into<SharedString>) -> impl IntoElement {
    crate::ui_kit::empty(text)
}

/// 连接器卡片里的文字动作（获取密钥/测试）：DS 卡片只保留轻量文字按钮。
fn connector_link(
    id: impl Into<gpui::ElementId>,
    label: impl Into<gpui::SharedString>,
) -> gpui::Stateful<gpui::Div> {
    div()
        .id(id)
        .h(px(20.))
        .px(px(2.))
        .flex()
        .items_center()
        .pointer()
        .font_family(theme::FONT_FAMILY)
        .text_size(px(11.))
        .line_height(px(16.))
        .text_color(theme::ink_secondary())
        .hover(|style| style.text_color(ui_accent()))
        .child(label.into())
}

/// 当前皮肤的强调色（微信绿 / 经典强调色）。
fn ui_accent() -> Rgba {
    if wechat_theme::active() {
        wechat_theme::send_enabled()
    } else {
        theme::accent()
    }
}

/// 当前皮肤的强调色淡底。
fn ui_accent_soft() -> Rgba {
    if wechat_theme::active() {
        let accent = wechat_theme::send_enabled();
        Rgba {
            r: accent.r,
            g: accent.g,
            b: accent.b,
            a: 0.18,
        }
    } else {
        theme::accent_soft()
    }
}

/// 连接器卡片的分类图标（DS 用品牌 logo；我们没有素材，用分类图标占位）。
fn connector_icon(id: &str, category: &str) -> gpui::AnyElement {
    let glyph = match category {
        "dev" => icons::Icon::Cpu,
        "docs" => icons::Icon::Folder,
        "work" => icons::Icon::ListChecks,
        "data" => icons::Icon::Chart,
        "search" => icons::Icon::Search,
        "design" => icons::Icon::Sparkles,
        _ => icons::Icon::Plug,
    };
    let wechat = wechat_theme::active();
    let container = div()
        .size(px(26.))
        .flex_shrink_0()
        .rounded(px(theme::RADIUS_FIELD))
        .bg(if wechat {
            wechat_theme::chip_bg()
        } else {
            theme::hover()
        })
        .flex()
        .items_center()
        .justify_center();
    // 连接器统一单色 currentColor，按品牌色染（近黑标在深色主题下回退到前景色，
    // 见 brand_icons::color）。
    if let Some(key) = brand_icons::connector_key(id)
        && let (Some(data), Some(color)) = (brand_icons::asset(key), brand_icons::color(key))
    {
        return container
            .child(gpui::svg().data(data).size(px(16.)).text_color(color))
            .into_any_element();
    }
    if let Some(data) = brand_icons::asset(id)
        && let Some(color) = brand_icons::color(id)
    {
        return container
            .child(gpui::svg().data(data).size(px(16.)).text_color(color))
            .into_any_element();
    }
    container
        .child(icons::icon(
            glyph,
            14.,
            if wechat {
                wechat_theme::icon_strong()
            } else {
                theme::ink_secondary()
            },
        ))
        .into_any_element()
}

