/// 工作目录尾名（定时任务找不到归属 Bot 时的展示名）。
fn workspace_tail(path: &str) -> String {
    let trimmed = path.trim().trim_end_matches(['\\', '/']);
    trimmed
        .rsplit(['\\', '/'])
        .find(|segment| !segment.is_empty())
        .unwrap_or(i18n::t("未知工作区"))
        .to_string()
}

