/// 厂商首字母方块的底色：按色相取一个低饱和块，深浅主题各一档。
fn provider_tile_bg(hue: f32) -> gpui::Rgba {
    let (s, l) = if theme::is_light() {
        (0.42, 0.90)
    } else {
        (0.36, 0.24)
    };
    let hsla = gpui::hsla(hue / 360.0, s, l, 1.);
    hsla.into()
}

/// 没有官方 logo 的厂商：色块 + 首字母（与 IM 头像同一套观感）。
fn provider_initial_tile(name: &str, size: f32) -> gpui::AnyElement {
    let initial = name
        .trim()
        .chars()
        .next()
        .map(|ch| ch.to_uppercase().to_string())
        .unwrap_or_else(|| "?".to_string());
    let hue = avatar::avatar_hue(name);
    div()
        .size(px(size))
        .flex_shrink_0()
        .rounded(px(size * 0.24))
        .bg(provider_tile_bg(hue))
        .flex()
        .items_center()
        .justify_center()
        .child(
            div()
                .font_family(theme::FONT_FAMILY)
                .text_size(px((size * 0.48).max(9.)))
                .font_weight(gpui::FontWeight::SEMIBOLD)
                .text_color(theme::ink())
                .child(initial),
        )
        .into_any_element()
}

fn settings_row_inner(
    leading: Option<gpui::AnyElement>,
    title: String,
    detail: Option<String>,
) -> gpui::Div {
    let wechat = wechat_theme::active();
    // 三栏布局：标签固定 130 / 说明吃掉中间 / 控件贴右缘。
    // 原来是「标题 + 说明」竖堆在左、控件在右，说明只能占很窄一截，
    // 而且每行高度被说明撑高一倍。
    let mut row = div()
        .w_full()
        .min_h(px(42.))
        .px(px(12.))
        .py(px(9.))
        .flex()
        .items_center()
        .gap(px(14.));
    if let Some(leading) = leading {
        row = row.child(leading);
    }
    // Q-03：130 是中文标签的宽度；英文标签更长（最宽 "Default model for new bots"
    // 约 182px），固定 130 会截成 "Background notific…"。按语言给两档宽度。
    let title_width = if i18n::is_en() { 184. } else { 130. };
    row = row.child(
        div()
            .w(px(title_width))
            .flex_shrink_0()
            .truncate()
            .font_family(if wechat {
                wechat_theme::FONT_FAMILY
            } else {
                theme::FONT_FAMILY
            })
            .text_size(px(13.))
            .line_height(px(18.))
            .text_color(if wechat {
                wechat_theme::chat_title()
            } else {
                theme::ink()
            })
            .child(SharedString::from(title)),
    );
    // 说明列：窄窗口下让它先被压缩（truncate），控件永远完整。
    row = row.child(
        div()
            .flex_1()
            .min_w(px(0.))
            .truncate()
            .font_family(if wechat {
                wechat_theme::FONT_FAMILY
            } else {
                theme::FONT_FAMILY
            })
            .text_size(px(12.))
            .line_height(px(16.))
            .text_color(if wechat {
                wechat_theme::list_preview()
            } else {
                theme::ink_secondary()
            })
            .child(SharedString::from(detail.unwrap_or_default())),
    );
    // 控件槽：调用方 `.child(...)` 追加到这里。
    row
}

fn settings_group(rows: Vec<gpui::AnyElement>) -> impl IntoElement {
    let wechat = wechat_theme::active();
    let count = rows.len();
    let mut card = div()
        .w_full()
        .rounded(px(theme::RADIUS_FIELD))
        .border_1()
        .border_color(if wechat {
            wechat_theme::composer_border()
        } else {
            theme::edge()
        })
        .bg(if wechat {
            wechat_theme::panel_bg()
        } else {
            theme::card()
        })
        .overflow_hidden()
        .flex()
        .flex_col();
    for (index, row) in rows.into_iter().enumerate() {
        let mut cell = div().w_full();
        if index + 1 < count {
            cell = cell
                .border_b(px(0.5))
                .border_color(if wechat {
                    wechat_theme::divider()
                } else {
                    theme::edge()
                });
        }
        card = card.child(cell.child(row));
    }
    card
}

