/// W4：上下文压缩中的状态行。挂在消息流顶部，`active=false` 时由调用处移除。
///
/// 不是气泡（组合进 `column` 会让它被当成一条消息进历史），只是一行居中的
/// `T_Label` + 主题色，和 DS 的 "Compacting context…" 一致。
fn compaction_status_row() -> impl IntoElement {
    div()
        .id("chat-compaction-status")
        .w_full()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(ui_kit::S1))
        .py(px(ui_kit::S1))
        .child(icons::icon(icons::Icon::Refresh, 12., theme::ink_tertiary()))
        .child(
            div()
                .font_family(theme::FONT_FAMILY)
                .text_size(px(ui_kit::T_LABEL))
                .line_height(px(ui_kit::T_LABEL_LH))
                .text_color(theme::ink_tertiary())
                .child(i18n::t("正在压缩上下文…")),
        )
}

/// 加载骨架（DS §10.9：加载用骨架占位，不用转圈）：三条气泡占位做余弦呼吸。
/// 每条各自挂动画（元素 id 必须唯一），减少动效时自动落到静态首帧。
fn skeleton_rows() -> impl IntoElement {
    div()
        .w_full()
        .flex()
        .flex_col()
        .gap(px(12.))
        .child(skeleton_bar("skeleton-bot-a", 210., false))
        .child(skeleton_bar("skeleton-user", 150., true))
        .child(skeleton_bar("skeleton-bot-b", 260., false))
}

fn skeleton_bar(id: &'static str, width: f32, right: bool) -> impl IntoElement {
    div()
        .w_full()
        .flex()
        .when(right, |row| row.justify_end())
        .child(
            div()
                .w(px(width))
                .h(px(34.))
                .rounded(px(theme::RADIUS_BUBBLE))
                .bg(theme::skeleton())
                .with_animation(
                    id,
                    gpui::Animation::new(Duration::from_millis(1200))
                        .repeat()
                        .with_easing(|t| 0.775 - 0.225 * (t * std::f32::consts::TAU).cos()),
                    |element, delta| element.opacity(delta.clamp(0., 1.)),
                ),
        )
}

/// AskUserQuestion/ExitPlanMode 的 permission.requested 只是等待态标记；
/// 真正的交互随后经 requestUserInput 问题卡到达（与真实 UI 同语义）。
fn is_user_input_backed(tool_name: &str) -> bool {
    let tool = tool_name.trim().to_ascii_lowercase();
    tool == "askuserquestion" || tool == "exitplanmode"
}

fn auto_permission(
    bot: &Bot,
    prompt: &PermissionPrompt,
) -> Option<(String, String, String)> {
    // 隐私越界（访问别人/已归档的目录）一律交给用户：档位说的是「这个 Bot 在它自己的
    // 范围内可以多自由」，不是「允许它读别人的隐私目录」。曾经这里只按工具名判定，
    // `full` 对 `read` 返回 Allow，越界卡被静默消费，文件内容直接进了回复（D-05）。
    if prompt.privacy {
        return None;
    }
    let level = parse_level(&bot.approval_level).ok()?;
    let decision = decide(level, &bot.approval_allowlist, &prompt.tool_name);
    let (allow, label) = match decision {
        ApprovalDecision::Allow => (true, i18n::t("放行")),
        ApprovalDecision::Deny => (false, "拒绝"),
        ApprovalDecision::Ask => return None,
    };
    let option = pick_option(prompt, allow)?;
    let note = format!(
        "已按 {} 策略自动{} · {}",
        match level {
            bot_team::approval::ApprovalLevel::Full => "full",
            bot_team::approval::ApprovalLevel::Auto => "auto",
            bot_team::approval::ApprovalLevel::Ask => "ask",
        },
        label,
        prompt.tool_name
    );
    if std::env::var("BOT_PILOT_DEBUG").ok().as_deref() == Some("1") {
        eprintln!("[ui] auto {label} {} ({note})", prompt.tool_name);
    }
    Some((prompt.request_id.clone(), option, note))
}

/// allow 时优先「仅本次」，其次「始终」，再退任意 allow 类；deny 只认 deny 类。
fn pick_option(prompt: &PermissionPrompt, allow: bool) -> Option<String> {
    if allow {
        for kind in ["allowOnce", "allowAlways"] {
            if let Some(option) = prompt.options.iter().find(|option| option.kind == kind) {
                return Some(option.option_id.clone());
            }
        }
        prompt
            .options
            .iter()
            .find(|option| option.kind.starts_with("allow"))
            .map(|option| option.option_id.clone())
    } else {
        prompt
            .options
            .iter()
            .find(|option| option.kind == "deny")
            .map(|option| option.option_id.clone())
    }
}

// ---- markdown 渲染（md 块 → gpui 元素）----

/// gpui-kit 的 Markdown TextView（GFM 表格/列表/代码块/选择复制都由组件负责）。
fn kit_markdown_el(id: String, text: &str, wechat: bool, font_size: f32) -> gpui::AnyElement {
    gpui::component::text::TextView::markdown(id, text.to_string())
        .selectable(true)
        .font_family(if wechat {
            wechat_theme::FONT_FAMILY
        } else {
            theme::FONT_FAMILY
        })
        .text_size(px(font_size))
        .line_height(px(font_size + if wechat { 8. } else { 10. }))
        .text_color(if wechat {
            wechat_theme::bubble_text()
        } else {
            theme::ink()
        })
        .into_any_element()
}

/// 时长文案：秒 / 分秒（与 WebView 的「2 分 20 秒」一致）。
fn elapsed_label(ms: u64) -> String {
    let secs = ms / 1000;
    if i18n::is_en() {
        if secs < 60 {
            format!("{secs}s")
        } else {
            format!("{}m {}s", secs / 60, secs % 60)
        }
    } else if secs < 60 {
            tri!("{secs} 秒", "{secs}s")
    } else {
            tri!("{} 分 {} 秒", "{}m {}s", secs / 60, secs % 60)
    }
}

/// 当前回合按文件聚合的改动（路径, 新增行, 删除行），按路径排序。
fn turn_edit_details(messages: &[Message]) -> Vec<(String, usize, usize)> {
    let start = messages
        .iter()
        .rposition(|message| message.role == Role::User)
        .map(|index| index + 1)
        .unwrap_or(0);
    let mut files: HashMap<String, (usize, usize)> = HashMap::new();
    for message in &messages[start..] {
        if message.kind != MsgKind::Tool
            || tool_render::family(&message.tool_name) != tool_render::ToolFamily::Edit
        {
            continue;
        }
        if let Some(info) = tool_render::edit_info(
            &message.tool_name,
            &message.tool_input,
            &message.tool_details,
        ) && !info.path.is_empty()
        {
            let entry = files.entry(info.path).or_insert((0, 0));
            entry.0 += info.added;
            entry.1 += info.removed;
        }
    }
    let mut rows: Vec<(String, usize, usize)> = files
        .into_iter()
        .map(|(path, (added, removed))| (path, added, removed))
        .collect();
    rows.sort_by(|left, right| left.0.cmp(&right.0));
    rows
}

/// 当前回合的写文件汇总（文件数、新增、删除；单测用）。
#[cfg(test)]
fn turn_edit_summary(messages: &[Message]) -> Option<(usize, usize, usize)> {
    let rows = turn_edit_details(messages);
    if rows.is_empty() {
        return None;
    }
    let added = rows.iter().map(|(_, added, _)| *added).sum();
    let removed = rows.iter().map(|(_, _, removed)| *removed).sum();
    Some((rows.len(), added, removed))
}

/// token 数的紧凑展示：1234 → 1.2k。
fn compact_tokens(value: i64) -> String {
    if value >= 1000 {
        format!("{:.1}k", value as f64 / 1000.0)
    } else {
        value.to_string()
    }
}

/// ACP 的 completed/failed/scheduled 与 pi 的 done/error/pending 统一成一套状态词。
fn normalize_tool_state(state: &str) -> &str {
    match state {
        "completed" => "done",
        "failed" => "error",
        "scheduled" => "pending",
        other => other,
    }
}

/// 首字前的「正在输入」三点气泡（错峰呼吸；无额外计时行）。
fn typing_bubble() -> gpui::AnyElement {
    let mut dots = div().flex().items_center().gap(px(4.));
    for index in 0..3 {
        dots = dots.child(
            div()
                .size(px(5.))
                .rounded_full()
                .bg(wechat_theme::time_label())
                .with_animation(
                    SharedString::from(format!("typing-dot-{index}")),
                    gpui::Animation::new(Duration::from_millis(1100)).repeat(),
                    move |el, delta| {
                        let phase = (delta + index as f32 * 0.2) % 1.0;
                        let wave = (phase * std::f32::consts::TAU).sin().max(0.0);
                        el.opacity(0.35 + 0.65 * wave)
                    },
                ),
        );
    }
    div()
        .w_full()
        .px(px(14.))
        .pb(px(4.))
        .flex()
        .justify_start()
        .child(
            div()
                .rounded(px(theme::RADIUS_FIELD))
                .border_1()
                .border_color(wechat_theme::composer_border())
                .bg(wechat_theme::panel_card_bg())
                .px(px(10.))
                .py(px(8.))
                .child(dots),
        )
        .into_any_element()
}

fn tool_state_label(state: &str) -> &'static str {
    match state {
        "pending" => i18n::t("排队中"),
        "running" => i18n::t("执行中"),
        "done" => i18n::t("已执行"),
        "error" => i18n::t("失败"),
        _ => "",
    }
}

/// 企微风格的工具卡：单行 chip，不再用满宽预览撑开。
/// 工具类别对应的行图标（贴近 WebView ToolLayout 的工具语义）。
fn tool_icon(name: &str) -> icons::Icon {
    let name = name.to_ascii_lowercase();
    if name.contains("bash") || name.contains("shell") || name.contains("exec") || name.contains("terminal") {
        icons::Icon::Terminal
    } else if name.contains("read") || name.contains("write") || name.contains("edit") || name.contains("patch") || name.contains("apply") {
        icons::Icon::Pencil
    } else if name.contains("search") || name.contains("grep") || name.contains("glob") || name.contains("find") || name.contains("browser") || name.contains("fetch") || name.contains("web") {
        icons::Icon::Search
    } else if name.contains("list") || name.contains("file") || name.contains("dir") {
        icons::Icon::Folder
    } else if name.contains("ask") || name.contains("question") {
        icons::Icon::MessageCircle
    } else if name.contains("mcp") || name.contains("connector") {
        icons::Icon::Plug
    } else if name.contains("plan") || name.contains("todo") || name.contains("task") {
        icons::Icon::ListChecks
    } else {
        icons::Icon::Terminal
    }
}

/// 工具卡主文案：优先显示参数里用户关心的对象（路径 / 命令 / 搜索词）。
fn tool_primary_text(message: &Message) -> String {
    let title = if message.tool_title.trim().is_empty() {
        message.tool_name.trim()
    } else {
        message.tool_title.trim()
    };
    let subject = tool_render::subject(&message.tool_name, &message.tool_input, title);
    let subject = if subject.trim().is_empty() {
        message.tool_name.trim().to_string()
    } else {
        subject
    };
    tool_render::single_line(&subject, 96)
}

/// 一行式工具卡的行头（图标 + 状态 + 主文案 + 可选计数 + 折叠箭头）。
fn tool_row_base(
    icon: icons::Icon,
    state: &str,
    primary: &str,
    counts: Option<(usize, usize)>,
    has_content: bool,
    expanded: bool,
) -> gpui::Div {
    let state_label = tool_state_label(state);
    let (status_color, icon_color) = match state {
        "running" => (wechat_theme::send_enabled(), wechat_theme::send_enabled()),
        "error" => (wechat_theme::nav_badge_bg(), wechat_theme::nav_badge_bg()),
        "done" => (wechat_theme::chat_title(), wechat_theme::chip_text()),
        _ => (wechat_theme::time_label(), wechat_theme::chip_text()),
    };
    // 工具行保持单行紧凑：1px 垂直留白 + 16px 行高，连续调用不撑高 transcript。
    let mut row = div()
        .w_full()
        .flex()
        .items_center()
        .gap(px(5.))
        .px(px(2.))
        .py(px(1.))
        .child(icons::icon(icon, 13., icon_color))
        .children((!state_label.is_empty()).then(|| {
            div()
                .flex_shrink_0()
                .font_family(wechat_theme::FONT_FAMILY)
                .text_size(px(12.))
                .line_height(px(16.))
                .text_color(status_color)
                .child(i18n::t(state_label))
        }))
        .child(
            div()
                .flex_1()
                .min_w(px(0.))
                .truncate()
                .font_family(wechat_theme::FONT_FAMILY)
                .text_size(px(12.))
                .line_height(px(16.))
                .text_color(wechat_theme::list_preview())
                .child(SharedString::from(primary.to_string())),
        );
    if let Some((added, removed)) = counts
        && added + removed > 0
    {
        row = row.child(diff_count_el(added, removed));
    }
    row.children(has_content.then(|| {
        icons::icon(
            if expanded {
                icons::Icon::ChevronLeft
            } else {
                icons::Icon::ChevronRight
            },
            12.,
            wechat_theme::icon(),
        )
    }))
}

/// 展开面板右下角的轻量复制动作（仅展开时出现，不占常驻高度）。
fn tool_copy_button(
    id: String,
    label: &'static str,
    text: String,
    weak: gpui::WeakEntity<PilotApp>,
) -> gpui::AnyElement {
    div()
        .id(SharedString::from(id))
        .h(px(18.))
        .px(px(4.))
        .rounded(px(theme::RADIUS_TAG))
        .flex()
        .items_center()
        .pointer()
        .font_family(wechat_theme::FONT_FAMILY)
        .text_size(px(ui_kit::T_LABEL))
        .text_color(wechat_theme::time_label())
        .hover(|style| {
            style
                .bg(wechat_theme::nav_item_hover_bg())
                .text_color(wechat_theme::chat_title())
        })
        .on_click(move |_event, _window, cx| {
            cx.write_to_clipboard(gpui::ClipboardItem::new_string(text.clone()));
            let _ = weak.update(cx, |this, cx| {
                this.toast(i18n::t("已复制"), cx);
            });
        })
        .child(label)
        .into_any_element()
}

/// 截图类工具结果的缩略图行（点击复用会话内的大图预览）。
fn tool_images_row(
    paths: &[String],
    call_id: &str,
    weak: &gpui::WeakEntity<PilotApp>,
) -> Option<gpui::AnyElement> {
    if paths.is_empty() {
        return None;
    }
    let mut row = div().w_full().flex().flex_wrap().gap(px(6.));
    for (index, path) in paths.iter().take(4).enumerate() {
        let path = std::path::PathBuf::from(path);
        let click_path = path.clone();
        let weak = weak.clone();
        row = row.child(
            div()
                .id(SharedString::from(format!("tool-image-{call_id}-{index}")))
                .w(px(132.))
                .h(px(96.))
                .rounded(px(theme::RADIUS_CHIP))
                .border_1()
                .border_color(wechat_theme::composer_border())
                .overflow_hidden()
                .pointer()
                .hover(|style| style.bg(theme::hover()))
                .on_click(move |_event, _window, cx| {
                    let path = click_path.clone();
                    let _ = weak.update(cx, |this, cx| {
                        this.image_preview = Some(path);
                        cx.notify();
                    });
                })
                .child(gpui::img(path).size_full().object_fit(gpui::ObjectFit::Cover)),
        );
    }
    if paths.len() > 4 {
        row = row.child(
            div()
                .font_family(wechat_theme::FONT_FAMILY)
                .text_size(px(ui_kit::T_LABEL))
                .text_color(wechat_theme::time_label())
                .child(SharedString::from(format!("+{}", paths.len() - 4))),
        );
    }
    Some(row.into_any_element())
}

fn tool_actions_row(
    call_id: &str,
    actions: Vec<(&'static str, String)>,
    weak: &gpui::WeakEntity<PilotApp>,
) -> gpui::AnyElement {
    let mut row = div().w_full().flex().justify_end().items_center().gap(px(6.));
    for (index, (label, text)) in actions.into_iter().enumerate() {
        row = row.child(tool_copy_button(
            format!("tool-copy-{call_id}-{index}"),
            label,
            text,
            weak.clone(),
        ));
    }
    row.into_any_element()
}

/// 把内联 diff 还原成可复制的纯文本。
fn edit_info_text(info: &tool_render::EditInfo) -> String {
    info.lines
        .iter()
        .map(|line| {
            let marker = match line.kind {
                tool_render::DiffKind::Added => "+",
                tool_render::DiffKind::Removed => "-",
                tool_render::DiffKind::Context => " ",
            };
            format!("{marker}{}", line.text)
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn diff_count_el(added: usize, removed: usize) -> gpui::AnyElement {
    let mut row = div()
        .flex_shrink_0()
        .flex()
        .items_center()
        .gap(px(4.))
        .font_family(theme::FONT_MONO)
        .text_size(px(11.))
        .line_height(px(16.));
    if added > 0 {
        row = row.child(
            div()
                .text_color(theme::success())
                .child(SharedString::from(format!("+{added}"))),
        );
    }
    if removed > 0 {
        row = row.child(
            div()
                .text_color(theme::danger())
                .child(SharedString::from(format!("-{removed}"))),
        );
    }
    row.into_any_element()
}

/// 截断多行文本到 N 行（尾部标注剩余行数），用于命令输出与通用详情。
fn capped_text(text: &str, max_lines: usize) -> String {
    let total = text.lines().count();
    let mut out = String::new();
    for line in text.lines().take(max_lines) {
        if !out.is_empty() {
            out.push('\n');
        }
        out.push_str(line);
    }
    if total > max_lines {
        out.push_str(&if i18n::is_en() {
            format!("\n… {} more lines", total - max_lines)
        } else {
            format!("\n… 还有 {} 行", total - max_lines)
        });
    }
    out
}

/// edit 内联 diff：逐行渲染，超过上限只显示前 N 行 + 剩余数量。
fn edit_diff_panel(info: &tool_render::EditInfo, output: &str) -> gpui::AnyElement {
    // 与 WebView 的内联 diff 卡同构：圆角/描边/面板底色，高度只保留关键片段。
    const MAX_LINES: usize = 16;
    let mut panel = div()
        .w_full()
        .rounded(px(theme::RADIUS_FIELD))
        .border_1()
        .border_color(wechat_theme::composer_border())
        .bg(wechat_theme::panel_card_bg())
        .py(px(4.))
        .flex()
        .flex_col()
        .overflow_hidden();
    if info.lines.is_empty() {
        if !output.trim().is_empty() {
            panel = panel.child(
                div()
                    .px(px(8.))
                    .py(px(2.))
                    .font_family(theme::FONT_MONO)
                    .text_size(px(11.))
                    .line_height(px(15.))
                    .text_color(wechat_theme::list_preview())
                    .child(SharedString::from(output.to_string())),
            );
        }
        return panel.into_any_element();
    }
    for line in info.lines.iter().take(MAX_LINES) {
        let (marker, color) = match line.kind {
            tool_render::DiffKind::Added => ("+", theme::success()),
            tool_render::DiffKind::Removed => ("-", theme::danger()),
            tool_render::DiffKind::Context => (" ", wechat_theme::list_preview()),
        };
        let text = if line.text.is_empty() {
            " ".to_string()
        } else {
            line.text.clone()
        };
        panel = panel.child(
            div()
                .w_full()
                .flex()
                .items_start()
                .gap(px(4.))
                .px(px(8.))
                .font_family(theme::FONT_MONO)
                .text_size(px(11.))
                .line_height(px(15.))
                .child(
                    div()
                        .w(px(22.))
                        .flex_shrink_0()
                        .text_right()
                        .text_color(wechat_theme::time_label())
                        .child(SharedString::from(
                            line.number.clone().unwrap_or_default(),
                        )),
                )
                .child(div().w(px(6.)).flex_shrink_0().text_color(color).child(marker))
                .child(
                    div()
                        .flex_1()
                        .min_w(px(0.))
                        .text_color(color)
                        .child(SharedString::from(text)),
                ),
        );
    }
    if info.lines.len() > MAX_LINES {
        panel = panel.child(
            div()
                .px(px(6.))
                .pt(px(1.))
                .font_family(wechat_theme::FONT_FAMILY)
                .text_size(px(11.))
                .line_height(px(15.))
                .text_color(wechat_theme::time_label())
                .child(SharedString::from(if i18n::is_en() {
                    format!("… {} more lines", info.lines.len() - MAX_LINES)
                } else {
                    format!("… 还有 {} 行", info.lines.len() - MAX_LINES)
                })),
        );
    }
    panel.into_any_element()
}

/// edit / write 工具卡：标题是文件路径，右侧是 +N/-M，展开为内联 diff。
fn wechat_edit_card(
    message: &Message,
    expanded: bool,
    weak: &gpui::WeakEntity<PilotApp>,
) -> gpui::AnyElement {
    let info = tool_render::edit_info(
        &message.tool_name,
        &message.tool_input,
        &message.tool_details,
    );
    let primary = info
        .as_ref()
        .map(|info| tool_render::single_line(&info.path, 96))
        .filter(|path| !path.is_empty())
        .unwrap_or_else(|| tool_primary_text(message));
    let counts = info
        .as_ref()
        .map(|info| (info.added, info.removed))
        .filter(|(added, removed)| added + removed > 0);
    let has_content = info
        .as_ref()
        .is_some_and(|info| !info.lines.is_empty())
        || !message.tool_detail.trim().is_empty();
    let call_id = message.tool_call_id.clone();
    let key = call_id.clone();
    let action_weak = weak.clone();
    let weak = weak.clone();
    let header = tool_row_base(
        icons::Icon::Pencil,
        &message.tool_state,
        &primary,
        counts,
        has_content,
        expanded,
    )
    .id(SharedString::from(format!("tool-toggle-{call_id}")))
    .when(has_content, |el| {
        el.pointer()
            .hover(|style| style.opacity(0.9))
            .on_click(move |_event, _window, cx| {
                let key = key.clone();
                let _ = weak.update(cx, |this, cx| {
                    if !this.tool_expanded.remove(&key) {
                        this.tool_expanded.insert(key.clone());
                    }
                    cx.notify();
                });
            })
    });
    let body = (expanded && has_content).then(|| {
        let panel = info
            .as_ref()
            .map(|info| edit_diff_panel(info, &message.tool_detail))
            .unwrap_or_else(|| {
                div()
                    .w_full()
                    .rounded(px(theme::RADIUS_FIELD))
                    .border_1()
                    .border_color(wechat_theme::composer_border())
                    .bg(wechat_theme::panel_card_bg())
                    .px(px(10.))
                    .py(px(8.))
                    .font_family(theme::FONT_MONO)
                    .text_size(px(11.))
                    .line_height(px(15.))
                    .text_color(wechat_theme::list_preview())
                    .child(SharedString::from(capped_text(&message.tool_detail, 40)))
                    .into_any_element()
            });
        let actions = info.as_ref().map(|info| {
            let mut actions = Vec::new();
            if !info.path.is_empty() {
                actions.push(("复制路径", info.path.clone()));
            }
            let diff = edit_info_text(info);
            if !diff.is_empty() {
                actions.push(("复制 diff", diff));
            }
            tool_actions_row(&message.tool_call_id, actions, &action_weak)
        });
        div()
            .flex()
            .flex_col()
            .gap(px(2.))
            .child(panel)
            .children(tool_images_row(
                &message.tool_images,
                &message.tool_call_id,
                &action_weak,
            ))
            .children(actions)
            .into_any_element()
    });
    div().w_full().flex().justify_start().child(
        div()
            .w_full()
            .flex()
            .flex_col()
            .gap(px(2.))
            .child(header)
            .children(body),
    )
    .into_any_element()
}

/// bash / powershell 工具卡：标题是命令（或描述），展开为 `$ 命令` + 输出 + 退出码。
fn wechat_exec_card(
    message: &Message,
    expanded: bool,
    weak: &gpui::WeakEntity<PilotApp>,
) -> gpui::AnyElement {
    let info = tool_render::exec_info(&message.tool_input, &message.tool_details);
    let command = info
        .as_ref()
        .map(|info| info.command.clone())
        .unwrap_or_default();
    let primary = info
        .as_ref()
        .map(|info| {
            if info.description.trim().is_empty() {
                tool_render::single_line(&info.command, 96)
            } else {
                tool_render::single_line(&info.description, 96)
            }
        })
        .filter(|text| !text.is_empty())
        .unwrap_or_else(|| tool_primary_text(message));
    let has_content = !command.trim().is_empty() || !message.tool_detail.trim().is_empty();
    let call_id = message.tool_call_id.clone();
    let key = call_id.clone();
    let action_weak = weak.clone();
    let weak = weak.clone();
    let header = tool_row_base(
        icons::Icon::Terminal,
        &message.tool_state,
        &primary,
        None,
        has_content,
        expanded,
    )
    .id(SharedString::from(format!("tool-toggle-{call_id}")))
    .when(has_content, |el| {
        el.pointer()
            .hover(|style| style.opacity(0.9))
            .on_click(move |_event, _window, cx| {
                let key = key.clone();
                let _ = weak.update(cx, |this, cx| {
                    if !this.tool_expanded.remove(&key) {
                        this.tool_expanded.insert(key.clone());
                    }
                    cx.notify();
                });
            })
    });
    let body = (expanded && has_content).then(|| {
        let mut panel = div()
            .w_full()
            .rounded(px(theme::RADIUS_FIELD))
            .border_1()
            .border_color(wechat_theme::composer_border())
            .bg(wechat_theme::panel_card_bg())
            .px(px(10.))
            .py(px(8.))
            .flex()
            .flex_col()
            .gap(px(6.));
        if !command.trim().is_empty() {
            panel = panel.child(
                div()
                    .w_full()
                    .flex()
                    .items_start()
                    .gap(px(4.))
                    .font_family(theme::FONT_MONO)
                    .text_size(px(11.))
                    .line_height(px(15.))
                    .child(
                        div()
                            .flex_shrink_0()
                            .text_color(wechat_theme::time_label())
                            .child("$"),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_w(px(0.))
                            .text_color(wechat_theme::chat_title())
                            .child(SharedString::from(command.clone())),
                    ),
            );
        }
        // WebView 的输出区是 5 行高的小视口；聊天里保留 12 行 + 剩余提示，兼顾可读与占位。
        const MAX_OUTPUT_LINES: usize = 12;
        let output = message.tool_detail.trim();
        if output.is_empty() {
            if message.tool_state == "running" {
                panel = panel.child(
                    div()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(11.))
                        .line_height(px(15.))
                        .text_color(wechat_theme::time_label())
                        .child(i18n::t("等待输出…")),
                );
            }
        } else {
            panel = panel.child(
                div()
                    .w_full()
                    .font_family(theme::FONT_MONO)
                    .text_size(px(11.))
                    .line_height(px(15.))
                    .text_color(wechat_theme::list_preview())
                    .child(SharedString::from(capped_text(output, MAX_OUTPUT_LINES))),
            );
        }
        if let Some(exit_code) = info.as_ref().and_then(|info| info.exit_code) {
            let failed = exit_code != 0;
            let label = if i18n::is_en() {
                format!("exit code {exit_code}")
            } else {
                format!("退出码 {exit_code}")
            };
            panel = panel.child(
                div()
                    .font_family(theme::FONT_MONO)
                    .text_size(px(11.))
                    .line_height(px(15.))
                    .text_color(if failed {
                        theme::danger()
                    } else {
                        wechat_theme::time_label()
                    })
                    .child(SharedString::from(label)),
            );
        }
        if let Some(images) = tool_images_row(
            &message.tool_images,
            &message.tool_call_id,
            &action_weak,
        ) {
            panel = panel.child(images);
        }
        let mut actions = Vec::new();
        if !command.trim().is_empty() {
            actions.push(("复制命令", command.clone()));
        }
        if !message.tool_detail.trim().is_empty() {
            actions.push(("复制输出", message.tool_detail.clone()));
        }
        if !actions.is_empty() {
            panel = panel.child(tool_actions_row(&message.tool_call_id, actions, &action_weak));
        }
        panel
    });
    div().w_full().flex().justify_start().child(
        div()
            .w_full()
            .flex()
            .flex_col()
            .gap(px(2.))
            .child(header)
            .children(body),
    )
    .into_any_element()
}

fn family_icon(family: tool_render::ToolFamily) -> icons::Icon {
    match family {
        tool_render::ToolFamily::Execute => icons::Icon::Terminal,
        tool_render::ToolFamily::Edit => icons::Icon::Pencil,
        tool_render::ToolFamily::Search => icons::Icon::Search,
        tool_render::ToolFamily::Read => icons::Icon::Folder,
        tool_render::ToolFamily::Cua => icons::Icon::Monitor,
        tool_render::ToolFamily::Other => icons::Icon::Terminal,
    }
}

fn tool_group_summary(family: tool_render::ToolFamily, count: usize, unique_files: usize) -> String {
    if i18n::is_en() {
        match family {
            tool_render::ToolFamily::Execute => format!("Executed {count} commands"),
            tool_render::ToolFamily::Edit if unique_files < count => {
                format!("{count} edits in {unique_files} files")
            }
            tool_render::ToolFamily::Edit => format!("Edited {unique_files} files"),
            tool_render::ToolFamily::Search => format!("Searched {count} times"),
            tool_render::ToolFamily::Read => format!("Read {count} items"),
            tool_render::ToolFamily::Cua => format!("{count} computer steps"),
            tool_render::ToolFamily::Other => format!("{count} tool calls"),
        }
    } else {
        match family {
            tool_render::ToolFamily::Execute => format!("执行了 {count} 条命令"),
            tool_render::ToolFamily::Edit if unique_files < count => {
                format!("编辑了 {count} 次（{unique_files} 个文件）")
            }
            tool_render::ToolFamily::Edit => format!("编辑了 {unique_files} 个文件"),
            tool_render::ToolFamily::Search => format!("搜索了 {count} 次"),
            tool_render::ToolFamily::Read => format!("读取了 {count} 项"),
            tool_render::ToolFamily::Cua => format!("操作了 {count} 步"),
            tool_render::ToolFamily::Other => format!("调用了 {count} 次工具"),
        }
    }
}

/// 连续同类工具调用折叠卡（execute/edit/search/read/cua 组）。
fn wechat_tool_group_card(
    key: &str,
    family: tool_render::ToolFamily,
    messages: &[(Message, bool)],
    expanded: bool,
    weak: &gpui::WeakEntity<PilotApp>,
) -> gpui::AnyElement {
    let mut running = false;
    let mut failed = false;
    for (message, _) in messages {
        match message.tool_state.as_str() {
            "running" | "pending" => running = true,
            "error" => failed = true,
            _ => {}
        }
    }
    let state = if running {
        "running"
    } else if failed {
        "error"
    } else {
        "done"
    };
    let mut added = 0;
    let mut removed = 0;
    let mut files = HashSet::new();
    if family == tool_render::ToolFamily::Edit {
        for (message, _) in messages {
            if let Some(info) = tool_render::edit_info(
                &message.tool_name,
                &message.tool_input,
                &message.tool_details,
            ) {
                added += info.added;
                removed += info.removed;
                if !info.path.is_empty() {
                    files.insert(info.path);
                }
            }
        }
    }
    let unique_files = if family == tool_render::ToolFamily::Edit && !files.is_empty() {
        files.len()
    } else {
        messages.len()
    };
    let summary = tool_group_summary(family, messages.len(), unique_files);
    let toggle_key = key.to_string();
    let click_weak = weak.clone();
    let header = tool_row_base(
        family_icon(family),
        state,
        &summary,
        Some((added, removed)),
        true,
        expanded,
    )
    .id(SharedString::from(format!("tool-group-{key}")))
    .pointer()
    .hover(|style| style.opacity(0.9))
    .on_click(move |_event, _window, cx| {
        let key = toggle_key.clone();
        let _ = click_weak.update(cx, |this, cx| {
            if !this.tool_group_expanded.remove(&key) {
                this.tool_group_expanded.insert(key.clone());
            }
            cx.notify();
        });
    });
    let mut inner = div()
        .w_full()
        .flex()
        .flex_col()
        .gap(px(2.))
        .child(header);
    if expanded {
        let mut children = div().w_full().flex().flex_col().gap(px(2.)).pl(px(4.));
        for (message, child_expanded) in messages {
            // 组头已经写了「已执行」，子行不再重复状态词（省宽度也省视觉噪音）；
            // 运行中/失败仍保留，方便定位是哪一条。
            let mut child = message.clone();
            if child.tool_state == "done" {
                child.tool_state.clear();
            }
            children = children.child(wechat_tool_card(&child, *child_expanded, weak));
        }
        inner = inner.child(children);
    }
    div().w_full().flex().justify_start().child(inner).into_any_element()
}

fn wechat_tool_card(
    message: &Message,
    expanded: bool,
    weak: &gpui::WeakEntity<PilotApp>,
) -> gpui::AnyElement {
    match tool_render::family(&message.tool_name) {
        tool_render::ToolFamily::Edit => wechat_edit_card(message, expanded, weak),
        tool_render::ToolFamily::Execute => wechat_exec_card(message, expanded, weak),
        _ => {
            let has_detail = !message.tool_detail.trim().is_empty()
                || !message.tool_details.trim().is_empty();
            let call_id = message.tool_call_id.clone();
            let key = call_id.clone();
            let action_weak = weak.clone();
            let weak = weak.clone();
            let family = tool_render::family(&message.tool_name);
            let mut primary = tool_primary_text(message);
            // 搜索类在标题尾附结果行数，收起态也能看到规模。
            if family == tool_render::ToolFamily::Search {
                let hits = message
                    .tool_detail
                    .lines()
                    .filter(|line| !line.trim().is_empty())
                    .count();
                if hits > 0 {
                    primary = if i18n::is_en() {
                        format!("{primary} · {hits} results")
                    } else {
                        format!("{primary} · {hits} 条结果")
                    };
                }
            }
            let icon = if family == tool_render::ToolFamily::Other {
                tool_icon(&message.tool_name)
            } else {
                family_icon(family)
            };
            let header = tool_row_base(
                icon,
                &message.tool_state,
                &primary,
                None,
                has_detail,
                expanded,
            )
            .id(SharedString::from(format!("tool-toggle-{call_id}")))
            .when(has_detail, |el| {
                el.pointer()
                    .hover(|style| style.opacity(0.9))
                    .on_click(move |_event, _window, cx| {
                        let key = key.clone();
                        let _ = weak.update(cx, |this, cx| {
                            if !this.tool_expanded.remove(&key) {
                                this.tool_expanded.insert(key.clone());
                            }
                            cx.notify();
                        });
                    })
            });
            let detail = if message.tool_detail.trim().is_empty() {
                message.tool_details.clone()
            } else {
                message.tool_detail.clone()
            };
            div().w_full().flex().justify_start().child(
                div()
                    .w_full()
                    .flex()
                    .flex_col()
                    .gap(px(2.))
                    .child(header)
                    .children((expanded && has_detail).then(|| {
                        div()
                            .flex()
                            .flex_col()
                            .gap(px(2.))
                            .child(
                                div()
                                    .w_full()
                                    .rounded(px(theme::RADIUS_FIELD))
                                    .border_1()
                                    .border_color(wechat_theme::composer_border())
                                    .bg(wechat_theme::panel_card_bg())
                                    .px(px(10.))
                                    .py(px(8.))
                                    .font_family(theme::FONT_MONO)
                                    .text_size(px(11.))
                                    .line_height(px(15.))
                                    .text_color(wechat_theme::list_preview())
                                    .child(SharedString::from(capped_text(&detail, 40))),
                            )
                            .children(tool_images_row(
                                &message.tool_images,
                                &message.tool_call_id,
                                &action_weak,
                            ))
                            .child(tool_actions_row(
                                &message.tool_call_id,
                                vec![("复制详情", detail.clone())],
                                &action_weak,
                            ))
                    })),
            )
            .into_any_element()
        }
    }
}

impl PilotApp {

    fn wechat_shell(&mut self, window: &mut Window, cx: &mut Context<Self>) -> gpui::AnyElement {
        div()
            .flex()
            .flex_col()
            .flex_1()
            .min_h(px(0.))
            .w_full()
            .bg(wechat_theme::window_bg())
            .child(self.wechat_titlebar(window, cx))
            .child({
                let mut body = div()
                    .flex()
                    .flex_1()
                    .min_h(px(0.))
                    .w_full()
                    .child(self.wechat_nav(cx));
                if self.settings_open {
                    body = body
                        .child(self.wechat_list(window, cx))
                        .child(self.wechat_settings_view(window, cx));
                    // 详情面板是横向第三列，必须挂在 body 上，而不是设置视图内部
                    // （设置视图是 flex_col，挂进去会被竖着堆到最下面）。
                    if self.settings_detail.is_some() {
                        body = body.children(self.settings_detail_panel(window, cx));
                    }
                } else {
                    body = body
                        .child(self.wechat_list(window, cx))
                        .child(self.wechat_chat(window, cx));
                    // DS bot 的布局：会话右侧常驻详情栏（模型 / 运行状态 / 文件改动）
                    if self.right_panel_open {
                        body = body.child(self.chat_info_panel(window, cx));
                    }
                }
                body
            })
            .into_any_element()
    }

    fn wechat_titlebar(
        &self,
        window: &Window,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let maximize_icon = if window.is_maximized() {
            icons::Icon::WindowRestore
        } else {
            icons::Icon::WindowMaximize
        };
        let topmost = self.topmost;
        div()
            .h(px(wechat_theme::TITLEBAR_HEIGHT))
            .flex_shrink_0()
            .w_full()
            .flex()
            .items_center()
            .bg(wechat_theme::titlebar_bg())
            .text_color(wechat_theme::nav_text())
            .child(
                div()
                    .window_control_area(WindowControlArea::Drag)
                    .flex_1()
                    .h_full(),
            )
            .child(
                div()
                    .id("wechat-pin-topmost")
                    .w(px(44.))
                    .h(px(28.))
                    .flex()
                    .items_center()
                    .justify_center()
                    .pointer()
                    .when(topmost, |el| {
                        el.bg(wechat_theme::nav_item_selected_bg())
                    })
                    .when(!topmost, |el| {
                        el.hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                    })
                    .on_click(cx.listener(|this, _event, _window, cx| {
                        this.topmost = !this.topmost;
                        save_ui_prefs(
                            &this.muted,
                            this.topmost,
                            &this.pinned_settings,
                            this.right_panel_open,
                        );
                        window_style::set_topmost(this.topmost);
                        this.toast(if this.topmost { i18n::t("窗口已置顶") } else { i18n::t("已取消置顶") }, cx);
                        cx.notify();
                    }))
                    .child(icons::icon_light(
                        icons::Icon::Pushpin,
                        menu_icons::TITLEBAR_SIZE,
                        if topmost { wechat_theme::nav_text_active() } else { wechat_theme::icon() },
                    )),
            )
            .child(
                div()
                    .flex()
                    .items_center()
                    .child(self.wechat_window_button(
                        "wechat-win-min",
                        icons::Icon::Minus,
                        false,
                        |_window| window_style::minimize(),
                    ))
                    .child(self.wechat_window_button(
                        "wechat-win-max",
                        maximize_icon,
                        false,
                        |window| {
                            if let Some(geometry) = current_geometry(window) {
                                window_state::remember(geometry);
                            }
                            window_style::toggle_maximize();
                        },
                    ))
                    .child(self.wechat_window_button(
                        "wechat-win-close",
                        icons::Icon::X,
                        true,
                        |window| {
                            close_or_hide(window);
                        },
                    )),
            )
    }

    fn wechat_window_button(
        &self,
        id: &'static str,
        glyph: icons::Icon,
        danger: bool,
        action: impl Fn(&mut Window) + 'static,
    ) -> impl IntoElement {
        let base = div()
            .id(id)
            .w(px(44.))
            .h(px(28.))
            .flex()
            .items_center()
            .justify_center()
            .pointer();
        let base = if danger {
            base.hover(|style| style.bg(wechat_theme::nav_badge_bg()))
        } else {
            base.hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
        };
        // 最小化/最大化的直线更密，改用 light 字重，和关闭图标观感一致。
        let light = matches!(
            glyph,
            icons::Icon::Minus | icons::Icon::WindowMaximize | icons::Icon::WindowRestore
        );
        let icon = if light {
            icons::icon_light(glyph, menu_icons::TITLEBAR_SIZE, wechat_theme::icon())
                .into_any_element()
        } else {
            icons::icon(glyph, menu_icons::TITLEBAR_SIZE, wechat_theme::icon()).into_any_element()
        };
        base.on_click(move |_: &gpui::ClickEvent, window, _| action(window))
            .child(icon)
    }

    /// 企业微信的彩色首字方块头像（10px 圆角）。
    fn wechat_avatar(id: &str, name: &str, size: f32) -> gpui::AnyElement {
        if let Some(appearance) = bot_icon::get(id) {
            return avatar::bot_icon_tile(&appearance.icon, &appearance.color, size, 6.);
        }
        div()
            .size(px(size))
            .flex_shrink_0()
            .rounded(px(theme::RADIUS_CHIP))
            .bg(wechat_theme::avatar_color(id))
            .flex()
            .items_center()
            .justify_center()
            .child(
                div()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(size * 0.42))
                    .font_weight(gpui::FontWeight::SEMIBOLD)
                    .text_color(wechat_theme::nav_text_active())
                    .child(name.chars().next().unwrap_or('B').to_string()),
            )
            .into_any_element()
    }

    /// 微信群头像：灰白底 + 最多 9 个成员头像，按人数自适应布局。
    fn wechat_group_avatar(ids: &[String], size: f32) -> impl IntoElement {
        let members: Vec<&String> = ids.iter().take(9).collect();
        let count = members.len();
        let pad = 1.5;
        let gap = 1.0;
        let inner = size - pad * 2.0;
        let cell = |id: &String, w: f32, h: f32| -> gpui::AnyElement {
            avatar::bot_avatar_rect(id, w, h, 6.0).into_any_element()
        };
        let mut grid = div()
            .size(px(size))
            .flex_shrink_0()
            .rounded(px(theme::RADIUS_CHIP))
            .overflow_hidden()
            .bg(wechat_theme::group_avatar_bg())
            .p(px(pad))
            .flex()
            .flex_col()
            .gap(px(gap));
        match count {
            0 => {}
            1 => {
                grid = grid.child(cell(members[0], inner, inner));
            }
            2 => {
                // 两个成员也保持正方形，整体在灰白底上居中。
                let side = (inner - gap) / 2.0;
                grid = grid.child(
                    div()
                        .flex_1()
                        .flex()
                        .items_center()
                        .justify_center()
                        .gap(px(gap))
                        .child(cell(members[0], side, side))
                        .child(cell(members[1], side, side)),
                );
            }
            3 => {
                let side = (inner - gap) / 2.0;
                grid = grid
                    .child(
                        div()
                            .flex()
                            .justify_center()
                            .child(cell(members[0], side, side)),
                    )
                    .child(
                        div()
                            .flex()
                            .gap(px(gap))
                            .child(cell(members[1], side, side))
                            .child(cell(members[2], side, side)),
                    );
            }
            4 => {
                let side = (inner - gap) / 2.0;
                for row in 0..2 {
                    grid = grid.child(
                        div()
                            .flex()
                            .gap(px(gap))
                            .child(cell(members[row * 2], side, side))
                            .child(cell(members[row * 2 + 1], side, side)),
                    );
                }
            }
            _ => {
                let side = (inner - gap * 2.0) / 3.0;
                for row in 0..3 {
                    let mut line = div().flex().gap(px(gap));
                    for col in 0..3 {
                        let index = row * 3 + col;
                        line = match members.get(index) {
                            Some(id) => line.child(cell(id, side, side)),
                            None => line.child(div().w(px(side)).h(px(side))),
                        };
                    }
                    grid = grid.child(line);
                }
            }
        }
        grid
    }

    fn wechat_channel_avatar(id: &str, size: f32) -> impl IntoElement {
        div()
            .size(px(size))
            .flex_shrink_0()
            .rounded(px(theme::RADIUS_TAG))
            .bg(wechat_theme::avatar_color(id))
            .flex()
            .items_center()
            .justify_center()
            .child(icons::icon(
                icons::Icon::Hash,
                size * 0.52,
                wechat_theme::nav_text_active(),
            ))
    }

    fn wechat_nav(&mut self, cx: &mut Context<Self>) -> impl IntoElement {
        let current = self.wechat_nav;
        let total_unread: usize = self
            .chats
            .values()
            .map(|chat| chat.unread)
            .sum();
        let mut rail = div()
            .w(px(wechat_theme::NAV_WIDTH))
            .flex_shrink_0()
            .h_full()
            .flex()
            .flex_col()
            .items_center()
            .bg(wechat_theme::nav_gradient())
            .pt(px(12.))
            .pb(px(12.))
            .gap(px(4.));
        // 顶部用户头像（圆形 + 在线绿点）
        rail = rail.child(
            div()
                .id("wechat-me")
                .relative()
                .pointer()
                .hover(|style| style.bg(theme::hover()))
                .on_click(cx.listener(|this, _event, _window, cx| {
                    this.me_card_open = !this.me_card_open;
                    this.detail_menu_open = false;
                    this.footer_menu_open = false;
                    cx.notify();
                }))
                .child(avatar::app_avatar(36., 6.))
                .child(
                    div()
                        .absolute()
                        .right(px(0.))
                        .bottom(px(0.))
                        .size(px(10.))
                        .rounded_full()
                        .bg(wechat_theme::online_dot())
                        .border_2()
                        .border_color(wechat_theme::titlebar_bg()),
                ),
        );
        rail = rail.child(div().h(px(8.)));
        let filters = [
            (WecomNav::All, menu_icons::MenuIcon::Chat, i18n::t("消息")),
            (WecomNav::Bots, menu_icons::MenuIcon::Contacts, i18n::t("通讯录")),
            (WecomNav::Channels, menu_icons::MenuIcon::Channels, i18n::t("群聊")),
        ];
        for (filter, icon, label) in filters {
            let active = current == filter && !self.settings_open;
            rail = rail.child(
                div()
                    .id(SharedString::from(format!("wechat-rail-{label}")))
                    .relative()
                    .size(px(36.)).my(px(4.))
                    .rounded(px(theme::RADIUS_CHIP))
                    .flex()
                    .items_center()
                    .justify_center()
                    .pointer()
                    .bg(gpui::rgba(0x00000000))
                    .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                    .on_click(cx.listener(move |this, _event, _window, cx| {
                        this.wechat_nav = filter;
                        this.settings_open = false;
                        this.ensure_wechat_selection(cx);
                        cx.notify();
                    }))
                    .child(menu_icons::menu_icon_with_weight(
                        icon,
                        active,
                        menu_icons::RAIL_SIZE,
                        if active {
                            wechat_theme::send_enabled()
                        } else {
                            wechat_theme::nav_icon()
                        },
                        true,
                    ))
                    .children((filter == WecomNav::All && total_unread > 0).then(|| {
                        div()
                            .absolute()
                            .top(px(2.))
                            .right(px(2.))
                            .min_w(px(16.))
                            .h(px(16.))
                            .px(px(4.))
                            .rounded_full()
                            .bg(wechat_theme::nav_badge_bg())
                            .flex()
                            .items_center()
                            .justify_center()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(11.))
                            .font_weight(gpui::FontWeight::MEDIUM)
                            .text_color(wechat_theme::nav_text_active())
                            .child(SharedString::from(if total_unread > 99 {
                                "99+".to_string()
                            } else {
                                total_unread.to_string()
                            }))
                    })),
            );
        }
        for tab in self.pinned_settings.clone() {
            let active = self.settings_open && self.settings_tab == tab;
            rail = rail.child(
                div()
                    .id(SharedString::from(format!("wechat-pinned-settings-{tab}")))
                    .size(px(36.)).my(px(4.))
                    .rounded(px(theme::RADIUS_CHIP))
                    .flex()
                    .items_center()
                    .justify_center()
                    .pointer()
                    .bg(gpui::rgba(0x00000000))
                    .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                    .on_click(cx.listener(move |this, _event, _window, cx| {
                        this.open_settings_at(tab, _window, cx);
                        cx.notify();
                    }))
                    .child(menu_icons::menu_icon_with_weight(
                        settings_page_icon(tab),
                        active,
                        menu_icons::RAIL_SIZE,
                        if active {
                            wechat_theme::send_enabled()
                        } else {
                            wechat_theme::nav_icon()
                        },
                        true,
                    )),
            );
        }
        rail.child(div().flex_1()).child(
            div()
                .id("wechat-rail-settings")
                .size(px(36.)).my(px(4.))
                .rounded(px(theme::RADIUS_CHIP))
                .flex()
                .items_center()
                .justify_center()
                .pointer()
                .bg(gpui::rgba(0x00000000))
                .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                .on_click(cx.listener(|this, _event, _window, cx| {
                    // 设置页头不再放关闭按钮；导轨齿轮同时承担开/关。
                    this.settings_open = !this.settings_open;
                    if this.settings_open {
                        // 每次打开都让定时任务/用量页重读快照。
                        this.automations_view = None;
                        this.usage_grouped_view = None;
                        // 焦点交给设置页，Esc 才能在任意页立即关闭（否则被输入框吃掉）。
                        this.settings_focus.clone().focus(_window, cx);
                    } else {
                        this.refocus_composer_if_clear(_window, cx);
                    }
                    cx.notify();
                }))
                .child(menu_icons::menu_icon_with_weight(
                    menu_icons::MenuIcon::Gear,
                    self.settings_open,
                    menu_icons::RAIL_SIZE,
                    if self.settings_open {
                        wechat_theme::send_enabled()
                    } else {
                        wechat_theme::nav_icon()
                    },
                    true,
                )),
        )
    }

    fn ensure_wechat_selection(&mut self, cx: &mut Context<Self>) {
        match self.wechat_nav {
            WecomNav::Channels => {
                if self.selected_group().is_none()
                    && let Some(index) = self.roster.groups.iter().position(|_| true)
                {
                    self.select_group(index, cx);
                }
            }
            WecomNav::Bots => {
                if self.selected_bot().is_none()
                    && let Some(index) = self.roster.bots.iter().position(|_| true)
                {
                    self.select_bot(index, cx);
                }
            }
            WecomNav::All => {}
        }
    }

    fn wechat_entries(&self, cx: &App) -> Vec<WecomEntry> {
        let query = self.search_input.read(cx).content().trim().to_lowercase();
        let mut entries = Vec::new();
        let mut push = |is_group: bool,
                        index: usize,
                        id: String,
                        name: String,
                        fallback: String,
                        at: u64,
                        pinned: bool,
                        unread: usize,
                        active: bool,
                        member_ids: Vec<String>| {
            if !query.is_empty() && !name.to_lowercase().contains(&query) {
                return;
            }
            let key = if is_group {
                group_key(&id)
            } else {
                bot_key(&id)
            };
            // 预览只要 32 字符：先截前 96 字符再压空白，
            // 避免对整条消息做 split+collect+join（长度与消息成正比）。
            let preview = self
                .chats
                .get(&key)
                .and_then(|chat| {
                    chat.messages
                        .iter()
                        .rev()
                        .find(|message| !message.text.trim().is_empty())
                        .map(|message| collapse_whitespace_prefix(&message.text, 96))
                })
                .map(|text| truncate_chars(&text, 32))
                .filter(|text| !text.is_empty())
                .unwrap_or(fallback);
            entries.push(WecomEntry {
                is_group,
                index,
                id,
                name,
                preview,
                at,
                pinned,
                unread,
                active,
                muted: self.muted.contains(&key),
                member_ids,
                status: chat_runtime_status(self.chats.get(&key)),
            });
        };
        if self.wechat_nav != WecomNav::Channels {
            for (index, bot) in self.roster.bots.iter().enumerate() {
                let chat = self.chats.get(&bot_key(&bot.id));
                let at = chat
                    .and_then(|chat| chat.messages.last().map(|message| message.at))
                    .unwrap_or(0);
                push(
                    false,
                    index,
                    bot.id.clone(),
                    bot.name.clone(),
                    if bot.role.is_empty() {
                        i18n::t("暂无消息").to_string()
                    } else {
                        bot.role.clone()
                    },
                    at,
                    bot.pinned,
                    chat.map(|chat| chat.unread).unwrap_or(0),
                    self.selection == Some(Selection::Bot(index)),
                    Vec::new(),
                );
            }
        }
        if self.wechat_nav != WecomNav::Bots {
            for (index, group) in self.roster.groups.iter().enumerate() {
                let chat = self.chats.get(&group_key(&group.id));
                let at = chat
                    .and_then(|chat| chat.messages.last().map(|message| message.at))
                    .unwrap_or(0);
                push(
                    true,
                    index,
                    group.id.clone(),
                    group.name.clone(),
                    count_members(visible_group_members(group, &self.roster).len()),
                    at,
                    group.pinned,
                    chat.map(|chat| chat.unread).unwrap_or(0),
                    self.selection == Some(Selection::Group(index)),
                    group
                        .member_ids
                        .iter()
                        .filter(|id| self.roster.bot_by_id(id).is_some())
                        .take(4)
                        .cloned()
                        .collect(),
                );
            }
        }
        entries.sort_by(|a, b| {
            b.pinned
                .cmp(&a.pinned)
                .then_with(|| b.at.cmp(&a.at))
                .then_with(|| a.name.cmp(&b.name))
        });
        entries
    }

    /// 侧栏分组后的列表行：未分组条目在前，之后是各分组标题 + 成员（折叠时只留标题）。
    fn wechat_list_rows(&self, cx: &App) -> Vec<WecomListRow> {
        let entries = self.wechat_entries(cx);
        if self.sidebar_sections.sections.is_empty() {
            return entries.into_iter().map(WecomListRow::Entry).collect();
        }
        let section_ids: std::collections::HashSet<String> = self
            .sidebar_sections
            .sections
            .iter()
            .map(|section| section.id.clone())
            .collect();
        let mut ungrouped = Vec::new();
        let mut grouped: HashMap<String, Vec<WecomEntry>> = HashMap::new();
        for entry in entries {
            let key = wechat_entry_key(&entry);
            match self.sidebar_sections.membership.get(&key) {
                Some(section_id) if section_ids.contains(section_id) => {
                    grouped.entry(section_id.clone()).or_default().push(entry);
                }
                _ => ungrouped.push(entry),
            }
        }
        let mut rows: Vec<WecomListRow> = ungrouped.into_iter().map(WecomListRow::Entry).collect();
        for section in &self.sidebar_sections.sections {
            let items = grouped.remove(&section.id).unwrap_or_default();
            rows.push(WecomListRow::Section {
                id: section.id.clone(),
                name: section.name.clone(),
                color: section.color.clone(),
                collapsed: section.collapsed,
                count: items.len(),
            });
            if !section.collapsed {
                rows.extend(items.into_iter().map(WecomListRow::Entry));
            }
        }
        rows
    }

    fn wechat_list(&mut self, window: &Window, cx: &mut Context<Self>) -> impl IntoElement {
        // 设置页菜单与会话列表同宽（246），切页时左列不跳变。
        let list = div()
            .w(px(wechat_theme::LIST_WIDTH))
            .flex_shrink_0()
            .h_full()
            .flex()
            .flex_col()
            .bg(wechat_theme::list_gradient());
        if self.settings_open {
            // 行本身通栏到侧栏边缘，内容缩进放在行内；滚动条占右侧 6px。
            let mut rows = div()
                .flex()
                .flex_col()
                .gap(px(2.));
        for (index, label) in SETTINGS_PAGES.iter().enumerate() {
            // 浏览器 / 电脑操控已并入「插件」页，不再单独占菜单项。
            if !settings_page_in_nav(index) {
                continue;
            }
            let active = self.settings_tab == index;
            let pinned = self.pinned_settings.contains(&index);
            if index == 12 {
                    rows = rows.child(
                        div()
                            .mx(px(8.))
                            .my(px(6.))
                            .h(px(0.5))
                            .bg(wechat_theme::divider()),
                    );
                }
                // 尾部信息页照 DS 用次级色（关于/反馈/浏览器/电脑操控/更多）。
                let secondary = index >= 12;
                let nav_focus = self.tab_focus[settings_nav_focus_key(index)].clone();
                let nav_focused = nav_focus.is_focused(window);
                rows = rows.child(
                    div()
                        .id(SharedString::from(format!("wechat-set-{index}")))
                        .track_focus(&nav_focus)
                        .key_context("TabStop")
                        // 焦点态只用底色 + inset 阴影：border 会增加元素宽度，
                        // 把固定 246px 宽的侧栏撑破（实测整体错位 3px）。
                        .when(nav_focused, |el| {
                            el.bg(wechat_theme::nav_item_hover_bg())
                                .shadow(vec![focus_ring_left(wechat_theme::send_enabled())])
                        })
                        .on_action(cx.listener(
                            move |this, _: &ActivateTabStop, window, cx| {
                                this.settings_tab = index;
                                this.im_create = None;
                                this.im_qr_page = None;
                                this.automations_view = None;
                                this.usage_grouped_view = None;
                                this.settings_focus.focus(window, cx);
                                cx.notify();
                            },
                        ))
                        .h(px(40.))
                        // 滚动条槽占 6px：反向抵消，选中/悬浮底色才铺到面板右缘。
                        .mr(px(-6.))
                        .pl(px(16.))
                        .pr(px(16.))
                        .flex()
                        .items_center()
                        .gap(px(8.))
                        .pointer()
                        .when(active, |el| el.bg(wechat_theme::send_enabled()))
                        .when(!active, |el| {
                            el.hover(|style| style.bg(wechat_theme::list_hover()))
                        })
                        .on_click(cx.listener(move |this, _event, window, cx| {
                            this.settings_tab = index;
                            this.im_create = None;
                            this.im_qr_page = None;
                            // 定时任务页读的是快照：切页必须让它重读，否则 Bot 刚用
                            // automation_create 建的任务在页面上仍显示「还没有定时任务」。
                            this.automations_view = None;
                            this.usage_grouped_view = None;
                            cx.notify();
                            // 点导航不产生焦点，Esc 会因无焦点元素而丢键：把焦点留在设置页上。
                            this.settings_focus.focus(window, cx);
                        }))
                        .child(menu_icons::menu_icon(
                            settings_page_icon(index),
                            false,
                            menu_icons::SETTINGS_SIZE,
                            if active {
                                theme::accent_ink()
                            } else if secondary {
                                wechat_theme::time_label()
                            } else {
                                wechat_theme::icon()
                            },
                        ))
                        .child(
                            div()
                                .flex_1()
                                .min_w(px(0.))
                                .truncate()
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(13.))
                                .line_height(px(18.))
                                .text_color(if active {
                                    wechat_theme::list_title_selected()
                                } else if secondary {
                                    wechat_theme::time_label()
                                } else {
                                    wechat_theme::list_title()
                                })
                                .child(i18n::t(label)),
                        )
                        .child(
                            div()
                                .id(SharedString::from(format!("wechat-set-pin-{index}")))
                                .size(px(16.))
                                .flex()
                                .items_center()
                                .justify_center()
                                .pointer()
                                .opacity(if pinned { 1.0 } else { 0.0 })
                                .when(active && !pinned, |el| {
                                    el.hover(|style| style.opacity(1.))
                                })
                                .on_click(cx.listener(move |this, _event, _window, cx| {
                                    cx.stop_propagation();
                                    this.toggle_pinned_setting(index, cx);
                                }))
                                .child(icons::icon(
                                    icons::Icon::Pin,
                                    13.,
                                    if active {
                                        theme::accent_ink()
                                    } else if pinned {
                                        wechat_theme::send_enabled()
                                    } else {
                                        wechat_theme::panel_text()
                                    },
                                )),
                        ),
                );
            }
            return list.child(
                div()
                    .id("wechat-settings-list")
                    .flex_1()
                    .min_h(px(0.))
                    .overflow_y_scroll()
                    .scrollbar_width(px(6.))
                    .py(px(16.))
                    .child(rows),
            );
        }
        let rows = self.wechat_list_rows(cx);
        let count = rows.len();
        let fingerprint = wechat_list_rows_fingerprint(&rows);
        if self.wechat_list_state.item_count() != count {
            self.wechat_list_state.reset(count);
            self.wechat_list_fingerprint = fingerprint;
        } else if self.wechat_list_fingerprint != fingerprint {
            if count > 0 {
                self.wechat_list_state.remeasure_items(0..count);
            }
            self.wechat_list_fingerprint = fingerprint;
        }
        let list_body: gpui::AnyElement = if rows.is_empty() {
            div()
                .py(px(24.))
                .text_center()
                .font_family(wechat_theme::FONT_FAMILY)
                .text_size(px(12.))
                .text_color(wechat_theme::list_preview())
                .child(i18n::t("没有匹配的会话"))
                .into_any_element()
        } else {
            let rows = std::sync::Arc::new(rows);
            let weak = cx.weak_entity();
            gpui::list(
                self.wechat_list_state.clone(),
                move |index, _window, _cx| wechat_list_row_el(&rows[index], &weak),
            )
            .size_full()
            .into_any_element()
        };
        list.child(
            div()
                .px(px(12.))
                .pt(px(12.))
                .pb(px(12.))
                .flex()
                .items_center()
                .gap(px(8.))
                .child(
                    div()
                        .id("wechat-search")
                        .flex_1()
                        .h(px(wechat_theme::SEARCH_HEIGHT))
                        .rounded(px(theme::RADIUS_TAG))
                        .border_1()
                        .border_color(wechat_theme::composer_border())
                        .bg(wechat_theme::search_bg())
                        .px(px(8.))
                        .flex()
                        .items_center()
                        .gap(px(6.))
                        .child(icons::icon(
                            icons::Icon::Search,
                            14.,
                            wechat_theme::list_preview(),
                        ))
                        .child(
                            div()
                                .flex_1()
                                .min_w(px(0.))
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(13.))
                                .line_height(px(18.))
                                .text_color(wechat_theme::list_title())
                                .child(self.search_input.clone()),
                        ),
                )
                .child(
                    div()
                        .id("wechat-new")
                        .size(px(28.))
                        .rounded_full()
                        .bg(wechat_theme::list_hover())
                        .flex()
                        .items_center()
                        .justify_center()
                        .pointer()
                        .hover(|style| style.bg(wechat_theme::list_hover()))
                        .on_click(cx.listener(|this, _event, _window, cx| {
                            this.new_menu_open = !this.new_menu_open;
                            this.footer_menu_open = false;
                            this.detail_menu_open = false;
                            cx.notify();
                        }))
                        .child(icons::icon(icons::Icon::Plus, 16., wechat_theme::icon())),
                ),
        )
        .child(
            div()
                .id("wechat-list")
                .flex_1()
                .min_h(px(0.))
                .child(list_body),
        )
    }

    fn wechat_settings_view(
        &mut self,
        window: &Window,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let title = match &self.im_create {
            Some(view) if view.provider == bots_service::BotProvider::Weixin => {
                i18n::t("新建微信机器人")
            }
            Some(_) => i18n::t("新建企业微信机器人"),
            None if self.im_qr_page.is_some() => i18n::t("扫码绑定"),
            None => i18n::t(SETTINGS_PAGES[self.settings_tab]),
        };
        let subpage = self.im_create.is_some() || self.im_qr_page.is_some();
        let tab = self.settings_tab;
        // 右侧主区：窗口 - 导轨 - 设置列表 - 页面左右内边距(14+8) - 滚动条槽(6)。
        let content_width = (f32::from(window.viewport_size().width)
            - wechat_theme::NAV_WIDTH
            - wechat_theme::LIST_WIDTH
            - 28.
            - if self.settings_detail.is_some() {
                ui_kit::PANEL_W
            } else {
                0.
            })
        .max(280.);
        let page = self.settings_page(content_width, cx);
        div()
            .relative()
            .flex_1()
            .min_w(px(0.))
            .h_full()
            .flex()
            .flex_col()
            .bg(wechat_theme::chat_bg())
            // 内嵌设置：焦点句柄必须挂在主轴，否则无焦点元素时 Esc 会丢。
            .track_focus(&self.settings_focus)
            .child(
                div()
                    .flex_shrink_0()
                    .px(px(14.))
                    .pt(px(14.))
                    .pb(px(14.))
                    .flex()
                    .items_center()
                    .justify_between()
                    .gap(px(8.))
                    .child(
                        div()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(15.))
                            .line_height(px(24.))
                            .font_weight(gpui::FontWeight::SEMIBOLD)
                            .text_color(wechat_theme::chat_title())
                            .child(title),
                    )
                    .children(subpage.then(|| {
                        div()
                            .id("im-subpage-back")
                            .h(px(28.))
                            .px(px(10.))
                            .rounded(px(theme::RADIUS_PILL))
                            .flex()
                            .items_center()
                            .gap(px(4.))
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, _event, window, cx| {
                                this.close_im_subpage(window, cx);
                            }))
                            .child(icons::icon(
                                icons::Icon::ChevronLeft,
                                14.,
                                wechat_theme::chat_subtitle(),
                            ))
                            .child(
                                div()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(12.))
                                    .line_height(px(18.))
                                    .text_color(wechat_theme::list_preview())
                                    .child(i18n::t("返回")),
                            )
                    }))
            )
            .child(div().h(px(1.)).bg(wechat_theme::divider()))
            .child(
                div()
                    .id("wecom-settings-scroll")
                    .flex_1()
                    .min_h(px(0.))
                    .overflow_y_scroll()
                    .scrollbar_width(px(6.))
                    // 滚动条占右侧 6px；右内边距相应减掉，视觉左右等宽。
                    .pl(px(14.))
                    .pr(px(8.))
                    .pt(px(14.))
                    .pb(px(14.))
                    .child(
                        div()
                            .w_full()
                            .child(
                                div()
                                    .relative()
                                    .with_animation(
                                        SharedString::from(format!(
                                            "wecom-settings-page-{tab}"
                                        )),
                                        gpui::Animation::new(theme::motion_base())
                                            .with_easing(theme::ease_out),
                                        |element, delta| {
                                            let delta = delta.clamp(0., 1.);
                                            element.opacity(delta).top(px(6. * (1. - delta)))
                                        },
                                    )
                                    .child(page),
                            ),
                    ),
            )
    }

    /// 会话右侧详情栏（DS bot 风格）：模型、引擎、运行状态、最近一轮用量。
    ///
    /// 与设置页的 `DetailPanel` 同一套视觉，但内容是会话实时状态而不是表单。
    fn chat_info_panel(&mut self, _window: &Window, cx: &mut Context<Self>) -> impl IntoElement {
        use crate::ui_kit as ui;

        let key = self.active_key().unwrap_or_default();
        let bot = self.selected_bot().cloned();
        let group = self.selected_group().cloned();
        let chat = self.chats.get(&key);

        let title = bot
            .as_ref()
            .map(|bot| bot.name.clone())
            .or_else(|| group.as_ref().map(|group| group.name.clone()))
            .unwrap_or_else(|| "Mode Chat".to_string());
        let engine = bot
            .as_ref()
            .and_then(|bot| self.sessions.engine_of(&bot.id))
            .unwrap_or("mode")
            .to_string();
        let engine_label = if group.is_some() {
            i18n::t("群聊 · 按成员").to_string()
        } else if engine.is_empty() || engine.eq_ignore_ascii_case("mode") {
            "Pi-Rust".to_string()
        } else {
            engine.clone()
        };
        let model = bot
            .as_ref()
            .and_then(|bot| bot.model.as_ref())
            .map(model_label)
            .unwrap_or_else(|| i18n::t("默认模型").to_string());
        let ready = chat.is_some_and(|chat| chat.ready);
        let streaming = chat.is_some_and(|chat| chat.streaming);
        let status = if streaming {
            i18n::t("运行中")
        } else if !ready {
            i18n::t("连接中")
        } else {
            i18n::t("就绪")
        };
        let session = chat
            .and_then(|chat| chat.session_id.as_deref())
            .map(display_session_id)
            .unwrap_or_else(|| i18n::t("尚未建立").to_string());
        let messages = chat.map(|chat| chat.messages.len()).unwrap_or(0);
        let queued = chat.map(|chat| chat.queued.len()).unwrap_or(0);
        let pending = chat
            .map(|chat| chat.permissions.len() + chat.questions.len() + chat.elicitations.len())
            .unwrap_or(0);
        let turn = chat
            .and_then(|chat| chat.last_turn.as_ref())
            .map(|report| {
                format!(
                    "{} · ↑{} ↓{}",
                    elapsed_label(report.duration_ms),
                    compact_tokens(report.usage.input),
                    compact_tokens(report.usage.output)
                )
            })
            .unwrap_or_else(|| "—".to_string());

        let status_tone = if streaming {
            ui::Tone::Accent
        } else if ready {
            ui::Tone::Success
        } else {
            ui::Tone::Neutral
        };

        let mut rows = vec![
            ui::stat_row(i18n::t("引擎"), engine_label).into_any_element(),
            ui::stat_row(i18n::t("模型"), model).into_any_element(),
            ui::stat_row(i18n::t("会话 ID"), session).into_any_element(),
            ui::stat_row(i18n::t("消息数"), messages.to_string()).into_any_element(),
            ui::stat_row(i18n::t("排队消息"), queued.to_string()).into_any_element(),
            ui::stat_row(i18n::t("待处理"), pending.to_string()).into_any_element(),
            ui::stat_row(i18n::t("最近一轮"), turn).into_any_element(),
        ];
        if let Some(bot) = &bot {
            rows.push(ui::stat_row(i18n::t("工作目录"), bot.directory.clone()).into_any_element());
        }
        let count = rows.len();
        let mut card = ui::card(vec![]);
        for (index, row) in rows.into_iter().enumerate() {
            card = card.child(ui::card_row(row, index + 1 == count));
        }
        // 「⋯ → 运行状态」不再渲染第二张卡（右栏这张基础卡已经涵盖它的全部内容），
        // 改为高亮这张卡：面板本来就开着时，只打开面板等于什么都没发生，
        // 那正是 O-2 要修的原始缺陷。挂 id 供 §3.5 的 grep 判据用。
        let highlighting = matches!(
            self.chat_detail.as_ref(),
            Some(SettingsDetail::RunStatus { key: target }) if target.as_str() == key.as_str()
        );
        let mut card = card.into_any_element();
        if highlighting {
            let bordered = div()
                .w_full()
                // 圆角/配色都走微信壳令牌：这一段其余配色都是 wechat_theme::，
                // 用 theme:: 会在用户自定义主题色时和周围不同步。R_CARD = 12 见规范 §4。
                .rounded(px(ui::R_CARD))
                .border_2()
                .border_color(wechat_theme::accent())
                .overflow_hidden()
                .child(card)
                .into_any_element();
            // 高亮必须能被读出来：只有一圈绿边，用户不知道自己在看什么。
            card = div()
                .id("chat-detail-run")
                .w_full()
                .flex()
                .flex_col()
                .gap(px(ui::S2))
                .child(ui::section(i18n::t("运行状态")))
                .child(bordered)
                .into_any_element();
        }

        let mut body = div()
            .w_full()
            .flex()
            .flex_col()
            .gap(px(ui::S3))
            .child(
                div()
                    .flex()
                    .items_center()
                    .gap(px(ui::S2))
                    .child(
                        div()
                            .flex_1()
                            .min_w(px(0.))
                            .truncate()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(13.))
                            .line_height(px(18.))
                            .font_weight(gpui::FontWeight::SEMIBOLD)
                            .text_color(wechat_theme::chat_title())
                            .child(SharedString::from(title)),
                    )
                    .child(ui::badge(status, status_tone))
                    // 右上角折叠：收起整列（图标与左侧展开按钮同族，只是镜像）
                    .child(
                        div()
                            .id("chat-info-collapse")
                            .size(px(22.))
                            .flex_shrink_0()
                            .rounded(px(theme::RADIUS_TAG))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, _event, window, cx| {
                                this.set_right_panel(false, window);
                                cx.notify();
                            }))
                            .child(icons::icon(
                                icons::Icon::SidebarCollapse,
                                15.,
                                wechat_theme::icon(),
                            )),
                    ),
            )
            .child(card);

        // ---- DS bot 右栏的其余分区 ----
        // 1) 待处理：审批 / 提问 / 表单
        if pending > 0 {
            let mut pending_rows = vec![
                ui::stat_row(i18n::t("审批"), chat.map(|c| c.permissions.len()).unwrap_or(0).to_string())
                    .into_any_element(),
                ui::stat_row(i18n::t("提问"), chat.map(|c| c.questions.len()).unwrap_or(0).to_string())
                    .into_any_element(),
                ui::stat_row(
                    i18n::t("表单"),
                    chat.map(|c| c.elicitations.len()).unwrap_or(0).to_string(),
                )
                .into_any_element(),
            ];
            let count = pending_rows.len();
            let mut card = ui::card(vec![]);
            for (index, row) in pending_rows.drain(..).enumerate() {
                card = card.child(ui::card_row(row, index + 1 == count));
            }
            body = body.child(ui::section(i18n::t("待处理"))).child(card);
        }

        // 2) 待办：只读自会话库
        if let Some(chat) = chat
            && !chat.todos.is_empty()
        {
            {
                let mut rows: Vec<gpui::AnyElement> = Vec::new();
                for item in chat.todos.iter().take(6) {
                    let (glyph, tone) = match item.status.as_str() {
                        "completed" => ("✓", ui::Tone::Success),
                        "in_progress" => ("●", ui::Tone::Accent),
                        _ => ("○", ui::Tone::Neutral),
                    };
                    rows.push(
                        div()
                            .w_full()
                            .px(px(ui::S3))
                            .py(px(ui::S1))
                            .flex()
                            .items_center()
                            .gap(px(ui::S1))
                            .child(ui::badge(glyph, tone))
                            .child(
                                div()
                                    .flex_1()
                                    .min_w(px(0.))
                                    .truncate()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(11.))
                                    .text_color(wechat_theme::list_preview())
                                    .child(SharedString::from(item.content.clone())),
                            )
                            .into_any_element(),
                    );
                }
                let overflow = chat.todos.len().saturating_sub(6);
                if overflow > 0 {
                    rows.push(
                        div()
                            .w_full()
                            .px(px(ui::S3))
                            .py(px(ui::S1))
                            .child(
                                div()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(ui_kit::T_LABEL))
                                    .text_color(wechat_theme::time_label())
                                    .child(SharedString::from(if i18n::is_en() {
                                        format!("{} more", overflow)
                                    } else {
                                        format!("还有 {overflow} 条")
                                    })),
                            )
                            .into_any_element(),
                    );
                }
                let count = rows.len();
                let mut card = ui::card(vec![]);
                for (index, row) in rows.into_iter().enumerate() {
                    card = card.child(ui::card_row(row, index + 1 == count));
                }
                body = body.child(ui::section(i18n::t("待办"))).child(card);
            }
        }

        // 3) 排队消息
        if let Some(chat) = chat
            && !chat.queued.is_empty()
        {
            {
                let mut rows: Vec<gpui::AnyElement> = Vec::new();
                for (index, queued_item) in chat.queued.iter().enumerate() {
                    rows.push(
                        div()
                            .w_full()
                            .px(px(ui::S3))
                            .py(px(ui::S1))
                            .flex()
                            .items_center()
                            .gap(px(ui::S1))
                            .child(
                                div()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(ui_kit::T_LABEL))
                                    .text_color(wechat_theme::time_label())
                                    .child(SharedString::from(format!("{}", index + 1))),
                            )
                            .child(
                                div()
                                    .flex_1()
                                    .min_w(px(0.))
                                    .truncate()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(11.))
                                    .text_color(wechat_theme::list_preview())
                                    .child(SharedString::from(queued_item.text.clone())),
                            )
                            .into_any_element(),
                    );
                }
                let count = rows.len();
                let mut card = ui::card(vec![]);
                for (index, row) in rows.into_iter().enumerate() {
                    card = card.child(ui::card_row(row, index + 1 == count));
                }
                body = body
                    .child(ui::section(tri!(
                        "排队中的消息 · {}", "Queued · {}", count
                    )))
                    .child(card);
            }
        }

        // 4) 运行参数：审批档位 / 工作目录
        {
            let mut rows: Vec<gpui::AnyElement> = Vec::new();
            if let Some(bot) = &bot {
                rows.push(
                    ui::stat_row(
                        i18n::t("审批档位"),
                        match bot.approval_level.as_str() {
                            "ask" => i18n::t("每次询问").to_string(),
                            "auto" => i18n::t("自动只读").to_string(),
                            "full" => i18n::t("工作区自动").to_string(),
                            other => other.to_string(),
                        },
                    )
                    .into_any_element(),
                );
            }
            if !rows.is_empty() {
                let count = rows.len();
                let mut card = ui::card(vec![]);
                for (index, row) in rows.into_iter().enumerate() {
                    card = card.child(ui::card_row(row, index + 1 == count));
                }
                body = body.child(ui::section(i18n::t("运行参数"))).child(card);
            }
        }

        // 5) 本轮改动：按文件聚合的新增/删除行（与回合尾同一份数据）
        if let Some(chat) = chat {
            let edits = turn_edit_details(&chat.messages);
            if !edits.is_empty() {
                let added: usize = edits.iter().map(|(_, added, _)| *added).sum();
                let removed: usize = edits.iter().map(|(_, _, removed)| *removed).sum();
                let mut rows: Vec<gpui::AnyElement> = Vec::new();
                for (path, added_lines, removed_lines) in edits.iter().take(8) {
                    let name = workspace_tail(path);
                    let label = tri!(
                        "{name} +{added_lines} −{removed_lines}",
                        "{name} +{added_lines} −{removed_lines}"
                    );
                    rows.push(
                        div()
                            .w_full()
                            .px(px(ui::S3))
                            .py(px(ui::S1))
                            .flex()
                            .items_center()
                            .gap(px(ui::S1))
                            .child(
                                icons::icon(icons::Icon::Folder, 13., wechat_theme::icon()),
                            )
                            .child(
                                div()
                                    .flex_1()
                                    .min_w(px(0.))
                                    .truncate()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(11.))
                                    .text_color(wechat_theme::list_preview())
                                    .child(SharedString::from(name)),
                            )
                            .child(
                                div()
                                    .flex_shrink_0()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(ui_kit::T_LABEL))
                                    .text_color(wechat_theme::time_label())
                                    .child(SharedString::from(label)),
                            )
                            .into_any_element(),
                    );
                }
                let overflow = edits.len().saturating_sub(8);
                if overflow > 0 {
                    rows.push(
                        div()
                            .w_full()
                            .px(px(ui::S3))
                            .py(px(ui::S1))
                            .child(
                                div()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(ui_kit::T_LABEL))
                                    .text_color(wechat_theme::time_label())
                                    .child(SharedString::from(if i18n::is_en() {
                                        format!("{} more files", overflow)
                                    } else {
                                        format!("还有 {overflow} 个文件")
                                    })),
                            )
                            .into_any_element(),
                    );
                }
                let count = rows.len();
                let mut card = ui::card(vec![]);
                for (index, row) in rows.into_iter().enumerate() {
                    card = card.child(ui::card_row(row, index + 1 == count));
                }
                body = body
                    .child(ui::section_action(
                        tri!("本轮改动 · {}", "This turn · {}", edits.len()),
                        ui::badge(
                            format!("+{added} / −{removed}"),
                            ui::Tone::Neutral,
                        ),
                    ))
                    .child(card);
            }
        }

        // 6) 会话用量
        if let Some(usage) = chat.and_then(|chat| chat.usage) {
            {
                let count = 4;
                let rows = [
                    ui::stat_row(i18n::t("回合"), usage.turns.to_string()).into_any_element(),
                    ui::stat_row(
                        i18n::t("总 tokens"),
                        session_db::format_tokens(usage.total_tokens),
                    )
                    .into_any_element(),
                    ui::stat_row(
                        i18n::t("输入"),
                        session_db::format_tokens(usage.input_tokens),
                    )
                    .into_any_element(),
                    ui::stat_row(
                        i18n::t("输出"),
                        session_db::format_tokens(usage.output_tokens),
                    )
                    .into_any_element(),
                ];
                let mut card = ui::card(vec![]);
                for (index, row) in rows.into_iter().enumerate() {
                    card = card.child(ui::card_row(row, index + 1 == count));
                }
                body = body.child(ui::section(i18n::t("会话用量"))).child(card);
            }
        }

        // 7) 最近会话历史（最多 3 条，可点切换）
        if let Some(bot) = &bot {
            let live = chat.and_then(|chat| chat.session_id.clone());
            let histories: Vec<String> = self
                .sessions
                .history_of(&bot.id)
                .into_iter()
                .filter(|id| live.as_deref() != Some(id.as_str()))
                .take(3)
                .collect();
            if !histories.is_empty() {
                let mut rows: Vec<gpui::AnyElement> = Vec::new();
                for session_id in histories {
                    let label = self
                        .sessions
                        .title(&session_id)
                        .map(str::to_string)
                        .unwrap_or_else(|| display_session_id(&session_id));
                    let bot_id = bot.id.clone();
                    let target = session_id.clone();
                    let rename_id = session_id.clone();
                    let rename_row = session_id.clone();
                    rows.push(
                        div()
                            .id(SharedString::from(format!(
                                "panel-history-{target}"
                            )))
                            .w_full()
                            .px(px(ui::S3))
                            .py(px(ui::S1))
                            .flex()
                            .items_center()
                            .gap(px(ui::S1))
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(move |this, _event, window, cx| {
                                this.switch_to_history_session(
                                    bot_id.clone(),
                                    target.clone(),
                                    window,
                                    cx,
                                );
                            }))
                            .child(
                                div()
                                    .flex_1()
                                    .min_w(px(0.))
                                    .truncate()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(ui::T_LABEL))
                                    .text_color(wechat_theme::list_preview())
                                    .child(SharedString::from(label)),
                            )
                            .child(
                                // D3：会话改名入口（classic 的「改名」随 sidebar 删掉了，
                                // 这里接回来；stop_propagation 必须调，否则点改名会先切会话）
                                div()
                                    .id(SharedString::from(format!("chat-info-rename-{rename_row}")))
                                    .flex_shrink_0()
                                    .px(px(ui::S2))
                                    .pointer()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(ui::T_LABEL))
                                    .text_color(wechat_theme::chat_subtitle())
                                    .hover(|style| style.text_color(wechat_theme::chat_title()))
                                    .on_click(cx.listener(move |this, _event, _window, cx| {
                                        cx.stop_propagation();
                                        let current = this
                                            .sessions
                                            .title(&rename_id)
                                            .unwrap_or_default()
                                            .to_string();
                                        this.settings_detail =
                                            Some(SettingsDetail::RenameSession {
                                                session_id: rename_id.clone(),
                                                current_title: current,
                                            });
                                        this.settings_detail_input = None;
                                        // 切到设置页后右栏整块不再渲染，清理掉运行状态卡，
                                        // 否则从设置返回时它会带着旧数据冒出来。
                                        this.chat_detail = None;
                                        this.settings_open = true;
                                        cx.notify();
                                    }))
                                    .child(i18n::t("改名")),
                            )
                            .child(icons::icon(
                                icons::Icon::ChevronRight,
                                12.,
                                wechat_theme::time_label(),
                            ))
                            .into_any_element(),
                    );
                }
                let count = rows.len();
                let mut card = ui::card(vec![]);
                for (index, row) in rows.into_iter().enumerate() {
                    card = card.child(ui::card_row(row, index + 1 == count));
                }
                body = body.child(ui::section(i18n::t("最近会话"))).child(card);
            }
        }
        // 8) Bot 记忆（验收 D-07）：默认微信风 UI 之前没有入口，只有 classic UI 的
        //    `bot_details` 里有。记忆条目数直接读索引；点行进编辑面板，与团队/群聊
        //    记忆共用 `SettingsDetail::BotMemory`，行级 id 仍是 `bot-memory-row-<file>`。
        if let Some(bot_id) = bot.as_ref().map(|bot| bot.id.clone()) {
            let entries = data::bot_memory_entries(&bot_id);
            let count = entries.len();
            let summary = if count == 0 {
                i18n::t("还没有记忆").to_string()
            } else {
                tri!("{count} 条记忆", "{count} entries")
            };
            let click_id = bot_id.clone();
            body = body.child(ui::section(i18n::t("记忆"))).child(
                ui::card(vec![]).child(ui::card_row(
                    div()
                        .id("chat-info-memory-row")
                        .w_full()
                        .px(px(ui::S3))
                        .py(px(ui::S1))
                        .flex()
                        .items_center()
                        .gap(px(ui::S1))
                        .pointer()
                        .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            this.settings_detail = Some(SettingsDetail::BotMemory {
                                bot_id: click_id.clone(),
                            });
                            this.settings_detail_input = None;
                            this.settings_detail_extra.clear();
                            this.settings_detail_error = None;
                            this.settings_open = true;
                            cx.notify();
                        }))
                        .child(
                            div()
                                .flex_1()
                                .min_w(px(0.))
                                .truncate()
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(11.))
                                .text_color(wechat_theme::list_preview())
                                .child(SharedString::from(summary)),
                        )
                        .child(
                            div()
                                .flex_shrink_0()
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(ui_kit::T_LABEL))
                                .text_color(wechat_theme::time_label())
                                .child(i18n::t("查看")),
                        )
                        .into_any_element(),
                    true,
                )),
            );
        }

        // 快捷动作：与「⋯」菜单里的常用项对齐
        if let Some(bot_id) = bot.as_ref().map(|bot| bot.id.clone()) {
            body = body.child(
                div()
                    .flex()
                    .flex_col()
                    .gap(px(ui::S1))
                    .child(
                        ui::button("info-model", i18n::t("切换模型"))
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                this.settings_detail = Some(SettingsDetail::Model {
                                    bot_id: bot_id.clone(),
                                });
                                this.settings_detail_input = None;
                                this.settings_open = true;
                                cx.notify();
                            })),
                    ),
            );
        }

        // 「⋯ → 运行状态」现在只高亮上面那张基础卡（见 card 构造处），
        // 不再渲染第二张卡：右栏基础卡已经涵盖它的全部内容，再画一张就是同一数据出现两次。

        div()
            .relative()
            .w(px(PANEL_WIDTH))
            .flex_shrink_0()
            .h_full()
            // 不再画 border_l_1：面板底色（#252526）本来就比中栏（#1e1e1f）亮一档，
            // 再叠 1px 亮线会读成「两条分割线」。底色差已经够分隔。
            .bg(wechat_theme::panel_bg())
            .px(px(12.))
            .py(px(12.))
            .child(
                div()
                    .id("chat-info-scroll")
                    .size_full()
                    .overflow_y_scroll()
                    .scrollbar_width(px(6.))
                    .child(body),
            )
    }

    /// 从右栏历史列表切到指定会话（与右栏「最近会话」点击同一条路径）。
    fn switch_to_history_session(
        &mut self,
        bot_id: String,
        session_id: String,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let key = bot_key(&bot_id);
        if let Some(chat) = self.chats.get(&key)
            && let Some(current) = chat.session_id.clone()
            && current != session_id
        {
            self.sessions.push_history(&bot_id, &current);
            self.sessions.save();
        }
        let Some(bot) = self.roster.bot_by_id(&bot_id).cloned() else {
            return;
        };
        let workspace = if bot.directory.trim().is_empty() {
            backend::fallback_workspace().to_string_lossy().into_owned()
        } else {
            bot.directory.clone()
        };
        let identity = bot.identity();
        let model = bot.model.clone();
        if let Some(chat) = self.chats.get_mut(&key) {
            chat.messages.clear();
            chat.streaming_index = None;
            chat.tool_index.clear();
            chat.member_stream.clear();
            chat.streaming = false;
            chat.permissions.clear();
            chat.questions.clear();
            chat.elicitations.clear();
            chat.session_id = None;
            chat.ready = false;
            chat.status = i18n::t("切换会话…").to_string();
        }
        self.backend.switch_session(
            key,
            workspace,
            identity,
            model,
            bot_id.clone(),
            session_id,
            self.sessions.engine_of(&bot_id).map(str::to_string),
        );
        self.scroll.scroll_to_bottom();
        cx.notify();
    }

    fn wechat_chat(&mut self, window: &Window, cx: &mut Context<Self>) -> impl IntoElement {
        let title = if let Some(bot) = self.selected_bot() {
            bot.name.clone()
        } else if let Some(group) = self.selected_group() {
            group.name.clone()
        } else {
            "Mode Chat".to_string()
        };
        let is_bot_chat = self.selected_bot().is_some();
        div()
            .flex_1()
            .min_w(px(0.))
            .h_full()
            .flex()
            .flex_col()
            .bg(wechat_theme::chat_bg())
            .child(
                div()
                    .h(px(56.))
                    .flex_shrink_0()
                    .px(px(14.))
                    .flex()
                    .items_center()
                    .justify_between()
                    .child(
                        div()
                            .min_w(px(0.))
                            .flex()
                            .items_center()
                            .gap(px(6.))
                            .child(
                                div()
                                    .truncate()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(15.))
                                    .line_height(px(22.))
                                    .font_weight(gpui::FontWeight::SEMIBOLD)
                                    .text_color(wechat_theme::chat_title())
                                    .child(SharedString::from(title)),
                            )
                            .children(is_bot_chat.then(|| {
                                div()
                                    .size(px(14.))
                                    .flex_shrink_0()
                                    .rounded(px(theme::RADIUS_TAG))
                                    .bg(wechat_theme::chip_bg())
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .child(icons::icon(
                                        icons::Icon::Bot,
                                        10.,
                                        wechat_theme::chip_text(),
                                    ))
                            })),
                    )
                    .child(
                        div()
                            .flex()
                            .items_center()
                            .gap(px(4.))
                            // 只在「收起」时显示展开按钮；展开后折叠入口移到右栏内部
                            // 右上角（见 chat_info_panel），避免同一处出现两个开合图标。
                            .when(!self.right_panel_open, |el| {
                                el.child(
                                    div()
                                        .id("wechat-panel-expand")
                                        .size(px(28.))
                                        .rounded(px(theme::RADIUS_TAG))
                                        .flex()
                                        .items_center()
                                        .justify_center()
                                        .pointer()
                                        .hover(|style| {
                                            style.bg(wechat_theme::nav_item_hover_bg())
                                        })
                                        .on_click(cx.listener(|this, _event, window, cx| {
                                            this.set_right_panel(true, window);
                                            cx.notify();
                                        }))
                                        .child(icons::icon(
                                            icons::Icon::SidebarExpand,
                                            18.,
                                            wechat_theme::icon(),
                                        )),
                                )
                            })
                            // Q-05：默认壳（微信风）原先没有「新会话」入口，只剩 Ctrl+N；
                            // 群聊没有「当前 Bot」语义，所以按 is_bot_chat 隐藏。
                            .children(is_bot_chat.then(|| {
                                div()
                                    .id("wechat-new-session")
                                    .size(px(28.))
                                    .rounded(px(theme::RADIUS_TAG))
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .pointer()
                                    .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                                    .on_click(cx.listener(|this, _event, _window, cx| {
                                        this.new_session_for_selected(cx);
                                    }))
                                    .child(icons::icon(
                                        icons::Icon::Plus,
                                        18.,
                                        wechat_theme::icon(),
                                    ))
                            }))
                            .child(
                                div()
                                    .id("wechat-more")
                                    .size(px(28.))
                                    .rounded(px(theme::RADIUS_TAG))
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .pointer()
                                    .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                                    .on_click(cx.listener(|this, _event, _window, cx| {
                                        if this.selection.is_some() {
                                            this.detail_menu_open = !this.detail_menu_open;
                                            this.menu_selected = 0;
                                        }
                                        cx.notify();
                                    }))
                                    .child(icons::icon(
                                        icons::Icon::Ellipsis,
                                        22.,
                                        wechat_theme::icon(),
                                    )),
                            ),
                    ),
            )
            .children(self.chat_find_bar(cx))
            .child(self.wechat_transcript(window, cx))
            .children(self.wechat_working_row(cx))
            .children(self.question_cards(cx))
            .children(self.elicitation_cards(cx))
            .children(self.approval_cards(cx))
            .children(self.turn_footer(cx))
            .children(self.group_task_bar(cx))
            .children(self.queue_panel(cx))
            .child(self.wechat_composer(window, cx))
    }

    fn wechat_transcript(
        &mut self,
        _window: &Window,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let key = self.active_key();
        let bot = self.selected_bot().cloned();
        let group = self.selected_group().cloned();
        let is_group = group.is_some();
        let default_author = bot
            .as_ref()
            .map(|bot| bot.name.clone())
            .or_else(|| group.as_ref().map(|group| group.name.clone()))
            .unwrap_or_else(|| "Bot".to_string());
        let member_ids: HashMap<String, String> = self
            .roster
            .bots
            .iter()
            .map(|bot| (bot.name.clone(), bot.id.clone()))
            .collect();
        let mention_names: Vec<String> = group
            .as_ref()
            .map(|group| {
                group
                    .member_ids
                    .iter()
                    .filter_map(|id| self.roster.bot_by_id(id).map(|bot| bot.name.clone()))
                    .collect()
            })
            .unwrap_or_default();
        let Some(chat) = key.as_ref().and_then(|key| self.chats.get(key)) else {
            return div()
                .flex_1()
                .min_h(px(0.))
                .flex()
                .items_center()
                .justify_center()
                .child(empty_state(
                    i18n::t("选择会话"),
                    i18n::t("从左侧列表选择 Bot 或群聊，或点右上角 + 新建。"),
                ))
                .into_any_element();
        };
        if chat.messages.is_empty() {
            if !chat.ready {
                return div()
                    .flex_1()
                    .min_h(px(0.))
                    .flex()
                    .justify_center()
                    // 与正式 transcript 行同一左右留白（14px），避免骨架贴边。
                    .px(px(14.))
                    .child(skeleton_rows())
                    .into_any_element();
            }
            return self.wechat_welcome(bot.as_ref(), group.as_ref(), cx);
        }
        let start = chat.messages.len().saturating_sub(chat.transcript_limit);
        let chat_key = key.clone().unwrap_or_default();
        let find_hit_message = self
            .chat_find
            .as_ref()
            .filter(|find| find.key == chat_key)
            .and_then(|find| find.matches.get(find.current).copied());
        let mut message_rows: HashMap<usize, usize> = HashMap::new();
        let mut rows: Vec<WecomRow> = Vec::new();
        let mut turn_rows: Vec<usize> = Vec::new();
        if start > 0 {
            rows.push(WecomRow::LoadEarlier {
                key: chat_key.clone(),
                hidden: start,
            });
        }
        let mut last_day: Option<String> = None;
        // 分组扫描跳过的下标（组内后续工具卡已随组一起进 rows）。
        let mut tool_group_skip = 0;
        for (index, message) in chat.messages.iter().enumerate().skip(start) {
            if index < tool_group_skip {
                continue;
            }
            if message.kind == MsgKind::Tool {
                let family = tool_render::family(&message.tool_name);
                let mut count = 1;
                while tool_render::groupable(family)
                    && index + count < chat.messages.len()
                {
                    let next = &chat.messages[index + count];
                    if next.kind != MsgKind::Tool
                        || tool_render::family(&next.tool_name) != family
                    {
                        break;
                    }
                    count += 1;
                }
                if count >= 2 {
                    let key = message.tool_call_id.clone();
                    let expanded = self.tool_group_expanded.contains(&key);
                    let messages = chat.messages[index..index + count]
                        .iter()
                        .map(|child| {
                            (
                                child.clone(),
                                self.tool_expanded.contains(&child.tool_call_id),
                            )
                        })
                        .collect();
                    rows.push(WecomRow::ToolGroup {
                        key,
                        family,
                        messages,
                        expanded,
                    });
                    let row = rows.len() - 1;
                    for child in index..index + count {
                        message_rows.insert(child, row);
                    }
                    tool_group_skip = index + count;
                } else {
                    rows.push(WecomRow::Tool {
                        message: Box::new(message.clone()),
                        expanded: self.tool_expanded.contains(&message.tool_call_id),
                    });
                    message_rows.insert(index, rows.len() - 1);
                }
                continue;
            }
            if message.kind == MsgKind::Reasoning {
                if !self.show_thinking || message.text.trim().is_empty() {
                    continue;
                }
                let key = format!(
                    "reason-{}-{}",
                    message.at,
                    message.member.as_deref().unwrap_or("")
                );
                rows.push(WecomRow::Reasoning {
                    expanded: self.reasoning_expanded.contains(&key),
                    key,
                    text: message.text.clone(),
                    member: message.member.clone(),
                    streaming: message.streaming,
                    duration_ms: message.duration_ms,
                });
                message_rows.insert(index, rows.len() - 1);
                continue;
            }
            if is_group && message.role == Role::User && is_group_prompt(&message.text) {
                continue;
            }
            if message.at > 0 {
                let day = time::format_day(message.at);
                if last_day.as_deref() != Some(day.as_str()) {
                    last_day = Some(day);
                    rows.push(WecomRow::Date(format!(
                        "{} {}",
                        time::day_label(message.at),
                        time::format_hm(message.at)
                    )));
                }
            }
            if message.role == Role::User {
                // 历史里偶发空 userInput（附件元数据缺失时）不渲染空气泡。
                if message.text.is_empty()
                    && message.attachments.is_empty()
                    && message.attachment_meta.is_empty()
                {
                    continue;
                }
                rows.push(WecomRow::User {
                    text: message.text.clone(),
                    attachments: message.attachments.clone(),
                    attachment_meta: message.attachment_meta.clone(),
                    find_hit: find_hit_message == Some(index),
                });
                message_rows.insert(index, rows.len() - 1);
                turn_rows.push(rows.len() - 1);
                continue;
            }
            if message.text.is_empty() && !message.streaming {
                continue;
            }
            let author = message
                .member
                .clone()
                .unwrap_or_else(|| default_author.clone());
            let author_id = message
                .member
                .as_ref()
                .and_then(|name| member_ids.get(name))
                .cloned()
                .unwrap_or_else(|| author.clone());
            rows.push(WecomRow::Assistant {
                text: message.text.clone(),
                author,
                author_id,
                find_hit: find_hit_message == Some(index),
            });
            message_rows.insert(index, rows.len() - 1);
        }
        if chat.compacting == Some(true) {
            // Q-01：压缩状态行。classic 壳挂消息列顶部，但虚拟列表的顶部是历史区
            // （滚上去才看得到），这里挂行尾——用户视线所在的位置。
            rows.push(WecomRow::Compacting);
        }
        self.wechat_message_rows = message_rows;
        let count = rows.len();
        let fingerprint = wechat_rows_fingerprint(&rows);
        let last_row_fingerprint = rows.last().map(wechat_row_fingerprint).unwrap_or(0);
        let old_count = self.wechat_row_count;
        let chat_changed = self.wechat_scroller_chat.as_deref() != Some(chat_key.as_str());
        if chat_changed {
            self.wechat_scroller.update(cx, |state, cx| {
                state.reset(count, cx);
                state.remeasure(cx);
                state.scroll_to_end(cx);
            });
            self.wechat_row_count = count;
            self.wechat_rows_fingerprint = fingerprint;
            self.wechat_last_row_fingerprint = last_row_fingerprint;
            self.wechat_scroller_chat = Some(chat_key);
            if !turn_rows.is_empty() {
                self.wechat_turn_cursor = turn_rows.len() - 1;
            }
        } else if count != old_count {
            if count > old_count && last_row_fingerprint == self.wechat_last_row_fingerprint {
                // 只是向上补了历史（加载更早）：prepend 保持滚动锚点。
                let added = count - old_count;
                self.wechat_scroller
                    .update(cx, |state, cx| state.prepend(added, cx));
            } else if count > old_count {
                // 新消息：append 会为新增行建测量项；reset 在本组件里会复用旧行元素，
                // 导致新助手行显示上一条内容。
                let added = count - old_count;
                self.wechat_scroller.update(cx, |state, cx| {
                    state.append(added, cx);
                    state.scroll_to_end(cx);
                });
            } else {
                self.wechat_scroller.update(cx, |state, cx| {
                    state.reset(count, cx);
                    state.remeasure(cx);
                });
            }
            self.wechat_row_count = count;
            self.wechat_rows_fingerprint = fingerprint;
            self.wechat_last_row_fingerprint = last_row_fingerprint;
        } else if self.wechat_rows_fingerprint != fingerprint {
            // 行数不变但内容增长（流式回复）：通知虚拟列表重测，否则行高与内容会停在旧帧。
            self.wechat_scroller
                .update(cx, |state, cx| state.remeasure(cx));
            self.wechat_rows_fingerprint = fingerprint;
            self.wechat_last_row_fingerprint = last_row_fingerprint;
        }
        if self.pending_find_scroll {
            self.pending_find_scroll = false;
            if let Some(hit) = find_hit_message
                && let Some(row) = self.wechat_message_rows.get(&hit).copied()
            {
                self.wechat_scroller
                    .update(cx, |state, cx| state.scroll_to_item(row, cx));
            }
        }
        let turn_rows = std::sync::Arc::new(turn_rows);
        let rows = std::sync::Arc::new(rows);
        let bubble_max = (560. * self.message_width as f32 / 100.).clamp(240., 560.);
        let chat_font_size = self.chat_font_size as f32;
        let flat_layout = self.message_layout == "flat";
        let render_rows = rows.clone();
        let weak = cx.weak_entity();
        let scroller = gpui::component::message_scroller::MessageScroller::new(
            "wechat-transcript",
            self.wechat_scroller.clone(),
            move |index, _window, cx| -> gpui::AnyElement {
                wechat_row_el(
                    &render_rows[index],
                    index,
                    is_group,
                    &mention_names,
                    bubble_max,
                    chat_font_size,
                    flat_layout,
                    &weak,
                    cx,
                )
            },
        )
        .scrollbar(true)
        .jump_button(false)
        .with_row_style(gpui::StyleRefinement::default().px(px(14.)).pb(px(14.)))
        .flex_1()
        .min_h(px(0.));
        let mut container = div()
            .relative()
            .flex()
            .flex_col()
            .flex_1()
            .min_h(px(0.))
            .child(scroller);
        if turn_rows.len() > 1 {
            let turns_prev = turn_rows.clone();
            let turns_next = turn_rows.clone();
            let cursor = self.wechat_turn_cursor;
            let can_prev = cursor > 0;
            let can_next = cursor + 1 < turns_prev.len();
            let mut nav = div()
                .absolute()
                .top(px(12.))
                // 中栏容器已有 14px 内边距，这里再留 6px 才不会贴住气泡。
                .right(px(6.))
                .flex()
                .flex_col()
                .gap(px(2.))
                .rounded(px(theme::RADIUS_CHIP))
                .border_1()
                .border_color(wechat_theme::composer_border())
                .bg(wechat_theme::panel_card_bg())
                .p(px(2.));
            for (label, previous, enabled) in
                [("↑", true, can_prev), ("↓", false, can_next)]
            {
                let turns = if previous {
                    turns_prev.clone()
                } else {
                    turns_next.clone()
                };
                nav = nav.child(
                    div()
                        .id(if previous {
                            "wechat-turn-prev"
                        } else {
                            "wechat-turn-next"
                        })
                        .size(px(22.))
                        .rounded(px(theme::RADIUS_TAG))
                        .flex()
                        .items_center()
                        .justify_center()
                        .pointer()
                        .when(!enabled, |el| el.opacity(0.35))
                        .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                        .on_click(cx.listener(move |this, _event, _window, cx| {
                            if previous {
                                if this.wechat_turn_cursor > 0 {
                                    this.wechat_turn_cursor -= 1;
                                }
                            } else if this.wechat_turn_cursor + 1 < turns.len() {
                                this.wechat_turn_cursor += 1;
                            }
                            if let Some(index) = turns.get(this.wechat_turn_cursor) {
                                this.wechat_scroller.update(cx, |state, cx| {
                                    state.scroll_to_item(*index, cx);
                                });
                            }
                            cx.notify();
                        }))
                        .child(
                            div()
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(12.))
                                .text_color(wechat_theme::icon())
                                .child(i18n::t(label)),
                        ),
                );
            }
            container = container.child(nav);
        }
        container.into_any_element()
    }

    /// 空会话欢迎区（O-1）：头像 + 欢迎语 + 三条建议 chip（单聊）／群欢迎区（群聊）。
    ///
    /// 交互照 classic `transcript` 的欢迎区做（点 chip 把文案填进输入框并聚焦），
    /// 但令牌全部换成 `wechat_theme` 的，chip 的 id 前缀用 `wechat-welcome-`。
    /// 群聊分支照 classic `group_placeholder` 重写：九宫格成员头像 + 「群名 · 人数」+
    /// 成员名单。它是 D-CUT 删掉 `group_placeholder` 后的补齐，不是新增功能。
    fn wechat_welcome(
        &mut self,
        bot: Option<&Bot>,
        group: Option<&Group>,
        cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        if let Some(group) = group {
            return self.wechat_group_welcome(group, cx);
        }
        let Some(bot) = bot else {
            return div().flex_1().min_h(px(0.)).into_any_element();
        };
        let input = self.input.clone();
        let suggestions = [
            i18n::t("先做一次发布前走查"),
            i18n::t("把这次需求拆成可执行任务"),
            i18n::t("总结一下最近的进展"),
        ];
        let mut chips = div().flex().flex_wrap().items_center().gap(px(ui_kit::S2));
        for (index, text) in suggestions.into_iter().enumerate() {
            let seed = text.to_string();
            let filled = seed.clone();
            chips = chips.child(
                div()
                    .id(SharedString::from(format!("wechat-welcome-suggestion-{index}")))
                    .h(px(28.))
                    .rounded(px(theme::RADIUS_TAG))
                    .border_1()
                    .border_color(wechat_theme::composer_border())
                    .px(px(ui_kit::S3))
                    .flex()
                    .items_center()
                    .pointer()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_BODY))
                    .line_height(px(ui_kit::T_BODY_LH))
                    .text_color(wechat_theme::chat_subtitle())
                    .hover(|style| {
                        style
                            .bg(wechat_theme::nav_item_hover_bg())
                            .text_color(wechat_theme::chat_title())
                    })
                    .on_click(cx.listener({
                        let input = input.clone();
                        move |_this, _event, window, cx| {
                            input.update(cx, |input, cx| input.set_content(filled.clone(), cx));
                            let handle = input.read(cx).focus_handle(cx);
                            handle.focus(window, cx);
                            cx.notify();
                        }
                    }))
                    .child(SharedString::from(seed)),
            );
        }

        div()
            .flex_1()
            .min_h(px(0.))
            .flex()
            .flex_col()
            .items_center()
            .justify_center()
            .gap(px(ui_kit::S4))
            .px(px(ui_kit::S6))
            .child(Self::wechat_avatar(&bot.id, &bot.name, 56.))
            .child(
                div()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_PAGE))
                    .line_height(px(ui_kit::T_PAGE_LH))
                    .font_weight(gpui::FontWeight::SEMIBOLD)
                    .text_color(wechat_theme::chat_title())
                    .child(SharedString::from(bot.name.clone())),
            )
            .children((!bot.role.trim().is_empty()).then(|| {
                div()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_LABEL))
                    .line_height(px(ui_kit::T_LABEL_LH))
                    .text_color(wechat_theme::chat_subtitle())
                    .child(SharedString::from(bot.role.clone()))
            }))
            .child(
                div()
                    .max_w(px(460.))
                    .mt(px(ui_kit::S1))
                    .rounded(px(theme::RADIUS_CHIP))
                    .bg(wechat_theme::bubble_in())
                    .px(px(14.))
                    .py(px(10.))
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_TITLE))
                    .line_height(px(ui_kit::T_TITLE_LH + 6.))
                    .text_color(wechat_theme::bubble_text())
                    .child(SharedString::from(tri!(
                        "你好，我是{}。直接把活儿派给我，或去群聊里和大家一起推进。",
                        "Hi, I am {}. Give me work directly, or head to a group chat and we will push it together.",
                        bot.name
                    ))),
            )
            .child(
                div()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_LABEL))
                    .line_height(px(ui_kit::T_LABEL_LH))
                    .text_color(wechat_theme::chat_subtitle())
                    .child(i18n::t("今天想先推进哪件事？")),
            )
            .child(chips)
            .into_any_element()
    }

    /// 群聊空会话欢迎区：九宫格成员头像 + 「群名 · 人数」+ 成员名单。
    ///
    /// classic 的 `group_placeholder` 随 D-CUT 一起删掉了，微信壳在群聊 + 0 条消息时
    /// 只剩裸 `div()`。这里按原函数重写，头像换 `wechat_group_avatar`（微信壳自己那套），
    /// 不再用已被删除的 `avatar::channel_avatar`。
    fn wechat_group_welcome(
        &mut self,
        group: &Group,
        _cx: &mut Context<Self>,
    ) -> gpui::AnyElement {
        let visible = visible_group_members(group, &self.roster);
        let members = if visible.is_empty() {
            group
                .member_ids
                .iter()
                .map(|id| short_id(id))
                .collect::<Vec<_>>()
                .join("、")
        } else {
            visible
                .iter()
                .map(|bot| bot.name.clone())
                .collect::<Vec<_>>()
                .join("、")
        };
        let ids: Vec<String> = group.member_ids.clone();
        div()
            .id("wechat-group-welcome")
            .flex_1()
            .min_h(px(0.))
            .flex()
            .flex_col()
            .items_center()
            .justify_center()
            .gap(px(ui_kit::S4))
            .px(px(ui_kit::S6))
            .child(if ids.is_empty() {
                // 群聊还没加成员：画不出九宫格，退回首字色块。
                Self::wechat_channel_avatar(&group.id, 56.).into_any_element()
            } else {
                Self::wechat_group_avatar(&ids, 56.).into_any_element()
            })
            .child(
                div()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_PAGE))
                    .line_height(px(ui_kit::T_PAGE_LH))
                    .font_weight(gpui::FontWeight::SEMIBOLD)
                    .text_color(wechat_theme::chat_title())
                    .child(SharedString::from(format!(
                        "{} · {}",
                        group.name,
                        count_members(visible.len())
                    ))),
            )
            .child(
                div()
                    .max_w(px(460.))
                    .text_center()
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_BODY))
                    .line_height(px(ui_kit::T_BODY_LH + 4.))
                    .text_color(wechat_theme::chat_subtitle())
                    .child(SharedString::from(tri!(
                        "成员：{members}。发消息开始群聊对话；用 @成员名 点名。",
                        "Members: {members}. Send a message to start the group chat; @mention someone to call on them."
                    ))),
            )
            .into_any_element()
    }

    /// 转录底部的「工作中 N 秒」行（streaming 时显示，1s ticker 刷新）。
    fn wechat_working_row(&mut self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let key = self.active_key()?;
        let (started, waiting, retry, has_output) = {
            let chat = self.chats.get(&key)?;
            let turn_start = chat
                .messages
                .iter()
                .rposition(|message| message.role == Role::User)
                .map(|index| index + 1)
                .unwrap_or(0);
            let has_output = chat
                .messages
                .get(turn_start..)
                .is_some_and(|messages| {
                    messages.iter().any(|message| {
                        message.kind == MsgKind::Tool || !message.text.trim().is_empty()
                    })
                });
            (
                chat.turn_started,
                !chat.permissions.is_empty()
                    || !chat.questions.is_empty()
                    || !chat.elicitations.is_empty(),
                chat.retry
                    .as_ref()
                    .map(|retry| (retry.attempt, retry.max_retries, retry.reason.clone())),
                has_output,
            )
        };
        if waiting {
            return None;
        }
        let started = started?;
        // 首字前的空窗：三点「正在输入」气泡，出字/出工具后让位给工作中行。
        if !has_output && retry.is_none() {
            return Some(typing_bubble());
        }
        self.ensure_working_ticker(cx);
        let elapsed = time::now_ms().saturating_sub(started);
        let spinner = gpui::svg()
            .data(include_bytes!("../assets/icons/spinner.svg"))
            .size(px(14.))
            .text_color(wechat_theme::time_label())
            .with_animation(
                "wecom-working-spin",
                gpui::Animation::new(Duration::from_millis(1200)).repeat(),
                |svg, delta| {
                    svg.with_transformation(gpui::Transformation::rotate(gpui::radians(
                        delta * std::f32::consts::TAU,
                    )))
                },
            );
        Some(
            div()
                .w_full()
                .px(px(14.))
                .pb(px(4.))
                .flex()
                .items_center()
                .gap(px(6.))
                .child(spinner)
                .child(
                    div()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(12.))
                        .line_height(px(18.))
                        .text_color(if retry.is_some() {
                            theme::warning()
                        } else {
                            wechat_theme::chat_title()
                        })
                        .child(if retry.is_some() {
                            i18n::t("重试中")
                        } else {
                            i18n::t("工作中")
                        }),
                )
                .children(retry.as_ref().map(|(attempt, max_retries, _)| {
                    div()
                        .flex_shrink_0()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(11.))
                        .text_color(theme::warning())
                        .child(SharedString::from(format!("{attempt}/{max_retries}")))
                }))
                .children(retry.as_ref().map(|(_, _, reason)| {
                    div()
                        .flex_1()
                        .min_w(px(0.))
                        .truncate()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(11.))
                        .text_color(wechat_theme::time_label())
                        .child(SharedString::from(tool_render::single_line(reason, 80)))
                }))
                .child(
                    div()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(11.))
                        .text_color(wechat_theme::time_label())
                        .child(SharedString::from(elapsed_label(elapsed))),
                )
                .into_any_element(),
        )
    }

    /// 回合尾统计：一行 10px 小字（用时 + token），不打断正文阅读。
    fn turn_footer(&mut self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let key = self.active_key()?;
        let (details, open, report) = {
            let chat = self.chats.get(&key)?;
            if chat.streaming
                || !chat.permissions.is_empty()
                || !chat.questions.is_empty()
                || !chat.elicitations.is_empty()
            {
                return None;
            }
            let report = chat.last_turn.as_ref()?;
            (
                turn_edit_details(&chat.messages),
                chat.edit_summary_open,
                (report.usage, report.duration_ms),
            )
        };
        let (usage, duration_ms) = report;
        let mut stats: Vec<String> = Vec::new();
        if duration_ms >= 1000 {
            stats.push(if i18n::is_en() {
                format!("{} elapsed", elapsed_label(duration_ms))
            } else {
                format!("用时 {}", elapsed_label(duration_ms))
            });
        }
        if usage.input > 0 || usage.output > 0 {
            stats.push(format!(
                "↑{} ↓{}",
                compact_tokens(usage.input),
                compact_tokens(usage.output)
            ));
        }
        if usage.cache_read > 0 {
            stats.push(if i18n::is_en() {
                format!("cache {}", compact_tokens(usage.cache_read))
            } else {
                format!("缓存 {}", compact_tokens(usage.cache_read))
            });
        }
        if details.is_empty() && stats.is_empty() {
            return None;
        }
        let mut column = div().w_full().px(px(14.)).pb(px(2.)).flex().flex_col().gap(px(2.));
        if !details.is_empty() {
            let files = details.len();
            let added: usize = details.iter().map(|(_, added, _)| *added).sum();
            let removed: usize = details.iter().map(|(_, _, removed)| *removed).sum();
            let mut card = div()
                .w_full()
                .rounded(px(theme::RADIUS_FIELD))
                .border_1()
                .border_color(wechat_theme::composer_border())
                .bg(wechat_theme::panel_card_bg())
                .overflow_hidden()
                .child(
                    div()
                        .id("turn-files-toggle")
                        .h(px(26.))
                        .px(px(8.))
                        .flex()
                        .items_center()
                        .gap(px(5.))
                        .pointer()
                        .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                        .on_click(cx.listener(|this, _event, _window, cx| {
                            if let Some(key) = this.active_key()
                                && let Some(chat) = this.chats.get_mut(&key)
                            {
                                chat.edit_summary_open = !chat.edit_summary_open;
                            }
                            cx.notify();
                        }))
                        .child(icons::icon(
                            icons::Icon::Pencil,
                            12.,
                            wechat_theme::time_label(),
                        ))
                        .child(
                            div()
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(11.))
                                .line_height(px(16.))
                                .text_color(wechat_theme::list_preview())
                                .child(SharedString::from(if i18n::is_en() {
                                    format!("This turn changed {files} files")
                                } else {
                                    format!("本轮改动 {files} 个文件")
                                })),
                        )
                        .child(div().flex_1())
                        .child(diff_count_el(added, removed))
                        .child(icons::icon(
                            if open {
                                icons::Icon::ChevronLeft
                            } else {
                                icons::Icon::ChevronRight
                            },
                            12.,
                            wechat_theme::icon(),
                        )),
                );
            if open {
                let mut rows = div().w_full().flex().flex_col().pb(px(2.));
                for (path, added, removed) in &details {
                    rows = rows.child(
                        div()
                            .h(px(20.))
                            .px(px(8.))
                            .flex()
                            .items_center()
                            .gap(px(6.))
                            .child(
                                div()
                                    .flex_1()
                                    .min_w(px(0.))
                                    .truncate()
                                    .font_family(theme::FONT_MONO)
                                    .text_size(px(ui_kit::T_LABEL))
                                    .text_color(wechat_theme::list_preview())
                                    .child(SharedString::from(path.clone())),
                            )
                            .children((*added > 0).then(|| {
                                div()
                                    .flex_shrink_0()
                                    .font_family(theme::FONT_MONO)
                                    .text_size(px(ui_kit::T_LABEL))
                                    .text_color(theme::success())
                                    .child(SharedString::from(format!("+{added}")))
                            }))
                            .children((*removed > 0).then(|| {
                                div()
                                    .flex_shrink_0()
                                    .font_family(theme::FONT_MONO)
                                    .text_size(px(ui_kit::T_LABEL))
                                    .text_color(theme::danger())
                                    .child(SharedString::from(format!("-{removed}")))
                            })),
                    );
                }
                card = card.child(rows);
            }
            column = column.child(card);
        }
        if !stats.is_empty() {
            column = column.child(
                div().w_full().flex().justify_end().child(
                    div()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(ui_kit::T_LABEL))
                        .line_height(px(14.))
                        .text_color(wechat_theme::time_label())
                        .child(SharedString::from(stats.join(" · "))),
                ),
            );
        }
        Some(column.into_any_element())
    }

    /// 会话内查找条：输入即搜，↑/↓ 跳命中，Esc/× 关闭。
    fn chat_find_bar(&self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let find = self.chat_find.as_ref()?;
        if self.active_key().as_deref() != Some(find.key.as_str()) {
            return None;
        }
        let count = if find.matches.is_empty() {
            i18n::t("无结果").to_string()
        } else {
            format!("{}/{}", find.current + 1, find.matches.len())
        };
        let input = find.input.clone();
        let nav_button = |id: &'static str,
                          label: &'static str,
                          previous: bool,
                          cx: &mut Context<Self>| {
            div()
                .id(id)
                .size(px(22.))
                .rounded(px(theme::RADIUS_TAG))
                .flex()
                .items_center()
                .justify_center()
                .pointer()
                .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                .on_click(cx.listener(move |this, _event, _window, cx| {
                    this.chat_find_step(if previous { -1 } else { 1 }, cx);
                }))
                .child(
                    div()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(12.))
                        .text_color(wechat_theme::icon())
                        .child(label),
                )
        };
        Some(
            div()
                .mx(px(14.))
                .mb(px(4.))
                .h(px(32.))
                .flex_shrink_0()
                .rounded(px(theme::RADIUS_FIELD))
                .border_1()
                .border_color(wechat_theme::composer_border())
                .bg(wechat_theme::panel_card_bg())
                .px(px(8.))
                .flex()
                .items_center()
                .gap(px(6.))
                .child(icons::icon(
                    icons::Icon::Search,
                    13.,
                    wechat_theme::time_label(),
                ))
                .child(
                    div()
                        .flex_1()
                        .min_w(px(0.))
                        .h(px(24.))
                        .child(input),
                )
                .child(
                    div()
                        .flex_shrink_0()
                        .font_family(wechat_theme::FONT_FAMILY)
                        .text_size(px(ui_kit::T_LABEL))
                        .text_color(wechat_theme::time_label())
                        .child(SharedString::from(count)),
                )
                .child(nav_button("chat-find-prev", "↑", true, cx))
                .child(nav_button("chat-find-next", "↓", false, cx))
                .child(
                    div()
                        .id("chat-find-close")
                        .size(px(22.))
                        .rounded(px(theme::RADIUS_TAG))
                        .flex()
                        .items_center()
                        .justify_center()
                        .pointer()
                        .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                        .on_click(cx.listener(|this, _event, _window, cx| {
                            this.chat_find = None;
                            this.pending_find_scroll = false;
                            cx.notify();
                        }))
                        .child(icons::icon(icons::Icon::X, 12., wechat_theme::time_label())),
                )
                .into_any_element(),
        )
    }

    /// 排队消息条：回合进行中继续发送的消息，结束前可逐条移除。
    fn queue_panel(&self, cx: &mut Context<Self>) -> Option<gpui::AnyElement> {
        let key = self.active_key()?;
        let chat = self.chats.get(&key)?;
        if chat.queued.is_empty() {
            return None;
        }
        let mut rows = div().w_full().flex().flex_col().pb(px(2.));
        for (index, item) in chat.queued.iter().enumerate() {
            let preview = tool_render::single_line(&item.text, 60);
            let attachment_count = item.attachments.len();
            let remove_key = key.clone();
            rows = rows.child(
                div()
                    .w_full()
                    .h(px(24.))
                    .px(px(8.))
                    .flex()
                    .items_center()
                    .gap(px(6.))
                    .child(
                        div()
                            .flex_shrink_0()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(ui_kit::T_LABEL))
                            .text_color(wechat_theme::time_label())
                            .child(SharedString::from(format!("{}.", index + 1))),
                    )
                    .child(
                        div()
                            .flex_1()
                            .min_w(px(0.))
                            .truncate()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(12.))
                            .line_height(px(16.))
                            .text_color(wechat_theme::list_preview())
                            .child(SharedString::from(preview)),
                    )
                    .children((attachment_count > 0).then(|| {
                        div()
                            .flex_shrink_0()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(ui_kit::T_LABEL))
                            .text_color(wechat_theme::time_label())
                            .child(SharedString::from(if i18n::is_en() {
                                format!("+{attachment_count} files")
                            } else {
                                format!("+{attachment_count} 附件")
                            }))
                    }))
                    .child(
                        div()
                            .id(SharedString::from(format!("queue-remove-{index}")))
                            .size(px(18.))
                            .rounded(px(theme::RADIUS_TAG))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(move |this, _event, _window, cx| {
                                if let Some(chat) = this.chats.get_mut(&remove_key)
                                    && index < chat.queued.len()
                                {
                                    chat.queued.remove(index);
                                }
                                cx.notify();
                            }))
                            .child(icons::icon(icons::Icon::X, 11., wechat_theme::time_label())),
                    ),
            );
        }
        Some(
            div()
                .mx(px(14.))
                .mb(px(4.))
                .rounded(px(theme::RADIUS_FIELD))
                .border_1()
                .border_color(wechat_theme::composer_border())
                .bg(wechat_theme::panel_card_bg())
                .overflow_hidden()
                .child(
                    div()
                        .h(px(24.))
                        .px(px(8.))
                        .flex()
                        .items_center()
                        .gap(px(5.))
                        .child(icons::icon(
                            icons::Icon::ListChecks,
                            12.,
                            wechat_theme::time_label(),
                        ))
                        .child(
                            div()
                                .font_family(wechat_theme::FONT_FAMILY)
                                .text_size(px(11.))
                                .text_color(wechat_theme::time_label())
                                .child(SharedString::from(if i18n::is_en() {
                                    if key.starts_with("group:") {
                                        format!(
                                            "{} queued · sends after all members finish",
                                            chat.queued.len()
                                        )
                                    } else {
                                        format!(
                                            "{} queued · sends after this turn",
                                            chat.queued.len()
                                        )
                                    }
                                } else if key.starts_with("group:") {
                                    format!(
                                        "排队中 {} 条 · 所有成员回合结束后自动发送",
                                        chat.queued.len()
                                    )
                                } else {
                                    format!(
                                        "排队中 {} 条 · 回复结束后自动发送",
                                        chat.queued.len()
                                    )
                                })),
                        ),
                )
                .child(rows)
                .into_any_element(),
        )
    }

    fn wechat_composer(
        &mut self,
        window: &Window,
        cx: &mut Context<Self>,
    ) -> impl IntoElement {
        let chat = self.active_key().and_then(|key| self.chats.get(&key));
        let ready = chat.is_some_and(|chat| chat.ready);
        let streaming = chat.is_some_and(|chat| chat.streaming);
        let pending_approval = chat
            .is_some_and(|chat| !chat.permissions.is_empty() || !chat.questions.is_empty());
        let has_attachments = chat.is_some_and(|chat| !chat.pending_attachments.is_empty());
        let permission = self.selected_bot().map(|bot| bot.approval_level.clone());
        let is_bot = self.selected_bot().is_some();
        let is_group = self.selected_group().is_some();
        let has_text = !self.input.read(cx).content().trim().is_empty();
        // 命令面板入口的焦点句柄：与 classic 共用同一个 tab stop 键（两套壳互斥，
        // 不会同时存在），这样 Tab 顺序表不用为默认壳再登记一份。
        let plus_focus = self.tab_focus["composer-plus"].clone();
        let plus_focused = plus_focus.is_focused(window);
        // 只有内嵌引擎支持 lane steering；外部 ACP 引擎没有插话通道。
        let can_interject = streaming && has_text && self.current_engine_is_mode();
        let send_enabled = (is_bot || is_group)
            && ready
            && !streaming
            && !pending_approval
            && (has_text || has_attachments);
        let send_bg = if streaming {
            wechat_theme::nav_badge_bg()
        } else if send_enabled {
            wechat_theme::send_enabled()
        } else {
            wechat_theme::send_disabled_bg()
        };
        let send_fg = if streaming || send_enabled {
            wechat_theme::nav_text_active()
        } else {
            wechat_theme::send_disabled_text()
        };
        div()
            .ml(px(14.))
            .mr(px(14.))
            .mb(px(14.))
            .min_h(px(wechat_theme::COMPOSER_HEIGHT))
            .flex_shrink_0()
            .rounded(px(theme::RADIUS_FIELD))
            .border_1()
            .border_color(wechat_theme::composer_border())
            .bg(wechat_theme::composer_bg())
            .on_drop::<gpui::ExternalPaths>(cx.listener(
                |this, paths: &gpui::ExternalPaths, _window, cx| {
                    let files: Vec<String> = paths
                        .paths()
                        .iter()
                        .map(|path| path.to_string_lossy().into_owned())
                        .collect();
                    this.stage_attachment_paths(files, cx);
                },
            ))
            .flex()
            .flex_col()
            .children(self.mention_panel(cx))
            .children(self.attachment_chips(cx))
            .children(self.error_bar(cx))
            .child(
                div()
                    .id("composer-input")
                    .key_context("Composer")
                    .flex_1()
                    .min_h(px(0.))
                    .min_w(px(0.))
                    .overflow_hidden()
                    // 输入文字视觉左/上边距约 12：外壳 8 + 编辑器内部 4。
                    .px(px(8.))
                    .pt(px(8.))
                    .font_family(wechat_theme::FONT_FAMILY)
                    .text_size(px(ui_kit::T_PAGE))
                    .line_height(px(22.))
                    .text_color(wechat_theme::bubble_text())
                    .child(self.input.clone()),
            )
            .child(
                div()
                    // 28 图标按钮上下各 12；发送 26 高，上下各 13。
                    .h(px(52.))
                    .flex_shrink_0()
                    .px(px(8.))
                    .flex()
                    .items_center()
                    .gap(px(8.))
                    // Q-02：命令面板入口。classic 壳在胶囊左侧有「+」，默认壳之前
                    // 只有 Ctrl+P 一条路——而 GPUI 收不到注入的组合键，等于没有入口。
                    .child(
                        div()
                            .id("composer-plus")
                            // 与 classic 的同类按钮一致：可 Tab 聚焦、Enter 触发，
                            // 不只靠鼠标（否则键盘可达性只修了一半）。
                            .track_focus(&plus_focus)
                            .key_context("TabStop")
                            .when(plus_focused, |el| el.bg(wechat_theme::nav_item_hover_bg()))
                            .on_action(cx.listener(|this, _: &ActivateTabStop, window, cx| {
                                this.on_palette_shortcut(&PaletteShortcut, window, cx);
                            }))
                            .size(px(28.))
                            .rounded(px(theme::RADIUS_TAG))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, _event, window, cx| {
                                // 与 Ctrl+P 同一条路径：开命令面板。
                                this.on_palette_shortcut(&PaletteShortcut, window, cx);
                            }))
                            .child(icons::icon_light(icons::Icon::Plus, 18., wechat_theme::icon())),
                    )
                    .children(permission.map(|level| {
                        let color = if level == "ask" {
                            wechat_theme::icon()
                        } else {
                            wechat_theme::send_enabled()
                        };
                        div()
                            .id("wechat-tool-permission")
                            .size(px(28.))
                            .rounded(px(theme::RADIUS_TAG))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, event: &gpui::ClickEvent, _window, cx| {
                                if let gpui::ClickEvent::Mouse(mouse) = event {
                                    // 菜单向上展开：把偏移算进锚点，避免 anchored offset
                                    // 只移动视觉、不移动命中框。
                                    this.permission_menu = Some(gpui::point(
                                        mouse.up.position.x,
                                        mouse.up.position.y - px(190.),
                                    ));
                                }
                                cx.notify();
                            }))
                            .child(icons::icon_light(
                                icons::Icon::Shield,
                                18.,
                                color,
                                ))
                    }))
                    .children(can_interject.then(|| {
                        div()
                            .id("wechat-interject")
                            .h(px(26.))
                            .px(px(8.))
                            .flex_shrink_0()
                            .rounded(px(theme::RADIUS_TAG))
                            .border_1()
                            .border_color(wechat_theme::composer_border())
                            .bg(wechat_theme::panel_card_bg())
                            .flex()
                            .items_center()
                            .gap(px(4.))
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, _event, window, cx| {
                                this.interject_current(window, cx);
                            }))
                            .child(icons::icon_light(
                                icons::Icon::MessageSquare,
                                14.,
                                wechat_theme::icon(),
                                ))
                            .child(
                                div()
                                    .font_family(wechat_theme::FONT_FAMILY)
                                    .text_size(px(11.))
                                    .text_color(wechat_theme::icon())
                                    .child(i18n::t("插话")),
                            )
                    }))
                    .children((streaming && has_text).then(|| {
                        div()
                            .flex_shrink_0()
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(ui_kit::T_LABEL))
                            .text_color(wechat_theme::time_label())
                            .child(i18n::t("Enter 排队"))
                    }))
                    .child(
                        div()
                            .id("wechat-tool-folder")
                            .size(px(28.))
                            .rounded(px(theme::RADIUS_TAG))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, _event, _window, cx| {
                                this.stage_attachments(cx);
                            }))
                            .child(icons::icon_light(icons::Icon::Folder, 18., wechat_theme::icon())),
                    )
                    .child(
                        div()
                            .id("wechat-tool-scissors")
                            .size(px(28.))
                            .rounded(px(theme::RADIUS_TAG))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, _event, _window, cx| {
                                this.start_screenshot_capture(cx);
                            }))
                            .child(icons::icon_light(icons::Icon::Scissors, 18., wechat_theme::icon())),
                    )
                    .child(
                        div()
                            .id("wechat-tool-mic")
                            .size(px(28.))
                            .rounded(px(theme::RADIUS_TAG))
                            .flex()
                            .items_center()
                            .justify_center()
                            .pointer()
                            .hover(|style| style.bg(wechat_theme::nav_item_hover_bg()))
                            .on_click(cx.listener(|this, _event, window, cx| {
                                this.toggle_voice_typing(window, cx);
                            }))
                            .child(icons::icon_light(
                                icons::Icon::Mic,
                                18.,
                                if self.voice_active { ui_accent() } else { wechat_theme::icon() },
                                )),
                    )
                    .child(div().flex_1())
                    .child(
                        div()
                            .id("wechat-send")
                            // 右缘与文字 12 视觉边距对齐（工具条 8 + 4）。
                            .mr(px(4.))
                            .h(px(26.))
                            .px(px(14.))
                            .rounded(px(theme::RADIUS_TAG))
                            .bg(send_bg)
                            .flex()
                            .items_center()
                            .pointer()
                            .hover(|style| style.bg(theme::hover()))
                            .font_family(wechat_theme::FONT_FAMILY)
                            .text_size(px(13.))
                            .line_height(px(18.))
                            .font_weight(gpui::FontWeight::MEDIUM)
                            .text_color(send_fg)
                            .on_click(cx.listener(|this, _event, window, cx| {
                                if this.active_key().is_some_and(|key| {
                                    this.chats
                                        .get(&key)
                                        .is_some_and(|chat| chat.streaming)
                                }) {
                                    this.stop_streaming(cx);
                                    return;
                                }
                                this.send_current(window, cx);
                            }))
                            .child(if streaming { i18n::t("停止") } else { i18n::t("发送") }),
                    ),
            )
    }
}

impl Render for PilotApp {
    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let render_started = std::time::Instant::now();
        // gpui 只把按键派发给「有焦点的元素」的派发路径：窗口起来时若没有任何元素持有
        // 焦点，字符输入与全局 action（Ctrl+N/K/,）都会静默丢失。首帧把焦点交给输入框，
        // 之后焦点归用户（点击输入框/搜索框各自接管）。
        if self.pending_find {
            self.pending_find = false;
            self.on_find_shortcut(&FindShortcut, window, cx);
        }
        // 每帧把窗口几何记进内存槽（后台线程负责落盘）。首帧先做一次恢复校准：
        // gpui 的 border offset 换算在 DWM 下不对称，实测「请求 - 实际」后才能固定位置。
        if let Some(geometry) = current_geometry(window) {
            window_state::calibrate_if_pending((geometry.x, geometry.y));
            window_state::remember(geometry);
        }
        // 设置页详情面板开合 -> 窗口宽度联动（与会话侧栏同一套规则）。
        //
        // 放在 render 顶部而不是各个入口：设置面板有 60+ 处赋值点（选模型、
        // 改密钥、群目标……），逐处改既易漏也易错；这里按「上一帧是否显示」
        // 比较一次即可捕获所有开合。
        {
            let shown = self.settings_open && self.settings_detail.is_some();
            if shown != self.settings_panel_shown {
                self.settings_panel_shown = shown;
                let current = f32::from(window.bounds().size.width);
                let target = if shown {
                    let target = panel_target_width(current, true, None, ui_kit::PANEL_W);
                    self.settings_panel_restore = target.map(|_| current);
                    target
                } else {
                    let target = panel_target_width(
                        current,
                        false,
                        self.settings_panel_restore,
                        ui_kit::PANEL_W,
                    );
                    self.settings_panel_restore = None;
                    target
                };
                // 改窗口尺寸要放在本帧渲染之后：render 里直接 resize 会让
                // 布局在渲染中途失效。
                if target.is_some() {
                    window.defer(cx, move |window, _cx| {
                        apply_panel_width(window, target);
                    });
                }
            }
        }
        if !self.first_frame_logged {
            self.first_frame_logged = true;
            // 窗口已存在：补 DWM 阴影与任务栏图标（幂等，只在首帧跑一次）。
            window_style::apply();
            if self.topmost {
                window_style::set_topmost(true);
            }
            // 最大化/还原由系统处理，图标与几何靠窗口尺寸观察者同步。
            self.bounds_observer = Some(cx.observe_window_bounds(window, |_this, window, cx| {
                if let Some(geometry) = current_geometry(window) {
                    window_state::remember(geometry);
                }
                cx.notify();
            }));
            // 托盘：首次启动装一次（失败不影响主窗口）。
            #[cfg(windows)]
            {
                tray::install();
            }
            if std::env::var("BOT_PILOT_DEBUG").ok().as_deref() == Some("1")
                && let Some(boot) = BOOT_AT.get()
            {
                eprintln!("[boot] first frame in {} ms", boot.elapsed().as_millis());
            }
        }
        if !self.focus_bootstrapped && window.focused(cx).is_none() {
            self.focus_bootstrapped = true;
            let handle = self.input.read(cx).focus_handle(cx);
            window.defer(cx, move |window, cx| {
                handle.focus(window, cx);
            });
        }
        let pending_notifications = std::mem::take(&mut self.pending_notifications);
        for message in pending_notifications {
            window.push_notification(
                gpui::component::notification::Notification::new()
                    .message(message)
                    .placement(gpui::Anchor::BottomCenter)
                    .w(px(320.))
                    .rounded(px(theme::RADIUS_FIELD))
                    .border_1()
                    .border_color(wechat_theme::composer_border())
                    .bg(wechat_theme::panel_card_bg())
                    .px(px(16.))
                    .py(px(10.))
                    .text_color(wechat_theme::chat_title()),
                cx,
            );
        }
        let mut root = div();
        root.text_style().font_fallbacks = Some(theme::font_fallbacks());
        let root = root
            .id("pilot-root")
            .relative()
            .size_full()
            .flex()
            .flex_col()
            .bg(theme::bg())
            .font_family(theme::FONT_FAMILY)
            .text_color(theme::ink())
            .on_action(cx.listener(Self::on_send))
            .on_action(cx.listener(Self::on_send_secondary))
            .on_action(cx.listener(Self::on_close_overlay))
            .on_action(cx.listener(Self::on_new_session_shortcut))
            .on_action(cx.listener(Self::on_search_shortcut))
            .on_action(cx.listener(Self::on_settings_shortcut))
            .on_action(cx.listener(Self::on_select_next))
            .on_action(cx.listener(Self::on_select_prev))
            .on_action(cx.listener(Self::on_approve_allow))
            .on_action(cx.listener(Self::on_approve_deny))
            .on_action(cx.listener(Self::on_new_bot_shortcut))
            .on_action(cx.listener(Self::on_edit_bot_shortcut))
            .on_action(cx.listener(Self::on_new_channel_shortcut))
            .on_action(cx.listener(Self::on_submit_dialog))
            .on_action(cx.listener(Self::on_find_shortcut))
            .on_action(cx.listener(Self::on_palette_shortcut))
            .on_action(cx.listener(Self::on_palette_prev))
            .on_action(cx.listener(Self::on_palette_next))
            .on_action(cx.listener(Self::on_palette_submit))
            .on_action(cx.listener(Self::on_find_prev))
            .on_action(cx.listener(Self::on_find_next))
            .on_action(cx.listener(Self::on_find_open))
            .on_action(cx.listener(Self::on_mention_next))
            .on_action(cx.listener(Self::on_mention_prev))
            .on_action(cx.listener(Self::on_focus_next))
            .on_action(cx.listener(Self::on_focus_prev))
            .child(self.wechat_shell(window, cx))
            .children(self.side_panel(window, cx))
            .children(self.image_preview_overlay(cx))
            .children(self.settings_dropdown_overlay(cx))
            .children(self.permission_menu_overlay(cx))
            .children(self.footer_menu_overlay(cx))
            .children(self.new_menu_overlay(cx))
            .children(None::<gpui::AnyElement>)
            .children(self.find_dialog_overlay(window, cx))
            .children(self.palette_overlay(window, cx))
;
        // 渲染成本打点（元素构建耗时；> 8ms 才报，避免日志噪音）。
        if std::env::var("BOT_PILOT_DEBUG").ok().as_deref() == Some("1") {
            let elapsed = render_started.elapsed();
            if elapsed.as_millis() >= 8 {
                let messages = self
                    .active_key()
                    .and_then(|key| self.chats.get(&key))
                    .map(|chat| chat.messages.len())
                    .unwrap_or(0);
                eprintln!(
                    "[perf] render {} ms (messages={messages})",
                    elapsed.as_millis()
                );
            }
        }
        root
            .children(self.me_card_overlay(cx))
            .children(self.detail_menu_overlay(window, cx))
    }
}

/// 进程启动时刻（首帧耗时基线；`BOT_PILOT_DEBUG=1` 时打印）。
static BOOT_AT: std::sync::OnceLock<std::time::Instant> = std::sync::OnceLock::new();

/// 读当前窗口几何（隐藏/最小化时 bounds 可能不可信，仍原样记录）。
fn current_geometry(window: &Window) -> Option<window_state::Geometry> {
    let bounds = window.bounds();
    let origin = bounds.origin;
    let size = bounds.size;
    Some(window_state::Geometry {
        x: f32::from(origin.x),
        y: f32::from(origin.y),
        width: f32::from(size.width),
        height: f32::from(size.height),
        maximized: window.is_maximized(),
        // 补偿由 `window_state::remember` 用首帧实测值覆盖。
        offset_x: 0.0,
        offset_y: 0.0,
    })
}

/// 性能测量钩子：`BOT_PILOT_FAKE_HISTORY=N` 时返回 N 条合成历史（不写库）。
fn fake_history_or(entries: Vec<backend::HistoryEntry>) -> Vec<backend::HistoryEntry> {
    match std::env::var("BOT_PILOT_FAKE_HISTORY")
        .ok()
        .and_then(|value| value.trim().parse::<usize>().ok())
    {
        Some(count) if count > 0 => {
            let now = time::now_ms();
            (0..count)
                .map(|index| {
                    let text = if index % 3 == 0 {
                        format!(
                            "合成消息 #{index}：长会话渲染开销测试。

- 列表项 A
- 列表项 B

| 列1 | 列2 |
| --- | --- |
| a | b |"
                        )
                    } else {
                        format!(
                            "合成消息 #{index}：这一段是普通段落，用来测试长会话的渲染开销与滚动表现。"
                        )
                    };
                    backend::HistoryEntry {
                        user: index % 2 == 0,
                        reasoning: false,
                        attachments: Vec::new(),
                        text,
                        tool: None,
                        member: None,
                        at: now - ((count - index) as u64) * 1000,
                    }
                })
                .collect()
        }
        _ => entries,
    }
}

/// 会话导出用的 Markdown（只取正文消息，工具/思考不导出）。
fn conversation_markdown(chat: &ChatState, title: &str) -> String {
    let mut lines = Vec::new();
    for message in &chat.messages {
        if message.kind != MsgKind::Text || message.text.trim().is_empty() {
            continue;
        }
        let who = match message.role {
            Role::User => i18n::t("你").to_string(),
            Role::Assistant => message
                .member
                .clone()
                .unwrap_or_else(|| title.to_string()),
        };
        lines.push(format!("**{who}：** {}", message.text.trim()));
    }
    if lines.is_empty() {
        String::new()
    } else {
        format!("# {title}\n\n{}", lines.join("\n\n"))
    }
}

/// 解析导出格式的 Markdown：`**你：** 文本` / `**Bot：** 文本`，空行保留在消息内。
fn parse_imported_markdown(text: &str) -> Vec<(bool, String)> {
    let marker = "：**";
    let mut out: Vec<(bool, String)> = Vec::new();
    let mut current: Option<(bool, String)> = None;
    for line in text.lines() {
        if let Some(rest) = line.strip_prefix("**")
            && let Some(position) = rest.find(marker)
        {
            if let Some(done) = current.take() {
                out.push(done);
            }
            let who = rest[..position].trim();
            let body = rest[position + marker.len()..].trim_start();
            current = Some((
                who == i18n::t("你") || who.eq_ignore_ascii_case("you"),
                body.to_string(),
            ));
            continue;
        }
        if let Some((_, body)) = current.as_mut() {
            if !body.is_empty() {
                body.push('\n');
            }
            body.push_str(line);
        }
    }
    if let Some(done) = current {
        out.push(done);
    }
    out.into_iter()
        .filter_map(|(user, text)| {
            let text = text.trim_end().to_string();
            (!text.is_empty()).then_some((user, text))
        })
        .collect()
}

/// 导出文件名：清掉 Windows 非法字符，空名回落会话。
fn export_file_name(title: &str) -> String {
    let sanitized: String = title
        .chars()
        .map(|ch| match ch {
            '\\' | '/' | ':' | '*' | '?' | '"' | '<' | '>' | '|' => '_',
            ch if ch.is_control() => '_',
            ch => ch,
        })
        .collect();
    let sanitized = sanitized.trim().trim_matches('.');
    let stem = if sanitized.is_empty() {
        "conversation"
    } else {
        sanitized
    };
    format!("{stem}.md")
}

/// 把 HistoryEntry 转成 UI 消息（History 事件与合成注入共用）。
fn history_messages(entries: Vec<backend::HistoryEntry>) -> Vec<Message> {
    entries
        .into_iter()
        .map(|entry| {
            let mut message = match entry.tool {
                Some(card) => Message::tool(card),
                None if entry.reasoning => {
                    Message::reasoning(entry.member.clone(), entry.text, false)
                }
                None => Message::text(
                    if entry.user { Role::User } else { Role::Assistant },
                    entry.text,
                    false,
                ),
            };
            message.attachments = entry
                .attachments
                .iter()
                .map(|attachment| attachment.file_name.clone())
                .collect();
            message.attachment_meta = entry.attachments;
            message.member = entry.member;
            if entry.at > 0 {
                message.at = entry.at;
            }
            message
        })
        .collect()
}

/// 把 gpui-kit 的默认主题色板换成微信深色，供 Dialog/Notification/Input 等组件使用。
/// 必须走 `Theme::update`（会同步 tokens 与 base theme）；直接改 global_mut 不会更新 Base。
fn configure_kit_theme(cx: &mut App) {
    use gpui::component::Theme;
    Theme::update(cx, |theme| {
        theme.background = gpui::Hsla::from(wechat_theme::chat_bg());
        theme.foreground = gpui::Hsla::from(wechat_theme::chat_title());
        theme.popover = gpui::Hsla::from(wechat_theme::panel_card_bg());
        theme.popover_foreground = gpui::Hsla::from(wechat_theme::chat_title());
        theme.border = gpui::Hsla::from(wechat_theme::composer_border());
        theme.input = gpui::Hsla::from(wechat_theme::composer_border());
        theme.primary = gpui::Hsla::from(wechat_theme::send_enabled());
        theme.primary_foreground = gpui::Hsla::from(wechat_theme::nav_text_active());
        theme.secondary = gpui::Hsla::from(wechat_theme::chip_bg());
        theme.secondary_foreground = gpui::Hsla::from(wechat_theme::chat_title());
        theme.muted = gpui::Hsla::from(wechat_theme::chip_bg());
        theme.muted_foreground = gpui::Hsla::from(wechat_theme::panel_text());
        theme.accent = gpui::Hsla::from(wechat_theme::list_hover());
        theme.accent_foreground = gpui::Hsla::from(wechat_theme::chat_title());
        theme.danger = gpui::Hsla::from(wechat_theme::nav_badge_bg());
        theme.danger_foreground = gpui::Hsla::from(wechat_theme::nav_text_active());
        theme.ring = gpui::Hsla::from(wechat_theme::send_enabled());
        theme.caret = gpui::Hsla::from(wechat_theme::chat_title());
        // 滚动条：浅色皮肤默认深色滑块，会像一条黑杠。
        theme.scrollbar = gpui::Hsla::from(gpui::rgba(0x00000000));
        theme.scrollbar_thumb = gpui::Hsla::from(wechat_theme::time_label());
        theme.scrollbar_thumb_hover = gpui::Hsla::from(wechat_theme::icon_strong());
        theme.font_family = wechat_theme::FONT_FAMILY.into();
        theme.font_size = px(13.);
    });
}

/// 发布包是 GUI 子系统：从 cmd/PowerShell 里直接跑 `--version` 时，先挂到父进程
/// 控制台并接回 `CONOUT$`，否则 println! 没有输出；父进程没有控制台（资源管理器
/// 双击）时什么都不做。标准句柄已经有效（管道/文件重定向）时不碰它们——挂控制台
/// 会把标准句柄换成控制台句柄，重定向的输出就丢了（2026-11-23 实测）。
#[cfg(all(windows, not(debug_assertions)))]
fn attach_parent_console() {
    use std::os::windows::io::AsRawHandle as _;
    use windows_sys::Win32::Foundation::INVALID_HANDLE_VALUE;
    use windows_sys::Win32::System::Console::{
        ATTACH_PARENT_PROCESS, AttachConsole, GetStdHandle, STD_ERROR_HANDLE, STD_OUTPUT_HANDLE,
        SetStdHandle,
    };

    let handle_ready = |kind: u32| {
        let handle = unsafe { GetStdHandle(kind) };
        !handle.is_null() && handle != INVALID_HANDLE_VALUE
    };
    if handle_ready(STD_OUTPUT_HANDLE) || handle_ready(STD_ERROR_HANDLE) {
        return;
    }
    unsafe {
        if AttachConsole(ATTACH_PARENT_PROCESS) == 0 {
            return;
        }
        for kind in [STD_OUTPUT_HANDLE, STD_ERROR_HANDLE] {
            if let Ok(console) = std::fs::OpenOptions::new().write(true).open("CONOUT$") {
                SetStdHandle(kind, console.as_raw_handle() as _);
                // 句柄要活到进程退出；--version 随后就 return，泄漏一个句柄无妨。
                std::mem::forget(console);
            }
        }
    }
}

#[cfg(not(all(windows, not(debug_assertions))))]
fn attach_parent_console() {}

fn main() {
    // 发布打包脚本用它核对构建期注入的版本（MODE_BOT_VERSION）是否真的进了二进制。
    if std::env::args_os().any(|arg| matches!(arg.to_str(), Some("--version" | "-V"))) {
        attach_parent_console();
        println!("Mode Chat {}", update::current_version());
        return;
    }
    let _ = BOOT_AT.set(std::time::Instant::now());
    // 主题偏好（深色/浅色）要在建窗口前读好，否则首帧会闪一下。
    theme::load_preference();
    // 微信皮肤置位；浅色/深色/跟随系统由 prefs 在 application run 里应用。
    // 崩溃先落盘（早于任何 UI/后台线程）：日志在试点状态目录，不碰产品数据。
    instance::install_panic_hook(&instance::state_dir());
    // 单实例：第二个进程只把已有窗口置前然后退出（不建第二份会话/第二个窗口）。
    let _instance_lock = match instance::acquire(&instance::state_dir().join("pilot-instance")) {
        instance::Acquire::Acquired(lock) => Some(lock),
        instance::Acquire::AlreadyRunning => {
            eprintln!("[instance] 已有试点实例在运行，已请求置前并退出");
            instance::focus_existing_window("Mode Chat");
            return;
        }
        instance::Acquire::Failed(error) => {
            // 锁机制失败不阻断启动（只读浏览仍可用），但明确告警。
            eprintln!("[instance] 单实例锁获取失败（继续启动）：{error}");
            None
        }
    };

    gpui::application().run(|cx: &mut App| {
        // gpui-kit 的主题/组件/对话框状态必须先初始化，否则组件拿不到 theme。
        gpui::init(cx);
        // 主题（浅色/深色/跟随系统）先落到两套 token，再同步 gpui-kit；
        // 组件默认 Light，必须显式切换，否则 TextView/代码块与皮肤不一致。
        let saved_theme = load_theme_pref();
        let saved_light = theme_light_for(&saved_theme);
        theme::set_light_runtime(saved_light);
        wechat_theme::set_light(saved_light);
        gpui::component::Theme::change(
            if saved_light {
                gpui::component::ThemeMode::Light
            } else {
                gpui::component::ThemeMode::Dark
            },
            None,
            cx,
        );
        configure_kit_theme(cx);
        // Geist 是原版 UI 的主字体（SIL OFL，随包 assets/fonts）。DirectWrite 只认 TTF/OTF。
        let _ = cx.text_system().add_fonts(vec![std::borrow::Cow::Borrowed(include_bytes!(
            "../assets/fonts/Geist-Variable.ttf"
        ))]);
        if std::env::var("BOT_PILOT_DEBUG").ok().as_deref() == Some("1") {
            let has_geist = cx
                .text_system()
                .all_font_names()
                .iter()
                .any(|name| name.contains("Geist"));
            eprintln!("[fonts] Geist loaded: {has_geist}");
        }
        cx.bind_keys([
            // 命令面板导航用 Tab/Shift+Tab：上下方向键被 TextInput 的光标移动绑定占用
            // （实测 Palette 上下文抢不过它），Tab 在全局没有绑定，不会打架。
            KeyBinding::new("tab", PaletteNext, Some("Palette")),
            KeyBinding::new("shift-tab", PalettePrev, Some("Palette")),
            // Windows 上 Tab 会被平台层先吃掉做焦点遍历，业务绑定收不到；
            // 上下键才是可靠路径（命令面板是单行输入，不抢 ↑/↓）。
            KeyBinding::new("up", PalettePrev, Some("Palette")),
            KeyBinding::new("down", PaletteNext, Some("Palette")),
            KeyBinding::new("enter", PaletteSubmit, Some("Palette")),
            // Composer 的 Enter/Shift+Enter 由 gpui-kit Textarea 的 submit_on_enter 处理。
            // 无障碍底线（P4-6）：Esc 关浮层、Ctrl+N/K/, 覆盖主要入口，全键盘可达。
            // 注意：请求焦点在 Composer 时 Esc 也在这里处理（输入法组合态的取消由
            // 平台层先行处理，P3-7 人工验收会复核是否会误关浮层）。
            KeyBinding::new("escape", CloseOverlay, None),
            // ⋯ 菜单：焦点在菜单容器上时 ↑/↓ 选择、Enter 执行。
            KeyBinding::new("up", DetailMenuPrev, Some("DetailMenu")),
            KeyBinding::new("down", DetailMenuNext, Some("DetailMenu")),
            KeyBinding::new("enter", DetailMenuConfirm, Some("DetailMenu")),
            // 搜索历史：Tab/Shift+Tab 选命中、Enter 跳转（↑/↓ 会被输入框吃掉）。
            KeyBinding::new("tab", FindNext, Some("Find")),
            KeyBinding::new("shift-tab", FindPrev, Some("Find")),
            KeyBinding::new("up", FindPrev, Some("Find")),
            KeyBinding::new("down", FindNext, Some("Find")),
            KeyBinding::new("enter", FindOpen, Some("Find")),
            // @ 候选：焦点在 composer 上时 Tab/Shift+Tab 选择（Enter 在 on_send 里插入）。
            KeyBinding::new("tab", MentionNext, Some("Composer")),
            KeyBinding::new("shift-tab", MentionPrev, Some("Composer")),
            // 按钮焦点链：Tab 在可聚焦控件间移动，Enter 激活当前控件。
            KeyBinding::new("tab", FocusNext, None),
            KeyBinding::new("shift-tab", FocusPrev, None),
            KeyBinding::new("enter", ActivateTabStop, Some("TabStop")),
            KeyBinding::new("ctrl-n", NewSessionShortcut, None),
            KeyBinding::new("ctrl-k", SearchShortcut, None),
            KeyBinding::new("ctrl-,", SettingsShortcut, None),
            // 键盘操作主循环：换条目 / 处理审批（Tab 焦点链见 README 已知限制）。
            KeyBinding::new("alt-down", SelectNextItem, None),
            KeyBinding::new("alt-up", SelectPrevItem, None),
            KeyBinding::new("alt-a", ApproveAllow, None),
            KeyBinding::new("alt-d", ApproveDeny, None),
            KeyBinding::new("ctrl-b", NewBotShortcut, None),
            KeyBinding::new("ctrl-e", EditBotShortcut, None),
            KeyBinding::new("ctrl-g", NewChannelShortcut, None),
            KeyBinding::new("ctrl-f", FindShortcut, None),
            KeyBinding::new("ctrl-p", PaletteShortcut, None),
            // 对话框里 Enter 提交（输入框是单行/多行都用 Shift+Enter 换行）。
            KeyBinding::new("enter", SubmitDialog, Some("Dialog")),
        ]);

        // 窗口几何持久化：上次的位置/大小/最大化；没有记录时用默认位置。
        // 原点要加 `restore_origin` 的补偿（gpui 的 border offset 换算在 DWM 下不对称，
        // 不补的话每次重启窗口上移 4px）。
        let saved = window_state::load();
        let requested_origin = match &saved {
            Some(geometry) => window_state::restore_origin(geometry),
            None => (120.0, 90.0),
        };
        let bounds = match saved {
            Some(geometry) => Bounds::new(
                Point::new(px(requested_origin.0), px(requested_origin.1)),
                size(px(geometry.width), px(geometry.height)),
            ),
            None => Bounds::new(
                Point::new(px(requested_origin.0), px(requested_origin.1)),
                size(px(1100.), px(720.)),
            ),
        };
        let window_bounds = match saved {
            Some(geometry) if geometry.maximized => WindowBounds::Maximized(bounds),
            _ => WindowBounds::Windowed(bounds),
        };
        window_state::set_restore_request(requested_origin);
        window_state::spawn_autosave();
        let options = WindowOptions {
            window_bounds: Some(window_bounds),
            titlebar: Some(TitlebarOptions {
                title: Some("Mode Chat".into()),
                appears_transparent: true,
                traffic_light_position: None,
            }),
            window_min_size: Some(size(px(WINDOW_MIN_W), px(WINDOW_MIN_H))),
            ..Default::default()
        };

        // gpui-kit 的 Root 包一层：Dialog/Sheet/Notification/Popover 等组件
        // 依赖 Root 的 overlay 层；自绘浮层不受影响。
        gpui::open_window(options, cx, |_window, cx| {
            cx.new(|cx| {
                let mut app = PilotApp::new(cx);
                app.schedule_auto_update(cx);
                app
            })
        })
        .expect("failed to open GPUI shell window");
        cx.activate(true);
    });

    std::thread::sleep(Duration::from_millis(50));
}

#[cfg(test)]
mod compose_tests {
    use super::compose_with_quote;

    #[test]
    fn quote_is_prefixed_and_trimmed() {
        let quoted = compose_with_quote(
            "OK",
            Some(("你".to_string(), "  多行
引用  内容  ".to_string())),
        );
        assert!(quoted.starts_with("引用 你：多行 引用 内容"), "{quoted}");
        assert!(quoted.ends_with("OK"), "{quoted}");
        // 无引用时原样返回
        assert_eq!(compose_with_quote("OK", None), "OK");
        // 空引用体不产生引用块
        assert_eq!(
            compose_with_quote("OK", Some(("你".to_string(), "   ".to_string()))),
            "OK"
        );
        // 超长引用裁剪到 200 字
        let long = "x".repeat(400);
        let quoted = compose_with_quote("OK", Some(("你".to_string(), long)));
        let body_line = quoted.lines().next().unwrap_or_default();
        assert!(
            body_line.chars().count() <= "引用 你：".chars().count() + 200,
            "引用体过长：{}",
            body_line.chars().count()
        );
    }
}

