#[cfg(test)]
mod image_transcode_tests {
    use super::*;

    #[test]
    fn bmp_transcodes_to_png() {
        let image = image::RgbaImage::from_pixel(2, 2, image::Rgba([220, 30, 30, 255]));
        let mut bmp = std::io::Cursor::new(Vec::new());
        image::DynamicImage::ImageRgba8(image)
            .write_to(&mut bmp, image::ImageFormat::Bmp)
            .expect("encode bmp");
        let png = transcode_image_to_png(bmp.get_ref()).expect("transcode");
        assert_eq!(&png[..8], b"\x89PNG\r\n\x1a\n");
        let decoded = image::load_from_memory(&png).expect("decode png");
        assert_eq!(decoded.to_rgba8().get_pixel(0, 0).0[0], 220);
    }
}

#[cfg(test)]
mod turn_summary_tests {
    use super::*;

    fn tool(name: &str, input: &str) -> Message {
        Message::tool(backend::ToolCard {
            call_id: format!("{name}-call"),
            name: name.to_string(),
            state: "done".to_string(),
            title: name.to_string(),
            detail: String::new(),
            input: input.to_string(),
            details: String::new(),
            images: Vec::new(),
        })
    }

    #[test]
    fn counts_unique_files_and_line_stats() {
        let messages = vec![
            Message::text(Role::User, "hi", false),
            tool(
                "write",
                r#"{"path":"a.txt","content":"x\ny"}"#,
            ),
            tool(
                "edit",
                r#"{"path":"a.txt","edits":[{"oldText":"y","newText":"z"}]}"#,
            ),
            tool("read", r#"{"path":"a.txt"}"#),
        ];
        assert_eq!(turn_edit_summary(&messages), Some((1, 3, 1)));
    }

    #[test]
    fn parses_exported_markdown() {
        let text = "# 会话\n\n**你：** 第一行\n第二行\n\n**Bot：** 回复";
        assert_eq!(
            parse_imported_markdown(text),
            vec![
                (true, "第一行\n第二行".to_string()),
                (false, "回复".to_string())
            ]
        );
    }

    #[test]
    fn export_name_is_sanitized() {
        assert_eq!(export_file_name("a/b:c*?"), "a_b_c__.md");
        assert_eq!(export_file_name("  "), "conversation.md");
    }

    #[test]
    fn ignores_previous_turns() {
        let messages = vec![
            tool(
                "write",
                r#"{"path":"old.txt","content":"a"}"#,
            ),
            Message::text(Role::User, "next", false),
            tool("read", r#"{"path":"a.txt"}"#),
        ];
        assert_eq!(turn_edit_summary(&messages), None);
    }
}

